const a={"les-n2-u01-01":{pedagogical_framework:{what:{summary:"Menguasai pola 〜に際して (pada saat momen penting peresmian/memulai) dan 〜にあたって (dalam rangka persiapan acara besar) untuk situasi profesional resmi.",canDo:"Bisa menyampaikan laporan persiapan jelang peluncuran operasional, sambutan resmi peresmian, dan instruksi keselamatan dengan ragam formal.",targetPatterns:["V-dict / N + に際して (pada saat momen penting / ketika resmi)","V-dict / N + にあたって (menjelang / dalam rangka persiapan acara besar)"],coreVocabSample:["稼働【かどう】","点検【てんけん】","準備【じゅんび】","企画【きかく】","対応【たいおう】","検討【けんとう】","安全【あんぜん】","進捗【しんちょく】"]},sensei_context:{sceneIntro:"Pabrik manufaktur presisi Kanagawa. Tanaka (Supervisor) meninjau persiapan akhir bersama Budi sebelum pengoperasian perdana lini produksi otomatis.",dailyMission:'Mampu menjelaskan kesiapan operasional menggunakan pola "ni saishite" dengan ragam formal korporat yang santun dan lugas.',whyOrder:"Pola ini menjadi gerbang N2 untuk membuka wacana formal; transisi dari kalimat deskriptif biasa menuju ujaran resmi berbobot institusi."},cultural_notes:{title:"Protokol Peluncuran Fasilitas Baru (稼働式 - Kadoushiki) di Industri Jepang",etiquette:"Dalam dunia industri Jepang, peluncuran lini baru selalu diawali briefing keselamatan resmi. Menggunakan 〜に際して menunjukkan rasa hormat terhadap momentum penting perusahaan.",taboos:"Jangan gunakan 〜に際して untuk rutinitas harian sepele (seperti makan siang atau mandi); pola ini dikhususkan bagi momen penting formal."},pronunciation_tips:{title:'Intonasi Stabil pada Frasa Formal "ni saishite"',moraNote:"Frasa ni-sa-i-shi-te dilafalkan dengan nada heiban datar tanpa hentakan tinggi mendadak pada mora sa atau shi.",soundTip:"Artikulasikan vokal rangkap [ai] pada sa-i secara jelas tanpa memotong mora."},common_pitfalls:[{title:"Tertukar Antara 〜に際して (Momen Resmi) vs 〜ときに (Waktu Biasa Kasual)",caseScenario:"Menggunakan pola kasual saat menyampaikan briefing pembukaan lini produksi di hadapan manajemen.",pitfallWarning:'"新【あたら】しい ラインを 動【うご】かす ときに、注意【ちゅうい】してください。"',rightSolution:'"新【あたら】しい ラインの 稼働【かどう】に 際【さい】して、安全【あんぜん】確認【かくにん】を 徹底【てってい】してください。"',explanation:"〜に際して memberikan bobot keseriusan dan formalitas resmi yang wajib digunakan dalam konteks operasional industri."},{title:"Salah Bentuk Konjugasi Sebelum 〜に際して",caseScenario:'Memasukkan bentuk lampau ta-kei sebelum pola: "kadou shita ni saishite".',pitfallWarning:'"稼働【かどう】した に 際【さい】して、点検【てんけん】しました。"',rightSolution:'"稼働【かどう】に 際【さい】して、点検【てんけん】いたしました。"',explanation:"Pola 〜に際して hanya menerima kata benda (N) atau kata kerja bentuk kamus (V-dict), bukan bentuk lampau."}],who_and_when:{situational_context:"Rapat koordinasi lapangan, sambutan pembukaan proyek, atau briefing keselamatan sebelum uji coba mesin.",social_relations:"Komunikasi formal profesional antara supervisor kerja dan staf teknis.",when_not_to_use:"Hindari pemakaian dalam percakapan santai di luar konteks formal kerja."},scenario:{title:"Inspeksi Final Sebelum Pengoperasian Lini Produksi",setting:"Ruang kendali pabrik Kanagawa, pukul 08.30 pagi.",narrative:"Tanaka memeriksa kesiapan Budi dan tim teknis menjelang pengoperasian perdana lini perakitan otomatis."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、新【あたら】しい 自動【じどう】化【か】ラインの 稼働【かどう】に 際【さい】して、安全【あんぜん】確認【かくにん】の 進捗【しんちょく】は どうなっていますか？",furigana:"ブディさん、新しい 自動化ラインの 稼働に 際して、安全確認の 進捗は どうなっていますか？",romaji:"Budi-san, atarashii jidouka rain no kadou ni saishite, anzen kakunin no shinchoku wa dou natte imasu ka?",idText:"Budi, menjelang pengoperasian lini otomatisasi baru, bagaimana progres pemeriksaan keselamatannya?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、田中【たなか】さん！ 稼働【かどう】に 際【さい】して、全【すべ】ての センサーの 点検【てんけん】を 完了【かんりょう】いたしました。マニュアルの 注意【ちゅうい】事項【じこう】も 全員【ぜんいん】に 周知【しゅうち】しております。",furigana:"はい、田中さん！ 稼働に 際して、全ての センサーの 点検を 完了いたしました。マニュアルの 注意事項も 全員に 周知しております。",romaji:"Hai, Tanaka-san! Kadou ni saishite, subete no sensaa no tenken o kanryou itashimashita. Manyuaru no chuuijikou mo zenin ni shuuchi shite orimasu.",idText:"Ya, Tanaka-san! Menjelang pengoperasian, kami telah menuntaskan inspeksi seluruh sensor. Poin-poin perhatian pada manual juga telah disosialisasikan ke semua staf."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"素早【すばや】い 対応【たいおう】ですね。新【あたら】しい 設備【せつび】の 導入【どうにゅう】に 伴【ともな】って、予期【よき】せぬ エラーが 起【お】こる 可能性【かのうせい】も ありますから、試運転【しうんてん】中【ちゅう】も 慎重【しんちょう】に 監視【かんし】してください。",furigana:"素早い 対応ですね。新しい 設備の 導入に 伴って、予期せぬ エラーが 起こる 可能性も ありますから、試運転中も 慎重に 監視してください。",romaji:"Subayai taiou desu ne. Atarashii setsubi no dounyuu ni tomonatte, yokisenu eraa ga okoru kanousei mo arimasu kara, shiuntenchuu mo shinchou ni kanshi shite kudasai.",idText:"Penanganan yang cepat. Seiring pengenalan fasilitas baru, ada kemungkinan terjadi galat yang tak terduga, jadi tolong awasi secara saksama juga selama uji coba."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 些細【ささい】な 異常【いじょう】も 見逃【みのが】さず、チームで リアルタイムに 連携【れんけい】して 報告【ほうこく】いたします。",furigana:"承知いたしました！ 些細な 異常も 見逃さず、チームで リアルタイムに 連携して 報告いたします。",romaji:"Shouchi itashimashita! Sasaina ijou mo minogasazu, chiimu de riarutaimu ni renkei shite houkoku itashimasu.",idText:"Dimengerti! Kami tidak akan melewatkan kejanggalan sekecil apa pun dan akan berkoordinasi secara langsung dengan tim untuk melapor."}],vocab_breakdown:[{id:"vg-n2-00051",word:"把握する",reading:"はあくする",romaji:"haaku suru",meaning:"memahami/menguasai sepenuhnya",pos:"verb-suru",nuance:"Bukan sekadar 'mengerti' biasa — 把握する menyiratkan pemahaman yang menyeluruh dan menguasai situasi secara aktif. Sering dipakai dalam konteks analisis data, briefing, atau pengambilan keputusan.",particleTip:"Kolokasi alami: 〜を 把握する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"現状をしっかり把握してから、対策を立てましょう。",furigana:"現状をしっかり把握してから、対策を立てましょう。",romaji:"haaku suru",idText:"Mari kita susun strategi setelah benar-benar memahami situasi saat ini."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"ハアク￣"}},{id:"vg-n2-00052",word:"検討する",reading:"けんとうする",romaji:"kentou suru",meaning:"mempertimbangkan; mengkaji",pos:"verb-suru",nuance:"Dalam konteks bisnis Jepang, 「検討します」 sering terdengar sebagai penolakan halus ('akan dipertimbangkan') tanpa komitmen. Perlu dibedakan dari 「考えます」 yang lebih kasual.",particleTip:"Kolokasi alami: 〜を 検討する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"ご提案については、社内で検討いたします。",furigana:"ご提案については、社内で検討いたします。",romaji:"kentou suru",idText:"Mengenai proposal Anda, kami akan mengkajinya secara internal."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ケントウ￣"}},{id:"vg-n2-00053",word:"実施する",reading:"じっしする",romaji:"jisshi suru",meaning:"melaksanakan; menerapkan",pos:"verb-suru",nuance:"Dipakai untuk pelaksanaan rencana, kebijakan, atau aturan yang sudah ditetapkan sebelumnya. Lebih resmi dari 「やる」 dan mengandung nuansa 'sesuai prosedur'.",particleTip:"Kolokasi alami: 〜を 実施する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"新しい政策が来月から実施される。",furigana:"新しい政策が来月から実施される。",romaji:"jisshi suru",idText:"Kebijakan baru akan diterapkan mulai bulan depan."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"ジッシ￣"}},{id:"vg-n2-00054",word:"対応する",reading:"たいおうする",romaji:"taiou suru",meaning:"merespons; menangani; sesuai dengan",pos:"verb-suru",nuance:"Multifungsi: bisa berarti 'merespons situasi/pelanggan', bisa juga berarti 'kompatibel dengan' (misal: スマホに対応したアプリ). Dalam layanan pelanggan, 対応 adalah kata kunci yang sangat umum.",particleTip:"Kolokasi alami: 〜を 対応する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"お客様のクレームに迅速に対応しました。",furigana:"お客様のクレームに迅速に対応しました。",romaji:"taiou suru",idText:"Kami merespons keluhan pelanggan dengan cepat."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"タイオウ￣"}},{id:"vg-n2-00055",word:"提供する",reading:"ていきょうする",romaji:"teikyou suru",meaning:"menyediakan; menawarkan; memberikan",pos:"verb-suru",nuance:"Digunakan ketika seseorang atau lembaga secara aktif menawarkan/menyediakan sesuatu kepada pihak lain. Lebih formal dari 「あげる」 dan sering dipakai dalam konteks layanan, informasi, atau produk.",particleTip:"Kolokasi alami: 〜を 提供する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"当社は高品質なサービスを提供しております。",furigana:"当社は高品質なサービスを提供しております。",romaji:"teikyou suru",idText:"Perusahaan kami menyediakan layanan berkualitas tinggi."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"テイキョウ￣"}},{id:"vg-n2-00056",word:"達成する",reading:"たっせいする",romaji:"tassei suru",meaning:"mencapai; mewujudkan (tujuan/target)",pos:"verb-suru",nuance:"Selalu berkonotasi positif — mencapai sesuatu yang sudah diinginkan/ditargetkan sebelumnya. Berbeda dari 「実現する」 yang lebih menekankan 'terwujud/menjadi kenyataan'.",particleTip:"Kolokasi alami: 〜を 達成する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"チームは今年の目標を達成した。",furigana:"チームは今年の目標を達成した。",romaji:"tassei suru",idText:"Tim berhasil mencapai target tahun ini."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"タッセイ￣"}},{id:"vg-n2-00057",word:"向上する",reading:"こうじょうする",romaji:"koujou suru",meaning:"meningkat; berkembang; membaik",pos:"verb-suru",nuance:"Menandakan peningkatan kualitas atau kemampuan secara gradual dan positif. Lebih sering dipakai untuk kemampuan/kinerja/kualitas daripada jumlah (untuk jumlah lebih tepat 増加する).",particleTip:"Kolokasi alami: 〜を 向上する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"練習のおかげで日本語の実力が向上した。",furigana:"練習のおかげで日本語の実力が向上した。",romaji:"koujou suru",idText:"Berkat latihan, kemampuan bahasa Jepangku meningkat."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"コウジョウ￣"}},{id:"vg-n2-00058",word:"確保する",reading:"かくほする",romaji:"kakuho suru",meaning:"memastikan ketersediaan; mengamankan; mendapatkan",pos:"verb-suru",nuance:"Mengandung nuansa 'mengamankan sesuatu agar tidak hilang atau kurang'. Berbeda dari sekadar 「もらう」 atau 「得る」 karena ada unsur kesengajaan dan pencegahan risiko.",particleTip:"Kolokasi alami: 〜を 確保する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"会議室を事前に確保しておいてください。",furigana:"会議室を事前に確保しておいてください。",romaji:"kakuho suru",idText:"Tolong amankan ruang rapat terlebih dahulu."},pitch:{pattern:1,category:"atamadaka",mora_count:3,downstep_mora:1,contour:"カ＼クホ"}}],explanations:[{id:"exp-1",grammarId:"gn2-00003",title:"Pola: 〜に際して",formula:"V-dict / N + に際して",meaning:"pada saat ... / ketika (momen penting) ...",nuanceNotes:"〜に際して digunakan untuk momen penting atau formal seperti upacara, awal kegiatan, atau situasi khusus.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に際して",idText:"pada saat ... / ketika (momen penting) ..."}],examples:[{jp:"入学に際して、学長が挨拶をした。",romaji:"",idText:"Pada saat masuk sekolah, rektor memberikan sambutan."},{jp:"契約に際して、注意事項をよく読んでください。",romaji:"",idText:"Pada saat kontrak, bacalah dengan teliti hal-hal yang perlu diperhatikan."}]},{id:"exp-2",grammarId:"gn2-00004",title:"Pola: 〜にあたって",formula:"V-dict / N + にあたって",meaning:"pada saat ... / dalam rangka ...",nuanceNotes:"〜にあたって hampir sama dengan に際して tetapi lebih menekankan persiapan atau tindakan menjelang suatu momen.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜にあたって",idText:"pada saat ... / dalam rangka ..."}],examples:[{jp:"旅行にあたって、保険に加入した。",romaji:"",idText:"Dalam rangka perjalanan, saya mengambil asuransi."},{jp:"発表にあたって、資料をまとめた。",romaji:"",idText:"Menjelang presentasi, saya menyusun bahan-bahan."}]},{id:"exp-3",grammarId:"gn2-00005",title:"Pola: 〜に伴って",formula:"V-dict / N + に伴って",meaning:"seiring dengan ... / bersamaan dengan ...",nuanceNotes:"〜に伴って menyatakan bahwa dua perubahan terjadi secara bersamaan dan saling berkaitan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に伴って",idText:"seiring dengan ... / bersamaan dengan ..."}],examples:[{jp:"経済の発展に伴って、生活水準が上がった。",romaji:"",idText:"Seiring perkembangan ekonomi, taraf hidup meningkat."},{jp:"年齢に伴って、体力が落ちる。",romaji:"",idText:"Seiring bertambahnya usia, stamina menurun."}]},{id:"exp-4",grammarId:"gn2-00023",title:"Pola: 〜ものだ",formula:"V-dict / V-ない + ものだ",meaning:"(1) memang seharusnya ... (2) dulu sering ...",nuanceNotes:"〜ものだ: (1) mengungkapkan kebenaran umum atau norma; (2) mengenang kebiasaan di masa lalu.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ものだ",idText:"(1) memang seharusnya ... (2) dulu sering ..."}],examples:[{jp:"人は誰でも間違えるものだ。",romaji:"",idText:"Memang sudah sewajarnya manusia berbuat salah."},{jp:"子供の頃、よくここで遊んだものだ。",romaji:"",idText:"Waktu kecil, saya dulu sering bermain di sini."}]},{id:"exp-5",grammarId:"gn2-00041",title:"Pola: 〜に従って / 〜に従い",formula:"V-dict / N + に従って / に従い",meaning:"sesuai dengan ... / mengikuti ... / seiring ...",nuanceNotes:"〜に従って memiliki dua makna: (1) mengikuti aturan, instruksi, atau otoritas tertentu; (2) seiring perubahan A, B pun ikut berubah secara proporsional.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に従って / 〜に従い",idText:"sesuai dengan ... / mengikuti ... / seiring ..."}],examples:[{jp:"規則に従って行動してください。",romaji:"",idText:"Mohon bertindak sesuai dengan peraturan."},{jp:"時代に従って、働き方も変わった。",romaji:"",idText:"Seiring perkembangan zaman, cara bekerja pun berubah."},{jp:"医師の指示に従い、薬を飲んでいます。",romaji:"",idText:"Saya minum obat mengikuti petunjuk dokter."}]},{id:"exp-6",grammarId:"gn2-00095",title:"Pola: 〜を皮切りに",formula:"N + を皮切りに / を皮切りとして",meaning:"diawali dengan ... / dimulai dari ... (sebagai pembuka serangkaian)",nuanceNotes:"〜を皮切りに menyatakan bahwa X menjadi titik awal atau pembuka dari serangkaian kejadian atau tindakan yang menyusul setelahnya.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜を皮切りに",idText:"diawali dengan ... / dimulai dari ... (sebagai pembuka serangkaian)"}],examples:[{jp:"東京を皮切りに、全国ツアーが幕を開けた。",romaji:"",idText:"Dimulai dari Tokyo, tur nasional pun resmi dimulai."},{jp:"この商品のヒットを皮切りに、次々と新製品が発売された。",romaji:"",idText:"Dimulai dari keberhasilan produk ini, produk-produk baru pun bermunculan satu per satu."}]},{id:"exp-7",grammarId:"gn2-00102",title:"Pola: 〜にそって / 〜に沿って",formula:"N + に沿って / に沿った (+ N)",meaning:"mengikuti / selaras dengan / sepanjang ...",nuanceNotes:"〜に沿って menyatakan bahwa sesuatu dilakukan mengikuti jalur, rencana, pedoman, atau arah yang disebutkan. Bisa bermakna literal (mengikuti jalan/sungai) maupun figuratif (mengikuti rencana).",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜にそって / 〜に沿って",idText:"mengikuti / selaras dengan / sepanjang ..."}],examples:[{jp:"川に沿って歩いていくと、古い橋が見えてきます。",romaji:"",idText:"Jika berjalan mengikuti sungai, Anda akan melihat sebuah jembatan tua."},{jp:"計画に沿ってプロジェクトを進めてください。",romaji:"",idText:"Tolong jalankan proyek sesuai dengan rencana yang telah dibuat."}]},{id:"exp-8",grammarId:"gn2-00106",title:"Pola: 〜に先立って",formula:"N / V-dict + に先立って / に先立ち",meaning:"sebelum ... / mendahului ... / sebagai persiapan menjelang ...",nuanceNotes:"〜に先立って menyatakan bahwa suatu tindakan atau persiapan dilakukan sebelum kejadian besar atau penting yang disebutkan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に先立って",idText:"sebelum ... / mendahului ... / sebagai persiapan menjelang ..."}],examples:[{jp:"式典に先立って、リハーサルが行われた。",romaji:"",idText:"Sebelum upacara, gladi resik pun dilaksanakan."},{jp:"製品発売に先立ち、プレスリリースが配布された。",romaji:"",idText:"Mendahului peluncuran produk, siaran pers telah dibagikan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "稼働 (かどう)" dalam industri manufaktur?',sentencePrompt:'Istilah "稼働 (かどう)" dalam operasional pabrik bermakna:',options:["Pengoperasian atau berjalannya mesin/fasilitas","Pemberhentian darurat sistem","Pembongkaran gedung pabrik","Pemberian sanksi kelalaian kerja"],correctAnswer:"Pengoperasian atau berjalannya mesin/fasilitas",explanation:'"稼働 (かどう)" bermakna mesin atau fasilitas industri yang aktif bekerja/beroperasi.',diagnosticFeedback:{"Pemberhentian darurat sistem":"Salah: Pemberhentian darurat adalah 緊急停止 (kinkyuu teishi).","Pembongkaran gedung pabrik":"Salah: Pembongkaran fasilitas adalah 解体 (kaitai).","Pemberian sanksi kelalaian kerja":"Salah: Sanksi disiplin adalah 処罰 (shobatsu) atau 懲戒 (choukai)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat rumpang berikut dengan partikel penghubung yang tepat untuk menyatakan momen peresmian resmi:",sentencePrompt:"新【しん】工場【こうじょう】の 建設【けんせつ】_____、周辺【しゅうへん】住民【じゅうみん】への 説明会【せつめいかい】が 行【おこな】われた。",options:["に際して","に反して","によって","にすぎず"],correctAnswer:"に際して",explanation:"Konteks pembangunan pabrik baru adalah momen resmi penting, sehingga pola yang tepat adalah 〜に際して (pada saat/menjelang).",diagnosticFeedback:{に反して:'Salah: に反して bermakna "bertolak belakang dengan ekspektasi", tidak logis di kalimat ini.',によって:"Salah: によって menyatakan penyebab atau metode, bukan momen penanda peristiwa formal.",にすぎず:'Salah: にすぎず bermakna "hanyalah tidak lebih dari", merendahkan skala peristiwa.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Kalimat Alami): Manakah kalimat yang menggunakan kaidah 〜に際して secara tepat dan gramatikal?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["契約【けいやく】に際して、注意事項【ちゅういじこう】をよく読んでください。","昼ご飯【ひるごはん】を食べたに際して、手を洗いました。","契約【けいやく】に際してでした、注意事項を読みます。","契約【けいやく】に際したい、注意事項を読みました。"],correctAnswer:"契約【けいやく】に際して、注意事項【ちゅういじこう】をよく読んでください。",explanation:"Pola 〜に際して tepat disambungkan dengan kata benda 契約 (kontrak) untuk momen resmi.",diagnosticFeedback:{"昼ご飯【ひるごはん】を食べたに際して、手を洗いました。":"Kekeliruan Konteks: Makan siang adalah aktivitas harian sepele, tidak boleh menggunakan に際して (cukup gunakan ときに).","契約【けいやく】に際してでした、注意事項を読みます。":"Kekeliruan Sintaksis: Bentuk に際してでした tidak gramatikal di posisi penghubung klausa.","契約【けいやく】に際したい、注意事項を読みました。":"Kekeliruan Morfologi: に際して tidak memiliki bentuk keinginan *に際したい."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat pengumuman resmi yang padu:",sentencePrompt:"Susunlah frasa-frasa berikut agar membentuk kalimat yang gramatikal:",options:["新製品の 発売に際して、 万全の 品質チェックを 行いました。","万全の 品質チェックを 新製品の 発売に際して、 行いました。","発売に際して、 行いました。 新製品の 万全の 品質チェックを","行いました。 万全の 品質チェックを 新製品の 発売に際して、"],correctAnswer:"新製品の 発売に際して、 万全の 品質チェックを 行いました。",explanation:"Struktur alami: Klausa keterangan waktu (新製品の発売に際して) + Objek (万全の品質チェックを) + Predikat (行いました).",diagnosticFeedback:{"万全の 品質チェックを 新製品の 発売に際して、 行いました。":"Kekeliruan Urutan: Menaruh objek sebelum klausa keterangan waktu membuat ritme kalimat kaku.","発売に際して、 行いました。 新製品の 万全の 品質チェックを":"Kekeliruan Posisi Predikat: Predikat kata kerja ditaruh di tengah kalimat sebelum objeknya disebutkan.","行いました。 万全の 品質チェックを 新製品の 発売に際して、":"Kekeliruan Struktur Kalimat: Predikat diletakkan di paling depan melanggar struktur SOV bahasa Jepang."},tokens:["新製品の","発売に際して、","万全の品質チェックを","行いました。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Respons Profesional): Saat supervisor Tanaka menginstruksikan: 「試運転【しうんてん】中【ちゅう】も 慎重【しんちょう】に 監視【かんし】してください」, bagaimana respons terbaik Anda?",sentencePrompt:"Pilihlah respons yang paling santun dan menunjukkan komitmen kerja profesional:",options:["承知【しょうち】いたしました！ 些細【ささい】な 異常【いじょう】も 見逃【みのが】さず、リアルタイムに 連携【れんけい】して 報告【ほうこく】いたします。","夜勤【やきん】の 交代【こうたい】時間【じかん】が 近【ちか】いので、後任【こうにん】の スタッフに 丸投【まるな】げして 帰宅【きたく】します。","今日【きょう】は 疲【つか】れたので、計器【けいき】の 数値【すうち】を 適当【てきとう】に 眺【なが】めて 済【す】ませます。","トラブルが 起【お】きたら 始末【しまつ】書【しょ】を 書【か】くのが 面倒【めんどう】なので、機械【きかい】の 電源【でんげん】を 抜【ぬ】いて 放置【ほうち】します。"],correctAnswer:"承知【しょうち】いたしました！ 些細【ささい】な 異常【いじょう】も 見逃【みのが】さず、リアルタイムに 連携【れんけい】して 報告【ほうこく】いたします。",explanation:"Jawaban ini mencerminkan etika Hourensou yang sigap, tanggap, dan bertanggung jawab penuh di lingkungan kerja presisi Jepang.",diagnosticFeedback:{"夜勤【やきん】の 交代【こうたい】時間【じかん】が 近【ちか】いので、後任【こうにん】の スタッフに 丸投【まるな】げして 帰宅【きたく】します。":"Lepas Tangan: Melempar tanggung jawab pemantauan mesin tanpa serah terima resmi membahayakan keselamatan lini produksi.","今日【きょう】は 疲【つか】れたので、計器【けいき】の 数値【すうち】を 適当【てきとう】に 眺【なが】めて 済【す】ませます。":"Sikap Ceroboh: Mengabaikan pemantauan indikator presisi dan bekerja asal-asalan sangat fatal dalam keselamatan manufaktur.","トラブルが 起【お】きたら 始末【しまつ】書【しょ】を 書【か】くのが 面倒【めんどう】なので、機械【きかい】の 電源【でんげん】を 抜【ぬ】いて 放置【ほうち】します。":"Kriminal Sabotase: Mematikan mesin pabrik sembarangan dan meninggalkan pos kerja melanggar kepatuhan industri berat."}}],can_do_challenge:{statement:"Bisa menyampaikan laporan persiapan jelang peluncuran operasional, sambutan resmi peresmian, dan instruksi keselamatan dengan ragam formal.",situation:"Ruang kendali pabrik Kanagawa, pukul 08.30 pagi.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜に際して!",modelAnswer:"はい、田中【たなか】さん！ 稼働【かどう】に 際【さい】して、全【すべ】ての センサーの 点検【てんけん】を 完了【かんりょう】いたしました。マニュアルの 注意【ちゅうい】事項【じこう】も 全員【ぜんいん】に 周知【しゅうち】しております。",modelAnswerId:"Ya, Tanaka-san! Menjelang pengoperasian, kami telah menuntaskan inspeksi seluruh sensor. Poin-poin perhatian pada manual juga telah disosialisasikan ke semua staf.",culturalEtiquette:"Dalam dunia industri Jepang, peluncuran lini baru selalu diawali briefing keselamatan resmi. Menggunakan 〜に際して menunjukkan rasa hormat terhadap momentum penting perusahaan.",skillUnlocked:["Menguasai formulasi pola 〜に際して","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Titik Balik, Suksesi Instan & Momentum Waktu"]},pocket_summary:{keyFormula:"V-dict / N + に際して (pada saat momen penting / ketika resmi), V-dict / N + にあたって (menjelang / dalam rangka persiapan acara besar)",coreWords:["稼働【かどう】","点検【てんけん】 (inspection; examination)","準備【じゅんび】 (persiapan, kesiapan)","企画【きかく】 (perencanaan; proyek)"],coreWarning:"Jangan gunakan 〜に際して untuk rutinitas harian sepele (seperti makan siang atau mandi); pola ini dikhususkan bagi momen penting formal.",quickDialogue:"A: ブディさん、新【あたら】しい 自動【じどう】化【か... → B: はい、田中【たなか】さん！ 稼働【かどう】に 際【..."}},"les-n2-u01-02":{pedagogical_framework:{what:{summary:"Menguasai pola 〜に伴って (seiring dengan perubahan skala besar) dan variasinya untuk memaparkan dampak simultan dalam laporan bisnis dan teknik.",canDo:"Bisa menganalisis tren data, menjelaskan keterkaitan sebab-akibat simultan, dan merumuskan langkah antisipasi dampak perubahan.",targetPatterns:["V-dict / N + に伴って / に伴い (seiring dengan / bersamaan dengan perubahan)","N + に伴う + N (yang menyertai / yang timbul akibat)"],coreVocabSample:["摩耗【まもう】","負担【ふたん】","増加【ぞうか】","維持【いじ】","提供【ていきょう】する","対策【たいさく】","変化【へんか】する","監視【かんし】する"]},sensei_context:{sceneIntro:"Ruang evaluasi performa pabrik. Tanaka dan Budi membahas kenaikan volume pesanan ekspor yang berdampak pada peningkatan beban mesin dan jadwal pemeliharaan.",dailyMission:'Mampu menjelaskan hubungan korelatif sebab-akibat menggunakan pola "ni tomonatte" secara akurat dalam laporan evaluasi mingguan.',whyOrder:"Setelah memahami titik awal momentum di Lesson 1, Lesson 2 melatih pembelajar menjelaskan gelombang dampak yang menyertai perubahan tersebut."},cultural_notes:{title:"Manajemen Pemeliharaan Preventif (予防保全 - Yobou Hozen)",etiquette:"Di industri Jepang, melaporkan potensi keausan sebelum alat rusak dipuji sebagai integritas profesional (Kaizen). Pola 〜に伴って sangat lazim dalam laporan teknis semacam ini.",taboos:"Hindari memakai 〜に伴って untuk peristiwa statis tanpa perubahan; pola ini wajib melibatkan elemen pergeseran atau perkembangan."},pronunciation_tips:{title:'Pelafalan Jernih pada Verba Bantu "tomonatte"',moraNote:"Perhatikan mora sokon kecil [っ] pada to-mo-na-t-te; tahan jeda satu ketukan sebelum melafalkan konsonan t.",soundTip:"Bentuk tulisan formal に伴い (ni tomonai) dilafalkan mengalir tanpa henti di tengah."},common_pitfalls:[{title:"Tertukar Antara に伴って (Simultan Sebab-Akibat) vs につれて (Alami Satu Arah)",caseScenario:"Menggunakan につれて untuk klausul yang melibatkan tindakan terencana atau kebijakan buatan manusia.",pitfallWarning:'"新【あたら】しい 法律【ほうりつ】の 施行【しこう】に つれて、社内【しゃない】規定【きてい】を 変更【へんこう】した。"',rightSolution:'"新【あたら】しい 法律【ほうりつ】の 施行【しこう】に 伴【ともな】って、社内【しゃない】規定【きてい】を 変更【へんこう】した。"',explanation:"〜につれて terbatas pada fenomena alami satu arah (seperti bertambah tua), sedangkan 〜に伴って mencakup kebijakan resmi dan sebab-akibat terencana."},{title:"Salah Menempatkan Bentuk Nomina: に伴う vs に伴って",caseScenario:'Menerangkan kata benda di belakangnya menggunakan bentuk adverbial: "tomonatte risuku".',pitfallWarning:'"増産【ぞうさん】に 伴【ともな】って リスクを 検討【けんとう】する。"',rightSolution:'"増産【ぞうさん】に 伴【ともな】う リスクを 検討【けんとう】する。"',explanation:"Gunakan に伴う ketika memodifikasi langsung kata benda berikutnya (N + に伴う + N)."}],who_and_when:{situational_context:"Presentasi hasil analisis tren, laporan dampak kebijakan, atau perumusan anggaran operasional tahunan.",social_relations:"Ragam bahasa tertulis dan lisan formal untuk forum rapat dan dokumen resmi.",when_not_to_use:"Jangan gunakan pada perubahan sepele perseorangan tanpa dampak relasional yang jelas."},scenario:{title:"Antisipasi Risiko Lonjakan Produksi Akhir Tahun",setting:"Ruang rapat departemen teknik, pukul 14.00.",narrative:"Tanaka dan Budi menyusun strategi pemeliharaan mesin seiring lonjakan volume perakitan ekspor."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、先【さき】ほどの 生産【せいさん】計画【けいかく】の 変更【へんこう】に 伴【ともな】う 課題【かだい】に ついて、対策【たいさく】は まとまりましたか？",furigana:"ブディさん、先ほどの 生産計画の 変更に 伴う 課題に ついて、対策は まとまりましたか？",romaji:"Budi-san, sakihodo no seisan keikaku no henkou ni tomonau kadai ni tsuite, taisaku wa matomarimashita ka?",idText:"Budi, mengenai kendala yang timbul seiring perubahan rencana produksi tadi, apakah solusinya sudah dirumuskan?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、田中【たなか】さん！ 生産量【せいさんりょう】の 増加【ぞうか】に 伴【ともな】って、設備【せつび】の 部品【ぶひん】の 摩耗【まもう】が 早【はや】まる 恐【おそ】れが あります。そのため、点検【てんけん】の 頻度【ひんど】を 週【しゅう】１回【いっかい】から 週【しゅう】２回【にかい】に 増【ふ】やす 計画【けいかく】を 立【た】てました。",furigana:"はい、田中さん！ 生産量の 増加に 伴って、設備の 部品の 摩耗が 早まる 恐れが あります。そのため、点検の 頻度を 週１回から 週２回に 増やす 計画を 立てました。",romaji:"Hai, Tanaka-san! Seisanryou no zouka ni tomonatte, setsubi no buhin no mamou ga hayamaru osore ga arimasu. Sono tame, tenken no hindo o shuu ikkai kara shuu nikai ni fuyasu keikaku o tatemashita.",idText:"Ya, Tanaka-san! Seiring peningkatan volume produksi, ada kekhawatiran keausan komponen fasilitas akan terjadi lebih cepat. Oleh sebab itu, kami menyusun rencana peningkatan frekuensi inspeksi dari sekali sepekan menjadi dua kali sepekan."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"非常【ひじょう】に 的確【てきかく】な 判断【はんだん】ですね。点検【てんけん】作業【さぎょう】の 増加【ぞうか】に 伴【ともな】う 現場【げんば】スタッフの 負担【ふたん】も 考慮【こうりょ】して、シフトを 調整【ちょうせい】しましょう。",furigana:"非常に 的確な 判断ですね。点検作業の 増加に 伴う 現場スタッフの 負担も 考慮して、シフトを 調整しましょう。",romaji:"Hijou ni tekikaku na handan desu ne. Tenken sagyou no zouka ni tomonau gemba sutaffu no futan mo kouryo shite, shifuto o chousei shimashou.",idText:"Keputusan yang sangat tepat. Mempertimbangkan juga beban staf lapangan yang menyertai bertambahnya tugas inspeksi, mari kita sesuaikan jadwal shift-nya."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ありがとうございます！ スタッフの 安全【あんぜん】と 疲労【ひろう】度【ど】を 最優先【さいゆうせん】に 確認【かくにん】しながら 進行【しんこう】いたします。",furigana:"ありがとうございます！ スタッフの 安全と 疲労度を 最優先に 確認しながら 進行いたします。",romaji:"Arigatou gozaimasu! Sutaffu no anzen to hiroudo o saiyuusen ni kakunin shinagara shinkou itashimasu.",idText:"Terima kasih banyak! Kami akan melaksanakannya dengan senantiasa mengutamakan keselamatan dan tingkat kelelahan staf."}],vocab_breakdown:[{id:"vg-n2-00177",word:"協力",reading:"きょうりょく",romaji:"kyouryoku",meaning:"kerja sama, kolaborasi",pos:"noun-suru",nuance:"Menunjukkan tindakan bekerja bersama demi tujuan yang sama. Lebih umum dan luas dari 連携 (renkei) yang menekankan koordinasi erat antar organisasi. 協力する = 'bekerja sama'. Polite request: ご協力ください.",particleTip:"Kolokasi alami: 〜を 協力 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"国際社会の協力が不可欠だ。",furigana:"国際社会の協力が不可欠だ。",romaji:"kyouryoku",idText:"Kerja sama internasional sangat penting."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"キョウリョク￣"}},{id:"vg-n2-00178",word:"連携",reading:"れんけい",romaji:"renkei",meaning:"koordinasi, kolaborasi erat antar pihak",pos:"noun-suru",nuance:"Lebih spesifik dari 協力: menekankan koordinasi terstruktur antar organisasi atau divisi yang berbeda. 連携する = 'berkoordinasi erat'. Sering muncul dalam konteks kemitraan instansi pemerintah, rumah sakit, atau bisnis.",particleTip:"Kolokasi alami: 〜を 連携 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"警察と消防が連携して対応した。",furigana:"警察と消防が連携して対応した。",romaji:"renkei",idText:"Polisi dan pemadam kebakaran berkoordinasi dalam penanganan."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"レンケイ￣"}},{id:"vg-n2-00179",word:"統合",reading:"とうごう",romaji:"tougou",meaning:"integrasi, penyatuan, konsolidasi",pos:"noun-suru",nuance:"Menunjukkan proses menyatukan berbagai bagian menjadi satu kesatuan. Berbeda dari 合併 (gappei = merger/penggabungan perusahaan) yang lebih spesifik di ranah bisnis. 統合 dipakai lebih luas: sistem, kebijakan, sosial.",particleTip:"Kolokasi alami: 〜を 統合 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"ヨーロッパの統合はEUによって進められた。",furigana:"ヨーロッパの統合はEUによって進められた。",romaji:"tougou",idText:"Integrasi Eropa didorong oleh Uni Eropa."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"トウゴウ￣"}},{id:"vg-n2-00180",word:"分断",reading:"ぶんだん",romaji:"bundan",meaning:"pemisahan, perpecahan, polarisasi",pos:"noun-suru",nuance:"Menunjukkan terpecahnya masyarakat, negara, atau kelompok secara tajam. Berkonotasi negatif — pemisahan yang merugikan. 社会の分断 (polarisasi sosial) sering muncul dalam analisis politik kontemporer.",particleTip:"Kolokasi alami: 〜を 分断 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"社会の分断が深刻な問題になっている。",furigana:"社会の分断が深刻な問題になっている。",romaji:"bundan",idText:"Polarisasi masyarakat menjadi masalah yang serius."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ブンダン￣"}},{id:"vg-n2-00181",word:"改革",reading:"かいかく",romaji:"kaikaku",meaning:"reformasi, perombakan sistem",pos:"noun-suru",nuance:"Menunjukkan perubahan mendasar pada sistem atau institusi yang sudah ada. Lebih kuat dari 改善 (kaizen = perbaikan bertahap); 改革 menyiratkan perombakan besar. 行政改革 = reformasi administrasi.",particleTip:"Kolokasi alami: 〜を 改革 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"政治改革を推し進めるための議論が続いている。",furigana:"政治改革を推し進めるための議論が続いている。",romaji:"kaikaku",idText:"Diskusi untuk mendorong reformasi politik terus berlangsung."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"カイカク￣"}},{id:"vg-n2-00182",word:"廃止",reading:"はいし",romaji:"haishi",meaning:"penghapusan, pembatalan, abolisi",pos:"noun-suru",nuance:"Menunjukkan penghapusan resmi suatu hukum, sistem, atau institusi secara permanen. Berbeda dari 廃棄 (haiki = membuang benda) dan 取り消し (torikeshi = pembatalan). 廃止 khusus untuk aturan/institusi.",particleTip:"Kolokasi alami: 〜を 廃止 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"死刑制度の廃止を求める声が高まっている。",furigana:"死刑制度の廃止を求める声が高まっている。",romaji:"haishi",idText:"Suara yang menuntut penghapusan hukuman mati semakin meningkat."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"ハイシ￣"}},{id:"vg-n2-00183",word:"導入",reading:"どうにゅう",romaji:"dounyuu",meaning:"pengenalan, penerapan, implementasi (hal baru)",pos:"noun-suru",nuance:"Menunjukkan tindakan memperkenalkan atau menerapkan sesuatu yang baru ke dalam suatu sistem. 導入する = 'mengadopsi/menerapkan'. Sering dipakai: 新システムの導入, AI技術の導入 (penerapan AI).",particleTip:"Kolokasi alami: 〜を 導入 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"AIシステムの導入によって業務が効率化された。",furigana:"AIシステムの導入によって業務が効率化された。",romaji:"dounyuu",idText:"Penerapan sistem AI membuat operasional menjadi lebih efisien."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ドウニュウ￣"}},{id:"vg-n2-00184",word:"審議",reading:"しんぎ",romaji:"shingi",meaning:"pembahasan resmi, deliberasi",pos:"noun-suru",nuance:"Merujuk pada diskusi serius di mana berbagai pihak bertukar argumen. Lebih formal dari 話し合い (hanashiai = pembicaraan). 議論する = 'berdebat/mendiskusikan'. 議論を呼ぶ = 'memancing perdebatan'.",particleTip:"Kolokasi alami: 〜を 審議 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"この問題については様々な議論が行われている。",furigana:"この問題については様々な議論が行われている。",romaji:"shingi",idText:"Berbagai diskusi sedang berlangsung mengenai masalah ini."},pitch:{pattern:1,category:"atamadaka",mora_count:3,downstep_mora:1,contour:"シ＼ンギ"}}],explanations:[{id:"exp-1",grammarId:"gn2-00107",title:"Pola: 〜を契機に",formula:"N + を契機に / を契機として",meaning:"menjadikan ... sebagai momentum / berawal dari ... (sebagai titik balik penting)",nuanceNotes:"〜を契機に menyatakan bahwa peristiwa X menjadi momentum atau titik balik yang mendorong perubahan atau tindakan signifikan sesudahnya.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜を契機に",idText:"menjadikan ... sebagai momentum / berawal dari ... (sebagai titik balik penting)"}],examples:[{jp:"その事故を契機に、安全規制が大幅に強化された。",romaji:"",idText:"Berawal dari kecelakaan itu, regulasi keselamatan pun diperkuat secara signifikan."},{jp:"転職を契機に、生き方そのものを見直した。",romaji:"",idText:"Menjadikan pergantian pekerjaan sebagai momentum, aku menata ulang cara hidupku."}]},{id:"exp-2",grammarId:"gn2-00108",title:"Pola: 〜をきっかけに",formula:"N / V-plain + のをきっかけに",meaning:"karena dipicu oleh ... / berawal dari ... / gara-gara ...",nuanceNotes:"〜をきっかけに menyatakan bahwa X menjadi pemicu atau awal mula dari suatu perubahan atau tindakan. Lebih kasual dan personal dibanding を契機に.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜をきっかけに",idText:"karena dipicu oleh ... / berawal dari ... / gara-gara ..."}],examples:[{jp:"旅行をきっかけに、写真に深く興味を持つようになった。",romaji:"",idText:"Berawal dari perjalanan itu, aku jadi sangat tertarik dengan fotografi."},{jp:"彼女に出会ったのをきっかけに、日本語の勉強を始めた。",romaji:"",idText:"Dipicu oleh pertemuan dengannya, aku mulai belajar bahasa Jepang."}]},{id:"exp-3",grammarId:"gn2-00123",title:"Pola: 〜ものを",formula:"V-plain / Adj-plain + ものを",meaning:"padahal kalau saja ... (penyesalan yang tertahan)",nuanceNotes:"〜ものを mengungkapkan penyesalan — situasi yang disesalkan seharusnya bisa dihindari jika kondisi tertentu terpenuhi. Sering digunakan di akhir kalimat.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ものを",idText:"padahal kalau saja ... (penyesalan yang tertahan)"}],examples:[{jp:"早く言えばよかったものを。",romaji:"",idText:"Padahal kalau saja bilang lebih awal..."},{jp:"少し待てばよかったものを、なぜそんなに急いだのか。",romaji:"",idText:"Padahal kalau sabar sebentar saja — mengapa tergesa-gesa begitu?"}]},{id:"exp-4",grammarId:"gn2-00131",title:"Pola: 〜を契機に",formula:"N + を契機に / V-plain + のを契機に",meaning:"menjadikan ... sebagai titik balik / kesempatan untuk berubah",nuanceNotes:"〜を契機に menyatakan bahwa suatu peristiwa menjadi pemicu atau titik balik yang mendorong perubahan besar atau tindakan baru. Biasanya digunakan untuk momen penting dalam hidup atau organisasi.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜を契機に",idText:"menjadikan ... sebagai titik balik / kesempatan untuk berubah"}],examples:[{jp:"転職を契機に、生活スタイルを一新した。",romaji:"",idText:"Menjadikan pergantian kerja sebagai titik balik, ia merombak total gaya hidupnya."},{jp:"震災を契機に、地域の防災意識が高まった。",romaji:"",idText:"Bencana gempa menjadi titik balik meningkatnya kesadaran mitigasi bencana di masyarakat."},{jp:"留学を契機に、将来は国際的な仕事をしたいと思うようになった。",romaji:"",idText:"Pengalaman belajar di luar negeri menjadi kesempatan baginya untuk mulai bercita-cita berkarier di bidang internasional."}]},{id:"exp-5",grammarId:"gn2-00132",title:"Pola: 〜に先立って",formula:"N + に先立って / V-dictionary + に先立って",meaning:"sebelum ..., sebagai langkah pendahuluan sebelum ...",nuanceNotes:"〜に先立って menyatakan bahwa suatu tindakan dilakukan terlebih dahulu sebagai persiapan atau langkah awal sebelum peristiwa utama. Digunakan dalam konteks formal seperti upacara, proyek, atau pengumuman resmi.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に先立って",idText:"sebelum ..., sebagai langkah pendahuluan sebelum ..."}],examples:[{jp:"式典に先立って、主催者から挨拶がありました。",romaji:"",idText:"Sebelum upacara dimulai, ada sambutan dari penyelenggara."},{jp:"工事に先立って、住民への説明会が開かれた。",romaji:"",idText:"Sebagai langkah pendahuluan sebelum konstruksi, diadakan sesi penjelasan bagi warga."}]},{id:"exp-6",grammarId:"gn2-00133",title:"Pola: 〜に際して",formula:"N + に際して / V-dictionary + に際して",meaning:"saat ..., dalam rangka ..., pada kesempatan ...",nuanceNotes:"〜に際して menandai momen penting atau situasi khusus sebagai konteks untuk suatu tindakan. Digunakan saat memperkenalkan hal yang dilakukan atau diperhatikan pada suatu peristiwa penting.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に際して",idText:"saat ..., dalam rangka ..., pada kesempatan ..."}],examples:[{jp:"入社に際して、いくつかの書類を提出してください。",romaji:"",idText:"Dalam rangka masuk kerja, harap serahkan beberapa dokumen berikut."},{jp:"試験に際して、携帯電話の電源をお切りください。",romaji:"",idText:"Saat ujian berlangsung, mohon matikan telepon genggam Anda."}]},{id:"exp-7",grammarId:"gn2-00144",title:"Pola: 〜たびに",formula:"V-dictionary + たびに / N + のたびに",meaning:"setiap kali ..., tiap kali ... (terjadi)",nuanceNotes:"〜たびに menyatakan bahwa setiap kali suatu peristiwa atau tindakan terjadi, konsekuensi atau reaksi tertentu selalu mengikutinya. Menekankan pola berulang yang terpicu oleh suatu aksi.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜たびに",idText:"setiap kali ..., tiap kali ... (terjadi)"}],examples:[{jp:"故郷に帰るたびに、昔のことを思い出す。",romaji:"",idText:"Setiap kali pulang ke kampung halaman, ia selalu teringat masa lalu."},{jp:"試験のたびに、緊張してしまう。",romaji:"",idText:"Setiap kali ada ujian, ia selalu gugup."}]},{id:"exp-8",grammarId:"gn2-00145",title:"Pola: 〜ごとに",formula:"N(waktu/jumlah) + ごとに / V-dictionary + ごとに",meaning:"setiap ..., per ..., dengan interval teratur ...",nuanceNotes:"〜ごとに menyatakan interval waktu atau satuan yang teratur, atau bahwa setiap unit/individu memiliki kondisi yang berbeda. Digunakan untuk keteraturan atau distribusi.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ごとに",idText:"setiap ..., per ..., dengan interval teratur ..."}],examples:[{jp:"薬は6時間ごとに飲んでください。",romaji:"",idText:"Minumlah obat ini setiap 6 jam sekali."},{jp:"人ごとに、価値観が異なる。",romaji:"",idText:"Setiap orang memiliki nilai-nilai hidup yang berbeda-beda."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna istilah "摩耗 (まもう)" dalam konteks mesin pabrik?',sentencePrompt:'Istilah "摩耗 (まもう)" mengacu pada fenomena:',options:["Keausan permukaan material akibat gesekan berulang","Karat kimia akibat kelembapan udara","Peleburan logam karena suhu tinggi","Patah mendadak akibat benturan keras"],correctAnswer:"Keausan permukaan material akibat gesekan berulang",explanation:'"摩耗 (まもう)" tersusun dari 摩 (gesek) + 耗 (habis/terkikis), artinya keausan akibat gesekan mekanik.',diagnosticFeedback:{"Karat kimia akibat kelembapan udara":"Salah: Karat kimia adalah 腐食 (fushoku) atau 錆び (sabi).","Peleburan logam karena suhu tinggi":"Salah: Peleburan adalah 溶解 (youkai).","Patah mendadak akibat benturan keras":"Salah: Patah mendadak adalah 破断 (hadan) atau 破損 (hason)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat rumpang berikut untuk menyatakan dampak perubahan gaya hidup seiring perkembangan teknologi:",sentencePrompt:"通信【つうしん】技術【ぎじゅつ】の 発展【はってん】_____、リモートワークが 急速【きゅうそく】に 普及【ふきゅう】した。",options:["に伴って","に限って","に比べて","に反して"],correctAnswer:"に伴って",explanation:"Perkembangan teknologi membawa dampak simultan merebaknya kerja jarak jauh, sehingga pola yang tepat adalah 〜に伴って (seiring dengan).",diagnosticFeedback:{に限って:'Salah: に限って bermakna "khusus pada / sialnya justru saat...", tidak cocok untuk korelasi tren.',に比べて:"Salah: に比べて adalah komparasi perbandingan, bukan relasi sebab-akibat simultan.",に反して:"Salah: に反して bermakna bertolak belakang dari dugaan."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Bentuk Nomina Modifikasi): Manakah kalimat yang menggunakan bentuk modifikasi kata benda 〜に伴う secara tepat?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["経済【けいざい】の 成長【せいちょう】に 伴【ともな】う 環境【かんきょう】問題【もんだい】が 深刻【しんこく】化【か】している。","経済【けいざい】の 成長【せいちょう】に 伴【ともな】って 環境【かんきょう】問題【もんだい】が 深刻化している。","経済【けいざい】の 成長【せいちょう】に 伴【ともな】った 環境【かんきょう】問題が 深刻化している。","経済【けいざい】の 成長【せいちょう】に 伴【ともな】い 環境【かんきょう】問題が 深刻化している。"],correctAnswer:"経済【けいざい】の 成長【せいちょう】に 伴【ともな】う 環境【かんきょう】問題【もんだい】が 深刻【しんこく】化【か】している。",explanation:"Sebelum kata benda 環境問題 (masalah lingkungan), wajib menggunakan bentuk modifikasi nomina 〜に伴う (V-dict).",diagnosticFeedback:{"経済【けいざい】の 成長【せいちょう】に 伴【ともな】って 環境【かんきょう】問題【もんだい】が 深刻化している。":"Kekeliruan Modifikasi: Bentuk te-kei (に伴って) adalah adverbial untuk menerangkan predikat kerja, tidak boleh langsung menempel pada kata benda tanpa partikel.","経済【けいざい】の 成長【せいちょう】に 伴【ともな】った 環境【かんきょう】問題が 深刻化している。":"Kekeliruan Aspek: Bentuk lampau *に伴った tidak lazim dalam pola modifikasi baku N2.","経済【けいざい】の 成長【せいちょう】に 伴【ともな】い 環境【かんきょう】問題が 深刻化している。":"Kekeliruan Fungsi: Bentuk ます-stem (に伴い) berfungsi sebagai penghubung klausa tertulis, bukan modifikasi nomina."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat analisis dampak demografi yang gramatikal:",sentencePrompt:"Susunlah frasa-frasa berikut agar membentuk kalimat yang gramatikal:",options:["少子高齢化の 進展に伴って、 社会保障費が 増大している。","社会保障費が 少子高齢化の 進展に伴って、 増大している。","増大している。 社会保障費が 少子高齢化の 進展に伴って、","進展に伴って、 増大している。 少子高齢化の 社会保障費が"],correctAnswer:"少子高齢化の 進展に伴って、 社会保障費が 増大している。",explanation:"Urutan baku: Sebab tren (少子高齢化の進展に伴って) + Subjek dampak (社会保障費が) + Predikat perubahan (増大している).",diagnosticFeedback:{"社会保障費が 少子高齢化の 進展に伴って、 増大している。":"Kekeliruan Fokus: Memisahkan subjek dari predikatnya dengan menyisipkan klausa panjang di tengah membuat kalimat terpecah.","増大している。 社会保障費が 少子高齢化の 進展に伴って、":"Kekeliruan Predikat: Predikat diletakkan di awal kalimat bertentangan dengan struktur SOV.","進展に伴って、 増大している。 少子高齢化の 社会保障費が":"Kekeliruan Modifikasi: Genitif 少子高齢化の terpisah dari kata yang dimodifikasinya (進展)."},tokens:["少子高齢化の","進展に伴って、","社会保障費が","増大している。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Respons Strategis): Saat supervisor Tanaka mengusulkan: 「現場スタッフの 負担も 考慮して、シフトを 調整しましょう」, bagaimana tanggapan terbaik Anda?",sentencePrompt:"Pilihlah tanggapan yang paling tepat dan berorientasi pada kepedulian tim kerja:",options:["ありがとうございます！ スタッフの 安全と 疲労度を 最優先に 確認しながら 進行いたします。","シフト調整は 面倒なので、今の ままの 人数で 無理やり 乗り切りましょう。","現場の スタッフが 疲れても、会社の 利益の 方が 大事ですから 関係ありません。","私は 本部スタッフなので、現場が どうなろうと 知ったことでは ありません。"],correctAnswer:"ありがとうございます！ スタッフの 安全と 疲労度を 最優先に 確認しながら 進行いたします。",explanation:"Menunjukkan komitmen sinergis antara efisiensi kerja dan kesejahteraan rekan tim lapangan.",diagnosticFeedback:{"シフト調整は 面倒なので、今の ままの 人数で 無理やり 乗り切りましょう。":"Sangat Berbahaya: Memaksa staf bekerja melebihi kapasitas tanpa rotasi dapat memicu kecelakaan kerja fatal.","現場の スタッフが 疲れても、会社の 利益の 方が 大事ですから 関係ありません。":"Pelanggaran K3: Mengabaikan keselamatan manusia demi profit adalah pelanggaran berat etika manajemen Jepang.","私は 本部スタッフなので、現場が どうなろうと 知ったことでは ありません。":"Egois: Sikap tidak peduli antarbagian (Silo mentality) menghancurkan kekompakan organisasi."}}],can_do_challenge:{statement:"Bisa menganalisis tren data, menjelaskan keterkaitan sebab-akibat simultan, dan merumuskan langkah antisipasi dampak perubahan.",situation:"Ruang rapat departemen teknik, pukul 14.00.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜を契機に!",modelAnswer:"はい、田中【たなか】さん！ 生産量【せいさんりょう】の 増加【ぞうか】に 伴【ともな】って、設備【せつび】の 部品【ぶひん】の 摩耗【まもう】が 早【はや】まる 恐【おそ】れが あります。そのため、点検【てんけん】の 頻度【ひんど】を 週【しゅう】１回【いっかい】から 週【しゅう】２回【にかい】に 増【ふ】やす 計画【けいかく】を 立【た】てました。",modelAnswerId:"Ya, Tanaka-san! Seiring peningkatan volume produksi, ada kekhawatiran keausan komponen fasilitas akan terjadi lebih cepat. Oleh sebab itu, kami menyusun rencana peningkatan frekuensi inspeksi dari sekali sepekan menjadi dua kali sepekan.",culturalEtiquette:"Di industri Jepang, melaporkan potensi keausan sebelum alat rusak dipuji sebagai integritas profesional (Kaizen). Pola 〜に伴って sangat lazim dalam laporan teknis semacam ini.",skillUnlocked:["Menguasai formulasi pola 〜を契機に","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Titik Balik, Suksesi Instan & Momentum Waktu"]},pocket_summary:{keyFormula:"V-dict / N + に伴って / に伴い (seiring dengan / bersamaan dengan perubahan), N + に伴う + N (yang menyertai / yang timbul akibat)",coreWords:["摩耗【まもう】","負担【ふたん】 (beban, tanggung jawab finansial/fisik)","増加【ぞうか】 (peningkatan, pertambahan, bertambah banyak)","維持【いじ】 (mempertahankan, merawat, menjaga kesinambungan)"],coreWarning:"Hindari memakai 〜に伴って untuk peristiwa statis tanpa perubahan; pola ini wajib melibatkan elemen pergeseran atau perkembangan.",quickDialogue:"A: ブディさん、先【さき】ほどの 生産【せいさん】計画... → B: はい、田中【たなか】さん！ 生産量【せいさんりょう..."}}},n={"les-n2-u02-01":{pedagogical_framework:{what:{summary:"Menguasai pola 〜に先がけて (mendahului yang lain / sebagai perintis) dan 〜に先立って (sebelum mengawali kegiatan besar) dalam perancangan strategi bisnis.",canDo:"Bisa mempresentasikan inovasi perintis, merancang uji coba sebelum rilis umum, dan melaporkan keunggulan komparatif.",targetPatterns:["N + に先がけて / に先がけ (mendahului / merintis sebelum yang lain)","V-dict / N + に先立って / に先立ち (sebelum mengawali kegiatan resmi)"],coreVocabSample:["実施【じっし】","検証【けんしょう】","導入【どうにゅう】","先駆【さきが】け","保証【ほしょう】する","対応【たいおう】","計画【けいかく】","精巧【せいこう】"]},sensei_context:{sceneIntro:"Ruang rapat logistik pelabuhan Yokohama. Tanaka menanyakan hasil uji coba sistem pelacakan kontainer otomatis yang diterapkan tim Budi mendahului pelabuhan lain.",dailyMission:'Mampu menjelaskan keunggulan inisiatif perintis menggunakan "ni sakigakete" secara lugas di hadapan dewan direksi.',whyOrder:"Pola ini krusial di N2 untuk membedakan urutan kronologis waktu biasa dengan tindakan proaktif yang berinisiatif maju lebih dahulu."},cultural_notes:{title:"Semangat Inovasi Pelopor (先駆者精神 - Senkusha Seishin) di Industri Jepang",etiquette:"Menjadi pelopor (先駆け) sangat dihargai dalam persaingan bisnis global. Gunakan 〜に先がけて dengan nada bangga namun tetap menjunjung objektivitas data verifikasi.",taboos:"Hindari memakai 〜に先がけて untuk hal-hal yang bersifat mengekor atau sekadar mengikuti kebiasaan yang sudah ada."},pronunciation_tips:{title:'Artikulasi Jelas pada Frasa Beruntun "ni sakigakete"',moraNote:"Lafalkan sa-ki-ga-ke-te dengan tempo rata. Huruf ga memiliki sedikit nasal pelan dalam standar Tokyo (bitoon).",soundTip:"Bentuk tulisan formal に先立ち (ni sakidachi) menggunakan mora chi yang tajam."},common_pitfalls:[{title:"Tertukar Antara に先立って (Persiapan Awal) vs に先がけて (Merintis Mendahului Kompetitor)",caseScenario:"Ingin menyatakan bahwa perusahaan merilis produk baru sebelum kompetitor lain, tetapi salah memilih kata.",pitfallWarning:'"他社【たしゃ】に 先立【さきだ】って、新【あたら】しい サービスを 開始【かいし】した。"',rightSolution:'"他社【たしゃ】に 先駆【さきが】けて、新【あたら】しい サービスを 開始【かいし】した。"',explanation:"に先立って berarti melakukan persiapan *sebelum acara dimulai*, sedangkan に先がけて berarti *bergerak lebih dulu mendahului pihak lain*."},{title:"Memasukkan Predikat Pasif yang Tidak Selaras",caseScenario:"Menggunakan subjek yang tidak memiliki kehendak bertindak aktif.",pitfallWarning:'"雨【あめ】に 先がけて、傘【かさ】が 降【ふ】った。"',rightSolution:'"一般【いっぱん】公開【こうかい】に 先がけて、関係者【かんけいしゃ】内覧会【ないらんかい】を 行【おこな】った。"',explanation:"Pola ini mengindikasikan tindakan sengaja dan inisiatif aktif manusia atau organisasi."}],who_and_when:{situational_context:"Rilis pers media, rapat inovasi produk, atau pengajuan proposal riset keunggulan pasar.",social_relations:"Ragam resmi formal antara pimpinan inovasi dan mitra bisnis eksternal.",when_not_to_use:"Jangan gunakan pada urutan aktivitas pribadi di rumah."},scenario:{title:"Laporan Keberhasilan Uji Coba Barcode RFID di Yokohama",setting:"Ruang konferensi pelabuhan Yokohama, pukul 10.00.",narrative:"Tanaka memuji tim Budi yang menguji sistem barcode RFID cerdas lebih awal sebelum dermaga regional lain menerapkannya."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、他港【たこう】に 先駆【さきが】けて 導入【どうにゅう】した RFID 自動【じどう】追跡【ついせき】システムですが、現在【げんざい】の 検証【けんしょう】結果【けっか】は いかがですか？",furigana:"ブディさん、他港に 先駆けて 導入した RFID 自動追跡システムですが、現在の 検証結果は いかがですか？",romaji:"Budi-san, takou ni sakigakete dounyuu shita RFID jidou tsuiseki shisutemu desu ga, genzai no kenshou kekka wa ikaga desu ka?",idText:"Budi, mengenai sistem pelacakan otomatis RFID yang kita terapkan mendahului pelabuhan lain, bagaimana hasil verifikasinya saat ini?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、田中【たなか】さん！ 全国【ぜんこく】の 商業【しょうぎょう】港【こう】に 先駆【さきが】けて 実証【じっしょう】実験【じっけん】を 行【おこな】った 結果【けっか】、コンテナの 誤配送【ごはいそう】が ゼロ件【けん】を 記録【きろく】いたしました。",furigana:"はい、田中さん！ 全国の 商業港に 先駆けて 実証実験を 行った 結果、コンテナの 誤配送が ゼロ件を 記録いたしました。",romaji:"Hai, Tanaka-san! Zenkoku no shougyoukou ni sakigakete jisshou jikken o okonatta kekka, kontena no gohaisou ga zero ken o kiroku itashimashita.",idText:"Ya, Tanaka-san! Berkat uji coba nyata yang mendahului pelabuhan komersial nasional lainnya, kesalahan pengiriman kontainer tercatat nol kasus."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"素晴らしい 成果【せいか】ですね！ 本格【ほんかく】稼働【かどう】に 先立【さきだ】って、現場【げんば】オペレーターへの 操作【そうさ】研修【けんしゅう】も 抜【ぬ】かりなく 進【すす】めてください。",furigana:"素晴らしい 成果ですね！ 本格稼働に 先立って、現場オペレーターへの 操作研修も 抜かりなく 進めてください。",romaji:"Subarashii seika desu ne! Honkaku kadou ni sakidatte, gemba opereetaa e no sousa kenshuu mo nukarinaku susumete kudasai.",idText:"Pencapaian yang luar biasa! Sebelum memulai pengoperasian penuh, tolong laksanakan juga pelatihan operator lapangan tanpa ada yang terlewat."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"かしこまりました！ 来週【らいしゅう】の 運用【うんよう】開始【かいし】に 先立【さきだ】ち、全【すべ】ての マニュアルを 配布【はいふ】し、模擬【もぎ】訓練【くんれん】を 実施【じっし】いたします。",furigana:"かしこまりました！ 来週の 運用開始に 先立ち、全ての マニュアルを 配布し、模擬訓練を 実施いたします。",romaji:"Kashikomarimashita! Raishuu no unyou kaishi ni sakidachi, subete no manyuaru o haifu shi, mogi kunren o jisshi itashimasu.",idText:"Dimengerti! Sebelum peluncuran operasional pekan depan, kami akan membagikan seluruh manual dan menggelar simulasi pelatihan praktis."}],vocab_breakdown:[{id:"vg-n2-00283",word:"判断する",reading:"はんだんする",romaji:"handan suru",meaning:"menilai, memutuskan berdasarkan pertimbangan",pos:"noun-suru",nuance:"Berbeda dari 決める (kimeru = memutuskan) yang lebih sederhana — 判断する menekankan proses evaluasi dan pertimbangan rasional sebelum mengambil keputusan. Lebih berat secara kognitif dan sering dipakai dalam situasi profesional, hukum, atau medis.",particleTip:"Kolokasi alami: 〜を 判断する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"医師は患者の症状を見て適切な治療法を判断した。",furigana:"医師は患者の症状を見て適切な治療法を判断した。",romaji:"handan suru",idText:"Dokter menilai gejala pasien dan memutuskan pengobatan yang tepat."},pitch:{pattern:1,category:"atamadaka",mora_count:4,downstep_mora:1,contour:"ハ＼ンダン"}},{id:"vg-n2-00284",word:"評価する",reading:"ひょうかする",romaji:"hyouka suru",meaning:"mengevaluasi, menilai kinerja atau kualitas",pos:"noun-suru",nuance:"Berbeda dari 判断する — 評価する fokus pada penilaian kualitas, kinerja, atau nilai suatu objek atau orang secara sistematis, sedangkan 判断する lebih ke keputusan umum. 高く評価する = 'menilai tinggi = menghargai', bisa bermakna positif atau negatif.",particleTip:"Kolokasi alami: 〜を 評価する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"彼女の研究は国際的に高く評価されている。",furigana:"彼女の研究は国際的に高く評価されている。",romaji:"hyouka suru",idText:"Penelitiannya dihargai tinggi secara internasional."},pitch:{pattern:1,category:"atamadaka",mora_count:3,downstep_mora:1,contour:"ヒョ＼ウカ"}},{id:"vg-n2-00285",word:"比較する",reading:"ひかくする",romaji:"hikaku suru",meaning:"membandingkan",pos:"noun-suru",nuance:"Lebih formal dari 比べる (kuraberu) — 比較する sering digunakan dalam tulisan akademik, presentasi bisnis, atau analisis terstruktur. 比べる lebih kasual dan bisa digunakan sehari-hari. 比較的 = 'secara relatif/komparatif' adalah turunan adverbia yang sangat umum.",particleTip:"Kolokasi alami: 〜を 比較する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"二つの製品を比較すると、価格に大きな差がある。",furigana:"二つの製品を比較すると、価格に大きな差がある。",romaji:"hikaku suru",idText:"Ketika membandingkan kedua produk, ada perbedaan harga yang besar."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"ヒカク￣"}},{id:"vg-n2-00286",word:"区別する",reading:"くべつする",romaji:"kubetsu suru",meaning:"membedakan, mendistingsi berdasarkan ciri atau sifat",pos:"noun-suru",nuance:"Berbeda dari 分ける (wakeru = memisahkan secara fisik) — 区別する menekankan pembedaan konseptual atau kategorisasi berdasarkan ciri dan karakteristik. 差別する (sabetsu suru) adalah kata yang serupa secara bunyi tetapi bermakna negatif (mendiskriminasi).",particleTip:"Kolokasi alami: 〜を 区別する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"公私を区別することが社会人として重要だ。",furigana:"公私を区別することが社会人として重要だ。",romaji:"kubetsu suru",idText:"Membedakan urusan publik dan pribadi adalah hal penting sebagai orang dewasa bekerja."},pitch:{pattern:1,category:"atamadaka",mora_count:3,downstep_mora:1,contour:"ク＼ベツ"}},{id:"vg-n2-00287",word:"分析する",reading:"ぶんせきする",romaji:"bunseki suru",meaning:"menganalisis, mengurai secara sistematis",pos:"noun-suru",nuance:"Lebih mendalam dan terstruktur dari 調べる (shiraberu = meneliti) — 分析する menunjukkan proses pemecahan sesuatu menjadi komponen-komponen untuk dipahami secara sistematis. Umumnya digunakan dalam konteks akademik, riset, dan profesional.",particleTip:"Kolokasi alami: 〜を 分析する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"市場のデータを分析すると消費者の傾向がわかる。",furigana:"市場のデータを分析すると消費者の傾向がわかる。",romaji:"bunseki suru",idText:"Dengan menganalisis data pasar, kita bisa memahami tren konsumen."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ブンセキ￣"}},{id:"vg-n2-00288",word:"解釈する",reading:"かいしゃくする",romaji:"kaishaku suru",meaning:"menginterpretasikan, menafsirkan",pos:"noun-suru",nuance:"Berbeda dari 理解する (rikai suru) — 解釈する menekankan proses penafsiran terhadap sesuatu yang ambigu, kompleks, atau terbuka untuk berbagai sudut pandang (hukum, teks sastra, perilaku). Hasilnya bisa berbeda antara satu orang dengan orang lain.",particleTip:"Kolokasi alami: 〜を 解釈する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"この法律をどう解釈するかは専門家でも意見が分かれる。",furigana:"この法律をどう解釈するかは専門家でも意見が分かれる。",romaji:"kaishaku suru",idText:"Bahkan para ahli pun berbeda pendapat dalam menafsirkan undang-undang ini."},pitch:{pattern:1,category:"atamadaka",mora_count:4,downstep_mora:1,contour:"カ＼イシャク"}},{id:"vg-n2-00289",word:"証明する",reading:"しょうめいする",romaji:"shoumei suru",meaning:"membuktikan, menunjukkan kebenaran secara formal",pos:"noun-suru",nuance:"Berbeda dari 説明する (setsumei suru = menjelaskan) — 証明する menekankan pembuktian kebenaran secara formal melalui bukti, data, logika, atau dokumen resmi. Dalam kehidupan sehari-hari juga digunakan untuk sertifikasi: 身分を証明する = 'membuktikan identitas'.",particleTip:"Kolokasi alami: 〜を 証明する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"科学者はその仮説を実験で証明した。",furigana:"科学者はその仮説を実験で証明した。",romaji:"shoumei suru",idText:"Para ilmuwan membuktikan hipotesis tersebut melalui eksperimen."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ショウメイ￣"}},{id:"vg-n2-00290",word:"反論する",reading:"はんろんする",romaji:"hanron suru",meaning:"membantah, menyanggah dengan argumen balik",pos:"noun-suru",nuance:"Lebih formal dan spesifik dari 反対する (hantai suru = menentang) — 反論する secara khusus berarti merespons argumen orang lain dengan argumen balasan yang logis. Digunakan dalam debat, diskusi akademik, atau persidangan, bukan sekadar menyatakan ketidaksetujuan.",particleTip:"Kolokasi alami: 〜を 反論する (objek tindakan kerja/bisnis).",exampleSentence:{jp:"彼は証拠を示して相手の主張に反論した。",furigana:"彼は証拠を示して相手の主張に反論した。",romaji:"hanron suru",idText:"Dia menunjukkan bukti dan membantah klaim lawan bicaranya."},pitch:{pattern:0,category:"heiban",mora_count:6,downstep_mora:0,contour:"はんろんする￣"}}],explanations:[{id:"exp-1",grammarId:"gn2-00146",title:"Pola: 〜につけ",formula:"V-dictionary + につけ / い-Adj(stem) + につけ / 〜につけ〜につけ",meaning:"setiap kali ..., entah ... maupun ... (selalu menimbulkan perasaan tertentu)",nuanceNotes:'〜につけ menyatakan bahwa setiap kali suatu situasi terjadi, selalu timbul perasaan atau reaksi tertentu. Sering digunakan dalam pola berpasangan (いいにつけ悪いにつけ) untuk menyatakan "bagaimanapun kondisinya".',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜につけ",idText:"setiap kali ..., entah ... maupun ... (selalu menimbulkan perasaan tertentu)"}],examples:[{jp:"故郷の写真を見るにつけ、両親のことが恋しくなる。",romaji:"",idText:"Setiap kali melihat foto kampung halaman, ia selalu rindu pada orang tuanya."},{jp:"いいにつけ悪いにつけ、彼女のことが気になる。",romaji:"",idText:"Entah dalam kondisi baik maupun buruk, ia selalu memikirkan perempuan itu."}]},{id:"exp-2",grammarId:"gn2-00191",title:"Pola: 〜に先がけて",formula:"N + に先がけて",meaning:"mendahului ..., sebelum orang lain ...",nuanceNotes:"〜に先がけて menyatakan bahwa seseorang atau suatu pihak melakukan sesuatu lebih awal dari orang lain atau sebelum suatu peristiwa terjadi, seringkali dengan nuansa menjadi yang pertama atau memelopori. Digunakan untuk menggambarkan tindakan yang bersifat inisiatif atau pionir.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に先がけて",idText:"mendahului ..., sebelum orang lain ..."}],examples:[{jp:"他社に先がけて、新製品を市場に投入した。",romaji:"",idText:"Mendahului perusahaan lain, mereka meluncurkan produk baru ke pasar."},{jp:"世界に先がけて、日本がその技術を開発した。",romaji:"",idText:"Mendahului dunia, Jepang mengembangkan teknologi tersebut."},{jp:"開会式に先がけて、リハーサルが行われた。",romaji:"",idText:"Mendahului upacara pembukaan, diadakan gladi resik."}]},{id:"exp-3",grammarId:"gn2-00193",title:"Pola: 〜とともに",formula:"N + とともに / V-plain + とともに",meaning:"bersamaan dengan ..., seiring ...",nuanceNotes:'〜とともに memiliki dua fungsi: (1) "bersama dengan" — menyatakan bahwa dua hal atau pihak terlibat secara bersamaan; (2) "seiring dengan" — menyatakan perubahan yang terjadi secara paralel. Dalam makna kedua, digunakan untuk menggambarkan dua hal yang berkembang atau berubah secara sejajar.',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜とともに",idText:"bersamaan dengan ..., seiring ..."}],examples:[{jp:"年齢を重ねるとともに、視野が広がった。",romaji:"",idText:"Seiring bertambahnya usia, wawasan pun semakin luas."},{jp:"彼女は仲間とともに、プロジェクトを成功させた。",romaji:"",idText:"Dia berhasil menyelesaikan proyek bersama timnya."},{jp:"社会が変化するとともに、価値観も変わってきた。",romaji:"",idText:"Seiring perubahan masyarakat, nilai-nilai pun ikut berubah."}]},{id:"exp-4",grammarId:"gn2-00194",title:"Pola: 〜にともなって",formula:"N + にともなって / V-plain + にともなって / にともなう + N",meaning:"seiring dengan ..., bersamaan dengan (perubahan)",nuanceNotes:"〜にともなって menyatakan bahwa suatu perubahan atau peristiwa membawa serta perubahan lain secara bersamaan — perubahan yang satu memicu atau disertai perubahan yang lain. Pola ini lebih formal dibandingkan 〜とともに dan sering digunakan dalam teks berita, laporan, atau akademis.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜にともなって",idText:"seiring dengan ..., bersamaan dengan (perubahan)"}],examples:[{jp:"少子化にともなって、学校の数が減った。",romaji:"",idText:"Seiring dengan penurunan angka kelahiran, jumlah sekolah pun berkurang."},{jp:"経済成長にともなって、生活水準が向上した。",romaji:"",idText:"Seiring pertumbuhan ekonomi, standar hidup pun meningkat."},{jp:"技術の進化にともなう変化に対応する。",romaji:"",idText:"Merespons perubahan yang menyertai evolusi teknologi."}]},{id:"exp-5",grammarId:"gn2-00209",title:"Pola: 〜に当たって",formula:"V-plain (辞書形) / N + に当たって",meaning:"pada saat ..., dalam rangka ...",nuanceNotes:"〜に当たって menyatakan bahwa suatu tindakan atau pertimbangan khusus dilakukan pada momen penting atau krusial — saat melakukan sesuatu yang signifikan. Pola ini menekankan bahwa momen tersebut adalah kesempatan atau situasi yang layak mendapat perhatian khusus.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に当たって",idText:"pada saat ..., dalam rangka ..."}],examples:[{jp:"新しい仕事を始めるに当たって、心構えを改めた。",romaji:"",idText:"Dalam rangka memulai pekerjaan baru, saya memperbarui tekad hati."},{jp:"卒業に当たって、先生に感謝の言葉を伝えた。",romaji:"",idText:"Pada saat kelulusan, saya menyampaikan kata-kata terima kasih kepada guru."},{jp:"式典開催に当たって、準備を万全にする。",romaji:"",idText:"Dalam rangka penyelenggaraan upacara, persiapan dilakukan secara matang."}]},{id:"exp-6",grammarId:"gn2-00210",title:"Pola: 〜にあたり",formula:"V-plain (辞書形) / N + にあたり",meaning:"pada saat ..., dalam rangka ... (formal/tulisan)",nuanceNotes:"〜にあたり adalah bentuk tulisan formal dari 〜に当たって (gn2-00209). Maknanya identik — digunakan untuk menyatakan bahwa sesuatu dilakukan pada momen penting atau dalam rangka suatu peristiwa signifikan. Bentuk ini sangat umum ditemukan dalam pidato, sambutan, pengumuman resmi, dan dokumen tertulis.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜にあたり",idText:"pada saat ..., dalam rangka ... (formal/tulisan)"}],examples:[{jp:"新年度の開始にあたり、ご挨拶申し上げます。",romaji:"",idText:"Dalam rangka dimulainya tahun ajaran baru, perkenankan saya menyampaikan sambutan."},{jp:"事業の拡大にあたり、新たな人材を募集します。",romaji:"",idText:"Dalam rangka perluasan usaha, kami membuka rekrutmen tenaga kerja baru."},{jp:"本書の出版にあたり、多くの方にご協力いただきました。",romaji:"",idText:"Dalam rangka penerbitan buku ini, kami mendapat dukungan dari banyak pihak."}]},{id:"exp-7",grammarId:"gn2-00211",title:"Pola: 〜に伴い",formula:"N + に伴い / V-plain + に伴い / に伴う + N",meaning:"seiring dengan ... (formal/tulisan)",nuanceNotes:"〜に伴い adalah bentuk tulisan formal dari 〜にともなって (gn2-00194). Menyatakan bahwa suatu perubahan atau kejadian membawa serta perubahan atau dampak lain secara bersamaan. Sangat umum dalam berita, laporan, pengumuman resmi, dan surat menyurat bisnis.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に伴い",idText:"seiring dengan ... (formal/tulisan)"}],examples:[{jp:"システム更新に伴い、一時的にサービスを停止します。",romaji:"",idText:"Seiring pembaruan sistem, layanan akan dihentikan sementara."},{jp:"人口増加に伴い、インフラ整備が急がれる。",romaji:"",idText:"Seiring pertumbuhan penduduk, pembangunan infrastruktur semakin mendesak."},{jp:"工事に伴う騒音にご注意ください。",romaji:"",idText:"Harap berhati-hati terhadap kebisingan yang menyertai proses konstruksi."}]},{id:"exp-8",grammarId:"gn2-00213",title:"Pola: 〜を経て",formula:"N + を経て / V-plain + 過程を経て",meaning:"setelah melalui ..., melewati proses ...",nuanceNotes:"〜を経て menyatakan bahwa suatu hasil dicapai setelah melalui suatu proses, tahapan, atau pengalaman tertentu. Mengandung nuansa bahwa proses tersebut memerlukan waktu, usaha, atau perjalanan yang berarti sebelum mencapai tujuan akhir.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜を経て",idText:"setelah melalui ..., melewati proses ..."}],examples:[{jp:"長い交渉を経て、契約が成立した。",romaji:"",idText:"Setelah melalui negosiasi panjang, kontrak berhasil disepakati."},{jp:"試験と面接を経て、採用された。",romaji:"",idText:"Setelah melewati ujian dan wawancara, dia diterima bekerja."},{jp:"数年の研究を経て、新薬が開発された。",romaji:"",idText:"Setelah melalui beberapa tahun penelitian, obat baru berhasil dikembangkan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah padanan makna yang tepat untuk istilah "実証 (じっしょう)" dalam pengujian sistem?',sentencePrompt:'Istilah "実証 (じっしょう)" memiliki arti:',options:["Pembuktian keandalan melalui data atau uji nyata","Dugaan sementara tanpa bukti","Penundaan jadwal peluncuran","Pembatalan proyek sepihak"],correctAnswer:"Pembuktian keandalan melalui data atau uji nyata",explanation:'"実証 (じっしょう)" tersusun dari 実 (nyata) + 証 (bukti), berarti verifikasi empiris lapangan.',diagnosticFeedback:{"Dugaan sementara tanpa bukti":"Salah: Dugaan sementara adalah 推測 (suisoku) atau 仮説 (kasetsu).","Penundaan jadwal peluncuran":"Salah: Penundaan jadwal adalah 延期 (enki).","Pembatalan proyek sepihak":"Salah: Pembatalan adalah 中止 (chuushi) atau 破棄 (haki)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat rumpang berikut untuk menyatakan tindakan mendahului kompetitor lain:",sentencePrompt:"我【わ】が 社【しゃ】は ライバル 企業【きぎょう】_____、環境【かんきょう】配慮【はいりょ】型【がた】の EV トラックを 開発【かいはつ】した。",options:["に先駆けて","に際して","によって","にすぎず"],correctAnswer:"に先駆けて",explanation:"Konteks melangkah lebih awal sebelum perusahaan pesaing menuntut pola 〜に先駆けて (merintis mendahului).",diagnosticFeedback:{に際して:"Salah: に際して hanya bermakna pada saat momen penting, bukan mendahului pihak pesaing.",によって:"Salah: によって menyatakan instrumen atau kausalitas.",にすぎず:"Salah: にすぎず bermakna hanya sebatas itu saja."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Pembedaan Nuansa): Manakah kalimat yang menggunakan 〜に先立って secara tepat untuk persiapan sebelum kegiatan resmi?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["会議【かいぎ】の 開始【かいし】に 先立【さきだ】ち、資料【しりょう】を 配布【はいふ】いたします。","他社【たしゃ】に 先立【さきだ】って、世界【せかい】初【はつ】の ロボットを 発売【はつばい】した。","会議【かいぎ】に 先立【さきだ】ってでした、資料を 配りました。","会議【かいぎ】を 先立【さきだ】つ、資料を 配布します。"],correctAnswer:"会議【かいぎ】の 開始【かいし】に 先立【さきだ】ち、資料【しりょう】を 配布【はいふ】いたします。",explanation:"Membagikan materi sebelum rapat dimulai adalah persiapan resmi yang tepat menggunakan に先立ち / に先立って.",diagnosticFeedback:{"他社【たしゃ】に 先立【さきだ】って、世界【せかい】初【はつ】の ロボットを 発売【はつばい】した。":"Kekeliruan Nuansa: Untuk mendahului kompetitor pasar, wajib memakai に先駆けて (sakigakete), bukan に先立って.","会議【かいぎ】に 先立【さきだ】ってでした、資料を 配りました。":"Kekeliruan Sintaksis: Bentuk に先立ってでした tidak gramatikal.","会議【かいぎ】を 先立【さきだ】つ、資料を 配布します。":"Kekeliruan Partikel: Pola ini memerlukan partikel に (に先立って), bukan partikel を."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat peluncuran proyek yang logis:",sentencePrompt:"Susunlah frasa-frasa berikut agar membentuk kalimat yang gramatikal:",options:["国際見本市の 開幕に先立って、 記者会見が 開かれた。","記者会見が 開幕に先立って、 国際見本市の 開かれた。","開かれた。 記者会見が 国際見本市の 開幕に先立って、","開幕に先立って、 開かれた。 国際見本市の 記者会見が"],correctAnswer:"国際見本市の 開幕に先立って、 記者会見が 開かれた。",explanation:"Keterangan waktu (国際見本市の開幕に先立って) + Subjek (記者会見が) + Predikat pasif (開かれた).",diagnosticFeedback:{"記者会見が 開幕に先立って、 国際見本市の 開かれた。":"Kekeliruan Pemisahan Modifikasi: Genitif 国際見本市の terpisah dari kata benda 開幕.","開かれた。 記者会見が 国際見本市の 開幕に先立って、":"Kekeliruan Posisi Predikat: Kata kerja ditaruh di awal kalimat.","開幕に先立って、 開かれた。 国際見本市の 記者会見が":"Kekeliruan Klausa: Predikat 開かれた memutus kesinambungan anak kalimat."},tokens:["国際見本市の","開幕に先立って、","記者会見が","開かれた。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Respons Pelatihan): Saat Tanaka berpesan: 「現場オペレーターへの 操作研修も 抜かりなく 進めてください」, apa respons terbaik Anda?",sentencePrompt:"Pilihlah jawaban yang paling mencerminkan dedikasi profesional:",options:["かしこまりました！ 運用開始に 先立ち、全ての マニュアルを 配布し、模擬訓練を 実施いたします。","操作は 簡単なので、研修なんて やるだけ 時間の 無駄ですよ。","オペレーターが 自分で 覚えるべきですから、放っておきましょう。","研修を 担当する くらいなら、会社を 辞めさせていただきます。"],correctAnswer:"かしこまりました！ 運用開始に 先立ち、全ての マニュアルを 配布し、模擬訓練を 実施いたします。",explanation:"Menunjukkan komitmen persiapan komprehensif (distribusi manual + simulasi latihan).",diagnosticFeedback:{"操作は 簡単なので、研修なんて やるだけ 時間の 無駄ですよ。":"Terlalu Meremehkan: Meremehkan pelatihan operasional adalah pemicu utama kecelakaan kerja.","オペレーターが 自分で 覚えるべきですから、放っておきましょう。":"Lepas Tanggung Jawab: Membiarkan rekan kerja tanpa bimbingan melanggar etika pembinaan tim.","研修を 担当する くらいなら、会社を 辞めさせていただきます。":"Emosional & Tidak Pantas: Respons konfrontatif ekstrem tidak memiliki tempat di lingkungan korporat."}}],can_do_challenge:{statement:"Bisa mempresentasikan inovasi perintis, merancang uji coba sebelum rilis umum, dan melaporkan keunggulan komparatif.",situation:"Ruang konferensi pelabuhan Yokohama, pukul 10.00.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜につけ!",modelAnswer:"はい、田中【たなか】さん！ 全国【ぜんこく】の 商業【しょうぎょう】港【こう】に 先駆【さきが】けて 実証【じっしょう】実験【じっけん】を 行【おこな】った 結果【けっか】、コンテナの 誤配送【ごはいそう】が ゼロ件【けん】を 記録【きろく】いたしました。",modelAnswerId:"Ya, Tanaka-san! Berkat uji coba nyata yang mendahului pelabuhan komersial nasional lainnya, kesalahan pengiriman kontainer tercatat nol kasus.",culturalEtiquette:"Menjadi pelopor (先駆け) sangat dihargai dalam persaingan bisnis global. Gunakan 〜に先がけて dengan nada bangga namun tetap menjunjung objektivitas data verifikasi.",skillUnlocked:["Menguasai formulasi pola 〜につけ","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Pencapaian Bertahap, Batas Waktu & Mileston Kerja"]},pocket_summary:{keyFormula:"N + に先がけて / に先がけ (mendahului / merintis sebelum yang lain), V-dict / N + に先立って / に先立ち (sebelum mengawali kegiatan resmi)",coreWords:["実施【じっし】 (pelaksanaan, penyelenggaraan, pemberlakuan (resmi/hukum))","検証【けんしょう】","導入【どうにゅう】 (pengenalan, penerapan, implementasi (hal baru))","先駆【さきが】け"],coreWarning:"Hindari memakai 〜に先がけて untuk hal-hal yang bersifat mengekor atau sekadar mengikuti kebiasaan yang sudah ada.",quickDialogue:"A: ブディさん、他港【たこう】に 先駆【さきが】けて ... → B: はい、田中【たなか】さん！ 全国【ぜんこく】の 商..."}},"les-n2-u02-02":{pedagogical_framework:{what:{summary:"Menguasai pola 〜とともに (bersamaan dengan perubahan / di samping itu sekaligus) dan 〜契機に (bermula dari momentum titik tolak) untuk memaparkan perkembangan bisnis.",canDo:"Bisa merangkum transformasi organisasi, menghubungkan dua fakta yang berjalan seiring, dan menceritakan titik balik kemajuan.",targetPatterns:["V-dict / N + とともに (seiring dengan / bersamaan dengan)","N + を契機に / を契機として (bermula dari momentum / bertitik tolak dari)"],coreVocabSample:["契機【けいき】","転換【てんかん】","促進【そくしん】","向上【こうじょう】","生長【せいちょう】","強化【きょうか】する","結果【けっか】","発展【はってん】"]},sensei_context:{sceneIntro:"Sesi evaluasi akhir tahun di kantor perkapalan Yokohama. Tanaka dan Budi meninjau bagaimana krisis rantai pasok global justru menjadi momentum pembaruan sistem digital.",dailyMission:'Mampu menghubungkan korelasi kemajuan dan momentum titik tolak menggunakan "to tomo ni" dan "o keiki ni" dalam presentasi evaluasi.',whyOrder:"Pola ini mengasah kemampuan analisis makro pembelajar N2 dalam melihat hikmah krisis dan relasi simultan antarsistem."},cultural_notes:{title:'Konsep "Mengubah Krisis Menjadi Peluang" (ピンチをチャンスに変える)',etiquette:"Dalam budaya korporat Jepang, merefleksikan kegagalan masa lalu sebagai momentum kebangkitan (契機 - Keiki) adalah tanda kepemimpinan matang.",taboos:"Jangan gunakan 〜を契機に untuk kebetulan kecil sehari-hari; pola ini menuntut adanya dampak perubahan arah yang signifikan."},pronunciation_tips:{title:'Intonasi Mengalir pada Partikel "to tomo ni"',moraNote:"Lafalkan to-to-mo-ni dengan nada ritmis datar. Jangan menaikkan nada secara tajam pada mora kedua to.",soundTip:"Kata 契機 (keiki) memiliki vokal panjang [ei] 2 mora: ke-e-ki."},common_pitfalls:[{title:"Tertukar Antara 〜とともに (Simultan Positif/Netral) vs 〜につれて (Hanya Satu Arah)",caseScenario:"Ingin menyampaikan dua aksi yang dilakukan bersamaan oleh satu subjek.",pitfallWarning:'"日本語【にほんご】の 勉強【べんきょう】に つれて、日本【にほん】の 文化【ぶんか】も 学【まな】んでいる。"',rightSolution:'"日本語【にほんご】の 勉強【べんきょう】と ともに、日本【にほん】の 文化【ぶんか】も 学【まな】んでいる。"',explanation:'〜につれて hanya untuk perubahan proporsional alami satu arah. Untuk menyatakan "A sekaligus juga B", gunakan 〜とともに.'},{title:"Salah Partikel Sebelum 契機",caseScenario:"Memakai partikel ni atau de sebelum kata benda keiki.",pitfallWarning:'"失敗【しっぱい】に 契機【けいき】に、方針【ほうしん】を 変【か】えた。"',rightSolution:'"失敗【しっぱい】を 契機【けいき】に、方針【ほうしん】を 変【か】えた。"',explanation:"Struktur baku pola ini adalah [Kata Benda] + を + 契機に / 契機として."}],who_and_when:{situational_context:"Pidato refleksi akhir tahun, penulisan esai wacana ekonomi, atau presentasi strategi ekspansi baru.",social_relations:"Komunikasi tingkat menengah-atas di hadapan rekan kerja, mentor, atau mitra pemangku kepentingan.",when_not_to_use:"Hindari penggunaan dalam percakapan cepat non-formal di lapangan."},scenario:{title:"Transformasi Digital Berangkat dari Evaluasi Hambatan Logistik",setting:"Ruang direksi pelabuhan Yokohama, pukul 16.30.",narrative:"Tanaka dan Budi memaparkan bagaimana audit sistem bulan lalu menjadi momentum pembenahan total alur kargo ekspor."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、先月【せんげつ】の システム トラブルを 契機【けいき】に 進【すす】めてきた 業務【ぎょうむ】改善【かいぜん】ですが、全体【ぜんたい】の 効果【こうか】は 把握【はあく】できていますか？",furigana:"ブディさん、先月の システム トラブルを 契機に 進めてきた 業務改善ですが、全体の 効果は 把握できていますか？",romaji:"Budi-san, sengetsu no shisutemu toraburu o keiki ni susumete kita gyoumu kaizen desu ga, zentai no kouka wa haaku dekite imasu ka?",idText:"Budi, mengenai perbaikan operasional yang kita jalankan bertolak dari kendala sistem bulan lalu, apakah dampak keseluruhannya sudah terpetakan?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、田中【たなか】さん！ あの トラブルを 契機【けいき】として 導入【どうにゅう】した クラウド 管理【かんり】に より、作業【さぎょう】の 効率【こうりつ】化【か】と ともに、情報【じょうほう】共有【きょうゆう】の スピードも 飛躍【ひやく】的【てき】に 向上【こうじょう】いたしました。",furigana:"はい、田中さん！ あの トラブルを 契機として 導入した クラウド 管理に より、作業の 効率化と ともに、情報共有の スピードも 飛躍的に 向上いたしました。",romaji:"Hai, Tanaka-san! Ano toraburu o keiki to shite dounyuu shita kuraudo kanri ni yori, sagyou no kouritsuka to tomo ni, jouhou kyouyuu no supiido mo hiyakuteki ni koujou itashimashita.",idText:"Ya, Tanaka-san! Berkat manajemen cloud yang kita adopsi bermula dari momentum kendala tersebut, seiring dengan peningkatan efisiensi kerja, kecepatan berbagi informasi pun melonjak drastis."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"まさに 災【わざわ】いを 転【てん】じて 福【ふく】と なす ですね。企業【きぎょう】の 成長【せいちょう】と ともに、コンプライアンスの 意識【いしき】も より 一層【いっそう】高【たか】めていきましょう。",furigana:"まさに 災いを 転じて 福と なす ですね。企業の 成長と ともに、コンプライアンスの 意識も より 一層高めていきましょう。",romaji:"Masa ni wazawai o tenjite fuku to nasu desu ne. Kigyou no seichou to tomo ni, kompuraiansu no ishiki mo yori issou takamete ikimashou.",idText:'Benar-benar pepatah "mengubah musibah menjadi berkah". Seiring pertumbuhan perusahaan, mari kita tingkatkan pula kesadaran kepatuhan regulasi secara lebih mendalam.'},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ 技術【ぎじゅつ】の 向上【こうじょう】と ともに、社会的【しゃかいてき】な 責任【せきにん】も しっかり 果【は】たせるよう 努力【どりょく】いたします。",furigana:"はい！ 技術の 向上と ともに、社会的な 責任も しっかり 果たせるよう 努力いたします。",romaji:"Hai! Gijutsu no koujou to tomo ni, shakaiteki na sekinin mo shikkari hataseru you doryoku itashimasu.",idText:"Baik! Bersamaan dengan peningkatan kemampuan teknis, saya akan berusaha keras agar mampu memenuhi tanggung jawab sosial secara optimal."}],vocab_breakdown:[{id:"vg-n2-00462",word:"扇ぐ",reading:"あおぐ",romaji:"aogu",meaning:"kipas angin",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 扇ぐ / 〜に関する 扇ぐ dalam wacana profesional.",exampleSentence:{jp:"彼はあおいで火をおこした。",furigana:"彼はあおいで火をおこした。",romaji:"aogu",idText:"Dia mengipasi api menjadi nyala api."},pitch:{pattern:2,category:"nakadaka",mora_count:3,downstep_mora:2,contour:"アオ＼グ"}},{id:"vg-n2-00465",word:"あきれる",reading:"あきれる",romaji:"akireru",meaning:"kagum",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の あきれる / 〜に関する あきれる dalam wacana profesional.",exampleSentence:{jp:"あの人にはあきれてしまった。",furigana:"あの人にはあきれてしまった。",romaji:"akireru",idText:"Aku muak dan bosan padanya."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"アキレル￣"}},{id:"vg-n2-00467",word:"あくび",reading:"あくび",romaji:"akubi",meaning:"menguap",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を あくび (objek tindakan kerja/bisnis).",exampleSentence:{jp:"あの先生の講義はあくびが出る。",furigana:"あの先生の講義はあくびが出る。",romaji:"akubi",idText:"Ceramahnya sangat membosankan."},pitch:{pattern:1,category:"atamadaka",mora_count:3,downstep_mora:1,contour:"ア＼クビ"}},{id:"vg-n2-00470",word:"挙げる",reading:"あげる",romaji:"ageru",meaning:"menaikkan",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 挙げる / 〜に関する 挙げる dalam wacana profesional.",exampleSentence:{jp:"質問があれば右手を挙げて下さい。",furigana:"質問があれば右手を挙げて下さい。",romaji:"ageru",idText:"Jika Anda memiliki pertanyaan, silakan angkat tangan kanan Anda."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"アゲル￣"}},{id:"vg-n2-00471",word:"揚げる",reading:"あげる",romaji:"ageru",meaning:"angkat",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 揚げる / 〜に関する 揚げる dalam wacana profesional.",exampleSentence:{jp:"彼はたこを揚げた。",furigana:"彼はたこを揚げた。",romaji:"ageru",idText:"Dia menerbangkan layang-layang."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"アゲル￣"}},{id:"vg-n2-00472",word:"憧れる",reading:"あこがれる",romaji:"akogareru",meaning:"rindu untuk",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 憧れる / 〜に関する 憧れる dalam wacana profesional.",exampleSentence:{jp:"あの人達は都会の生活にあこがれている。",furigana:"あの人達は都会の生活にあこがれている。",romaji:"akogareru",idText:"Mereka longing for city life."},pitch:{pattern:0,category:"heiban",mora_count:5,downstep_mora:0,contour:"アコガレル￣"}},{id:"vg-n2-00474",word:"味わう",reading:"あじわう",romaji:"ajiwau",meaning:"rasa",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 味わう / 〜に関する 味わう dalam wacana profesional.",exampleSentence:{jp:"あのテーマパークでスリルを味わった。",furigana:"あのテーマパークでスリルを味わった。",romaji:"ajiwau",idText:"Kami bersenang-senang di taman hiburan."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"アジワ＼ウ"}},{id:"vg-n2-00475",word:"預かる",reading:"あずかる",romaji:"azukaru",meaning:"tetap dalam tahanan",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 預かる / 〜に関する 預かる dalam wacana profesional.",exampleSentence:{jp:"４時まで荷物を預かっていただけませんか。",furigana:"４時まで荷物を預かっていただけませんか。",romaji:"azukaru",idText:"Bisakah Anda menyimpan tas saya di sini sampai jam empat?"},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"アズカ＼ル"}}],explanations:[{id:"exp-1",grammarId:"gn2-00219",title:"Pola: 〜の末に",formula:"N (proses/usaha) + の末に / V-た + 末に",meaning:"setelah panjang ..., pada akhirnya setelah ...",nuanceNotes:'〜の末に menyatakan bahwa setelah melalui proses yang panjang, melelahkan, atau penuh perjuangan, akhirnya tercapai suatu hasil. Pola ini secara khas digunakan dengan kata benda yang menggambarkan proses panjang seperti "苦労" (kerja keras), "努力" (usaha), "悩み" (kekhawatiran), atau "話し合い" (diskusi).',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜の末に",idText:"setelah panjang ..., pada akhirnya setelah ..."}],examples:[{jp:"長い話し合いの末に、結論に達した。",romaji:"",idText:"Setelah diskusi panjang, akhirnya tercapai kesimpulan."},{jp:"苦労の末に、夢を実現した。",romaji:"",idText:"Setelah panjang berjuang, impiannya akhirnya terwujud."},{jp:"悩んだ末に、転職を決めた。",romaji:"",idText:"Setelah lama mempertimbangkan, dia memutuskan untuk pindah kerja."}]},{id:"exp-2",grammarId:"gn2-00235",title:"Pola: 〜ものを",formula:"V-plain / Adj-plain + ものを",meaning:"padahal bisa saja ... / seandainya saja ... (penyesalan atau keluhan)",nuanceNotes:"〜ものを menyatakan penyesalan atau keluhan bahwa sesuatu yang seharusnya bisa terjadi justru tidak terjadi, atau seseorang tidak melakukan hal yang seharusnya. Mengandung nada menyesal atau menyalahkan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ものを",idText:"padahal bisa saja ... / seandainya saja ... (penyesalan atau keluhan)"}],examples:[{jp:"素直に謝れば許してもらえたものを、強情を張るから…。",romaji:"",idText:"Kalau saja mau minta maaf dengan tulus, pasti sudah dimaafkan, tapi karena keras kepala..."},{jp:"早めに病院に行けばよかったものを。",romaji:"",idText:"Seandainya saja pergi ke dokter lebih awal, pasti sudah lebih baik."}]},{id:"exp-3",grammarId:"gn2-00236",title:"Pola: 〜だろうに",formula:"V-plain / Adj-plain / N + だろうに",meaning:"padahal pasti ... / seandainya ... tentu ... (penyesalan kontrafaktual)",nuanceNotes:'〜だろうに menyatakan penyesalan atau simpati dengan membayangkan kondisi yang seharusnya bisa terjadi tetapi tidak. Pembicara menyiratkan "padahal sudah jelas hasilnya bisa baik, tapi nyatanya tidak begitu."',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜だろうに",idText:"padahal pasti ... / seandainya ... tentu ... (penyesalan kontrafaktual)"}],examples:[{jp:"少し休めば楽になるだろうに、無理をして倒れてしまった。",romaji:"",idText:"Padahal kalau sedikit saja istirahat pasti merasa lebih baik, tapi malah memaksakan diri sampai jatuh sakit."},{jp:"言えば助けてもらえただろうに、なぜ一人で抱え込んだのか。",romaji:"",idText:"Kalau bilang saja pasti sudah dibantu, mengapa menanggungnya sendiri?"}]},{id:"exp-4",grammarId:"gn2-00281",title:"Pola: 〜きる",formula:"V-masu-stem + きる",meaning:"benar-benar menyelesaikan ..., sampai habis/tuntas",nuanceNotes:'〜きる menyatakan bahwa suatu tindakan dilakukan secara penuh, menyeluruh, hingga tuntas — tidak setengah-setengah. Dipakai terutama dengan verba yang melibatkan konsumsi, usaha, atau penyelesaian seperti 食べる, 飲む, 使う, 読む. Menekankan aspek "sampai tidak ada sisa" atau "sampai benar-benar habis."',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜きる",idText:"benar-benar menyelesaikan ..., sampai habis/tuntas"}],examples:[{jp:"この本を今日中に読みきるつもりだ。",romaji:"",idText:"Aku berniat membaca buku ini sampai habis hari ini."},{jp:"電池を使いきる前に充電した方がいい。",romaji:"",idText:"Lebih baik isi daya sebelum baterai benar-benar habis terpakai."}]},{id:"exp-5",grammarId:"gn2-00284",title:"Pola: 〜きった",formula:"V-masu-stem + きった (past)",meaning:"sudah benar-benar selesai, sudah tuntas (bentuk lampau dari 〜きる)",nuanceNotes:'〜きった adalah bentuk lampau (past tense) dari 〜きる, menyatakan bahwa suatu tindakan telah diselesaikan secara penuh dan tuntas. Selain menunjukkan penyelesaian, bentuk ini juga sering dipakai untuk menyatakan kondisi yang telah mencapai titik ekstrem, seperti "sudah kelelahan total" atau "sudah habis sama sekali."',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜きった",idText:"sudah benar-benar selesai, sudah tuntas (bentuk lampau dari 〜きる)"}],examples:[{jp:"マラソン42kmを走りきった。気持ちよかった！",romaji:"",idText:"Berhasil berlari maraton 42 km sampai garis finish. Lega sekali rasanya!"},{jp:"長い旅の後でもう疲れきった。",romaji:"",idText:"Setelah perjalanan panjang, sudah benar-benar habis tenaganya."}]},{id:"exp-6",grammarId:"gn2-00285",title:"Pola: 〜ぬく",formula:"V-masu-stem + ぬく",meaning:"bertahan sampai akhir, melakukan sampai tuntas (meskipun sulit)",nuanceNotes:'〜ぬく menyatakan bahwa seseorang bertahan dan melakukan sesuatu sampai akhir meskipun menghadapi kesulitan atau tantangan besar. Mengandung nuansa ketekunan, ketangguhan, dan tekad yang kuat. Berbeda dari sekadar "selesai," 〜ぬく menekankan perjuangan yang dilewati untuk mencapai hasil akhir.',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ぬく",idText:"bertahan sampai akhir, melakukan sampai tuntas (meskipun sulit)"}],examples:[{jp:"どんなに辛くても、最後まで走りぬく！",romaji:"",idText:"Seberapa pun beratnya, aku akan berlari sampai akhir!"},{jp:"彼は貧しい環境の中でも勉強しぬいて、医者になった。",romaji:"",idText:"Di tengah kondisi yang serba kekurangan, dia terus belajar hingga akhirnya menjadi dokter."}]},{id:"exp-7",grammarId:"gn2-00286",title:"Pola: 〜とおす",formula:"V-masu-stem + とおす",meaning:"menyelesaikan, bertahan sampai selesai (tanpa menyerah atau berhenti)",nuanceNotes:'〜とおす menyatakan bahwa suatu tindakan dilakukan secara konsisten dari awal sampai akhir tanpa berhenti atau menyerah. Mengandung makna "menembus sampai ujung" — seperti satu jalur lurus yang tidak terputus. Dipakai untuk menggambarkan ketekunan, konsistensi, dan penyelesaian penuh.',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜とおす",idText:"menyelesaikan, bertahan sampai selesai (tanpa menyerah atau berhenti)"}],examples:[{jp:"どんなに難しくても、最後まで仕事をやりとおした。",romaji:"",idText:"Sesulit apapun, aku menyelesaikan pekerjaan sampai akhir tanpa menyerah."},{jp:"彼女は反対を受けても自分の意見を言いとおした。",romaji:"",idText:"Meski mendapat penentangan, dia tetap konsisten pada pendapatnya sampai akhir."}]},{id:"exp-8",grammarId:"gn2-00287",title:"Pola: 〜あげる",formula:"V-masu-stem + あげる",meaning:"menyelesaikan (membuat sampai jadi), merampungkan sesuatu",nuanceNotes:'〜あげる sebagai sufiks verba majemuk menyatakan bahwa suatu proses atau karya diselesaikan secara penuh — dari awal sampai akhir. Nuansanya adalah "mengangkat sesuatu ke tingkat selesai/jadi" — sering dipakai untuk karya, produk, atau hasil usaha yang memerlukan proses panjang. Contoh umum: 書き上げる, 作り上げる, 仕上げる.',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜あげる",idText:"menyelesaikan (membuat sampai jadi), merampungkan sesuatu"}],examples:[{jp:"3年間かけてついに小説を書きあげた。",romaji:"",idText:"Setelah 3 tahun, akhirnya aku berhasil menyelesaikan penulisan novel."},{jp:"チームで協力して素晴らしい発表を作りあげた。",romaji:"",idText:"Kami bekerja sama sebagai tim dan berhasil membuat presentasi yang luar biasa."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kata "契機 (けいき)" dalam konteks perkembangan wacana?',sentencePrompt:'Kata "契機 (けいき)" paling tepat diterjemahkan sebagai:',options:["Momentum titik tolak yang memicu perubahan besar","Batas akhir tenggat pembayaran","Sertifikat kelulusan formal","Perjanjian kerja sama jangka pendek"],correctAnswer:"Momentum titik tolak yang memicu perubahan besar",explanation:'"契機 (けいき)" bermakna momentum atau peluang penting yang memicu babak transformasi baru.',diagnosticFeedback:{"Batas akhir tenggat pembayaran":"Salah: Tenggat pembayaran adalah 支払期日 (shiharai kijitsu).","Sertifikat kelulusan formal":"Salah: Sertifikat adalah 証明書 (shoumeisho) atau 免許 (menkyo).","Perjanjian kerja sama jangka pendek":"Salah: Kontrak kerja sama adalah 業務提携 (gyoumu teikei)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat rumpang berikut untuk menyatakan dua hal yang berkembang beriringan:",sentencePrompt:"経済【けいざい】の 復興【ふっこう】_____、国民【こくみん】の 自信【じしん】も 回復【かいふく】していった。",options:["とともに","にすぎず","に反して","にかかわらず"],correctAnswer:"とともに",explanation:"Kebangkitan ekonomi berjalan beriringan dengan pulihnya rasa percaya diri rakyat, sehingga pola yang tepat adalah 〜とともに (seiring dengan / bersamaan dengan).",diagnosticFeedback:{にすぎず:"Salah: にすぎず bermakna hanyalah tidak lebih dari.",に反して:"Salah: に反して bermakna bertolak belakang dengan harapan.",にかかわらず:"Salah: にかかわらず bermakna tanpa memedulikan."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Kaidah Partikel): Manakah kalimat yang menggunakan partikel 〜を契機に secara benar?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["海外【かいがい】留学【りゅうがく】を 契機【けいき】に、異文化【いぶんか】理解【りかい】への 関心【かんしん】が 深【ふか】まった。","海外【かいがい】留学【りゅうがく】に 契機【けいき】に、関心【かんしん】が 深まった。","海外【かいがい】留学【りゅうがく】で 契機【けいき】に、関心が 深まった。","海外【かいがい】留学【りゅうがく】の 契機【けいき】に、関心が 深まった。"],correctAnswer:"海外【かいがい】留学【りゅうがく】を 契機【けいき】に、異文化【いぶんか】理解【りかい】への 関心【かんしん】が 深【ふか】まった。",explanation:"Kaidah paten pola ini mewajibkan partikel を sebelum kata 契機 (N + を契機に).",diagnosticFeedback:{"海外【かいがい】留学【りゅうがく】に 契機【けいき】に、関心【かんしん】が 深まった。":"Kekeliruan Partikel: Partikel に sebelum 契機 salah dan menimbulkan pengulangan partikel yang rancu.","海外【かいがい】留学【りゅうがく】で 契機【けいき】に、関心が 深まった。":"Kekeliruan Partikel: Partikel で tidak dapat digunakan dalam konstruksi pola ini.","海外【かいがい】留学【りゅうがく】の 契機【けいき】に、関心が 深まった。":'Kekeliruan Modifikasi: Meskipun 留学の契機 bermakna "alasan studi", sebelum に wajib diawali klausa を契機に jika berfungsi sebagai frasa adverbial.'}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat pernyataan etika korporat yang padu:",sentencePrompt:"Susunlah frasa-frasa berikut agar membentuk kalimat yang gramatikal:",options:["事業の 拡大とともに、 環境への 配慮が 強く 求められる。","環境への 配慮が 事業の 拡大とともに、 強く 求められる。","強く 求められる。 事業の 拡大とともに、 環境への 配慮が","事業の 拡大とともに、 強く 求められる。 環境への 配慮が"],correctAnswer:"事業の 拡大とともに、 環境への 配慮が 強く 求められる。",explanation:"Struktur baku: Keterangan simultan (事業の拡大とともに) + Subjek tuntutan (環境への配慮が) + Keterangan (強く) + Predikat pasif (求められる).",diagnosticFeedback:{"環境への 配慮が 事業の 拡大とともに、 強く 求められる。":"Kekeliruan Alur: Menaruh subjek di depan membuat klausa simultan membelah kalimat.","強く 求められる。 事業の 拡大とともに、 環境への 配慮が":"Kekeliruan Predikat: Predikat diletakkan di awal kalimat.","事業の 拡大とともに、 強く 求められる。 環境への 配慮が":"Kekeliruan Urutan Modifikasi: Kata keterangan 強く dan predikat 求められる mendahului subjeknya."},tokens:["事業の","拡大とともに、","環境への配慮が","強く求められる。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Respons Tanggung Jawab): Saat Tanaka berpesan: 「企業の 成長と ともに、コンプライアンスの 意識も より 一層高めていきましょう」, apa respons terbaik Anda?",sentencePrompt:"Pilihlah tanggapan yang menunjukkan kematangan etika bisnis:",options:["はい！ 技術の 向上と ともに、社会的な 責任も しっかり 果たせるよう 努力いたします。","法律を守っていたら 儲からないので、適当に ごまかしましょう。","コンプライアンスなんて 形式だけの ものですから、無視して 構いませんよ。","成長さえ すれば、社会的な 責任など どうでも いいはずです。"],correctAnswer:"はい！ 技術の 向上と ともに、社会的な 責任も しっかり 果たせるよう 努力いたします。",explanation:"Menyeimbangkan kemajuan teknologi dengan pemenuhan tanggung jawab sosial perusahaan (CSR).",diagnosticFeedback:{"法律を守っていたら 儲からないので、適当に ごまかしましょう。":"Tindakan Kriminal: Mengabaikan hukum demi laba adalah pelanggaran fatal kepatuhan bisnis.","コンプライアンスなんて 形式だけの ものですから、無視して 構いませんよ。":"Sikap Meremehkan: Mengabaikan kepatuhan regulasi dapat berujung pencabutan izin usaha.","成長さえ すれば、社会的な 責任など どうでも いいはずです。":"Anti-Sosial: Mengabaikan tanggung jawab sosial bertentangan dengan prinsip keberlanjutan (SDGs)."}}],can_do_challenge:{statement:"Bisa merangkum transformasi organisasi, menghubungkan dua fakta yang berjalan seiring, dan menceritakan titik balik kemajuan.",situation:"Ruang direksi pelabuhan Yokohama, pukul 16.30.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜の末に!",modelAnswer:"はい、田中【たなか】さん！ あの トラブルを 契機【けいき】として 導入【どうにゅう】した クラウド 管理【かんり】に より、作業【さぎょう】の 効率【こうりつ】化【か】と ともに、情報【じょうほう】共有【きょうゆう】の スピードも 飛躍【ひやく】的【てき】に 向上【こうじょう】いたしました。",modelAnswerId:"Ya, Tanaka-san! Berkat manajemen cloud yang kita adopsi bermula dari momentum kendala tersebut, seiring dengan peningkatan efisiensi kerja, kecepatan berbagi informasi pun melonjak drastis.",culturalEtiquette:"Dalam budaya korporat Jepang, merefleksikan kegagalan masa lalu sebagai momentum kebangkitan (契機 - Keiki) adalah tanda kepemimpinan matang.",skillUnlocked:["Menguasai formulasi pola 〜の末に","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Pencapaian Bertahap, Batas Waktu & Mileston Kerja"]},pocket_summary:{keyFormula:"V-dict / N + とともに (seiring dengan / bersamaan dengan), N + を契機に / を契機として (bermula dari momentum / bertitik tolak dari)",coreWords:["契機【けいき】 (peluang; kesempatan)","転換【てんかん】 (mengkonversi; mengalihkan)","促進【そくしん】 (promosi, dorongan, percepatan kemajuan)","向上【こうじょう】 (elevation; rise)"],coreWarning:"Jangan gunakan 〜を契機に untuk kebetulan kecil sehari-hari; pola ini menuntut adanya dampak perubahan arah yang signifikan.",quickDialogue:"A: ブディさん、先月【せんげつ】の システム トラブル... → B: はい、田中【たなか】さん！ あの トラブルを 契機..."}}},e={"les-n2-u03-01":{pedagogical_framework:{what:{summary:"Menguasai pola 〜きる / 〜きれる (mampu menuntaskan hingga tetes terakhir) dan bentuk negatif 〜きれない (kewalahan melebihi batas kapasitas).",canDo:"Bisa melaporkan penyelesaian beban komputasi masif, mengidentifikasi kapasitas maksimal server, dan meminta eskalasi sumber daya saat overload.",targetPatterns:["V-stem + きる / きれる (menuntaskan tuntas / mampu menyelesaikan hingga habis)","V-stem + きれない (tidak mampu menampung / terlalu banyak hingga tak tuntas)"],coreVocabSample:["裁【さば】く","処理【しょり】","容量【ようりょう】","負荷【ふか】","限界【げんかい】","確保【かくほ】する","維持【いじ】","点検【てんけん】"]},sensei_context:{sceneIntro:"Pusat operasi data lini perakitan Nagoya. Kenji (IT Lead) meneliti lonjakan antrean data sensor IoT otomotif yang menembus batas throughput server.",dailyMission:'Mampu menjelaskan batasan kapasitas pemrosesan menggunakan pola "kirenai" dan solusi arsitektural menggunakan "kitte / kiru" kepada pimpinan teknis.',whyOrder:"Setelah membahas tahapan waktu di Unit 1-2, Unit 3 berfokus pada aspek ketuntasan tindakan (Aspectual Verbs) yang sangat vital dalam rekayasa sistem."},cultural_notes:{title:"Manajemen Kapasitas & Eskalasi Insiden (キャパシティ管理とエスカレーション)",etiquette:"Mengakui secara terus terang bahwa beban kerja sudah mencapai batas (処理しきれない) jauh lebih dihargai daripada berpura-pura sanggup lalu memicu kegagalan sistemik.",taboos:'Jangan memaksakan diri mengatakan "Dekimasu" jika data empiris menunjukkan kapasitas memori atau fisik sudah berada di zona bahaya merah.'},pronunciation_tips:{title:'Tekanan Tegas pada Sufiks Verba "kiru / kirenai"',moraNote:"Sufiks ki-ru dan ki-re-na-i diucapkan dengan artikulasi tegas pada mora ki untuk menandai batas tuntas tindakan.",soundTip:"Bentuk sambung te-kei 切って (kitte) memiliki mora sokon yang rapat dan kuat."},common_pitfalls:[{title:"Salah Menempatkan Bentuk Verba Sebelum 切る",caseScenario:'Memasukkan kata kerja bentuk kamus sebelum kiru: "tsukau-kiru".',pitfallWarning:'"予算【よさん】を 使【つか】う切【き】った。"',rightSolution:'"予算【よさん】を 使【つか】い切【き】った。"',explanation:"Pola verba majemuk 切る hanya menerima bentuk ます-stem (V-stem), bukan bentuk kamus."},{title:"Tertukar Antara 〜きれない (Kapasitas Meluap) vs 〜られない (Potensial Biasa)",caseScenario:"Ingin menyatakan bahwa jumlah pendaftar terlalu banyak hingga tak muat di ruangan.",pitfallWarning:'"応募者【おうぼしゃ】が 多【おお】すぎて、部屋【へや】に 入【はい】らない。"',rightSolution:'"応募者【おうぼしゃ】が 多【おお】すぎて、数【かぞ】えきれない / 収容【しゅうよう】しきれない。"',explanation:"〜きれない secara spesifik mengekspresikan ketidakmampuan yang diakibatkan oleh kuantitas atau beban yang melampaui batas absolut."}],who_and_when:{situational_context:"Laporan insiden teknis server, audit anggaran proyek tahunan, atau evaluasi beban kerja staf.",social_relations:"Koordinasi teknis tingkat tinggi antara Lead Architect dan Senior Engineer.",when_not_to_use:"Jangan gunakan pada hal-hal yang tidak memiliki konsep ketuntasan hingga akhir."},scenario:{title:"Lonjakan Beban Data Sensor IoT Perakitan Akhir Tahun",setting:"Ruang kendali arsitektur sistem Nagoya, pukul 11.15.",narrative:"Kenji dan Budi menganalisis antrean 100.000 transaksi IoT per detik yang berpotensi meluap di luar kapasitas penyangga."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Systems Architect",avatar:"👨‍💻",jp:"ブディさん、年末【ねんまつ】の 増産【ぞうさん】に 伴【ともな】い、IoT センサーの 送信【そうしん】データが 毎秒【まいびょう】10万件【じゅうまんけん】に 達【たっ】しました。現状【げんじょう】の サーバーで 処理【しょり】しきれていますか？",furigana:"ブディさん、年末の 増産に 伴い、IoT センサーの 送信データが 毎秒10万件に 達しました。現状の サーバーで 処理しきれていますか？",romaji:"Budi-san, nenmatsu no zousan ni tomonai, IoT sensaa no soushin deeta ga maibyou juumanken ni tasshimashita. Genjou no saabaa de shorishikirete imasu ka?",idText:"Budi, seiring lonjakan produksi akhir tahun, data transmisi sensor IoT menembus 100.000 data per detik. Apakah server kita saat ini mampu menuntaskan pemrosesannya?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"Kenjiさん、旧【きゅう】システムでは 正直【しょうじき】さばききれない 状態【じょうたい】でした。しかし、今朝【けさ】新【あたら】しい 分散【ぶんさん】キューを 配備【はいび】し、全【すべ】ての トランザクションを 遅延【ちえん】なく 処理【しょり】しきる 構成【こうせい】に 刷新【さっしん】いたしました！",furigana:"Kenjiさん、旧システムでは 正直さばききれない 状態でした。しかし、今朝新しい 分散キューを 配備し、全ての トランザクションを 遅延なく 処理しきる 構成に 刷新いたしました！",romaji:"Kenji-san, kyuu shisutemu dewa shoujiki sabakikirenai joutai deshita. Shikashi, kesa atarashii bunsankyuu o haibi shi, subete no toranzakushon o chien naku shorishikiru kousei ni sasshin itashimashita!",idText:"Kenji-san, pada sistem lama sejujurnya kita kewalahan tak sanggup menampung beban tersebut. Akan tetapi, pagi tadi kami menerapkan distributed queue baru dan memperbarui konfigurasi agar mampu menuntaskan seluruh transaksi tanpa latensi!"},{id:"d3",speaker:"Kenji",speakerRole:"Senior Systems Architect",avatar:"👨‍💻",jp:"見事【みごと】な 対策【たいさく】ですね！ メモリの リソースを 最後【さいご】まで 使【つか】いきっても サーバーが 停止【ていし】しないよう、オートスケールの 上限【じょうげん】も 確認【かくにん】しておいてください。",furigana:"見事な 対策ですね！ メモリの リソースを 最後まで 使いきっても サーバーが 停止しないよう、オートスケールの 上限も 確認しておいてください。",romaji:"Migoto na taisaku desu ne! Memori no risoosu o saigo made tsukaikitte mo saabaa ga teishi shinai you, ootosukeeru no jougen mo kakunin shite oite kudasai.",idText:"Solusi yang brilian! Tolong pastikan pula batas atas auto-scaling agar seandainya sumber daya memori terkuras tuntas sekalipun, server tidak akan mogok."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ クラウドの 冗長【じょうちょう】化【か】を 徹底【てってい】し、万全【ばんぜん】の 体制【たいせい】で 年末【ねんまつ】の ピークを 守【まも】り抜【ぬ】きます。",furigana:"承知いたしました！ クラウドの 冗長化を 徹底し、万全の 体制で 年末の ピークを 守り抜きます。",romaji:"Shouchi itashimashita! Kuraudo no jouchouka o tettei shi, banzen no taisei de nenmatsu no piiku o mamorinukimasu.",idText:"Dimengerti! Kami akan memastikan redundansi cloud secara menyeluruh dan menjaga puncak beban akhir tahun dengan kesiapan prima hingga tuntas."}],vocab_breakdown:[{id:"vg-n2-00582",word:"売り切れる",reading:"うりきれる",romaji:"urikireru",meaning:"terjual habis",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 売り切れる / 〜に関する 売り切れる dalam wacana profesional.",exampleSentence:{jp:"そのケーキはすぐに売り切れるでしょう。",furigana:"そのケーキはすぐに売り切れるでしょう。",romaji:"urikireru",idText:"Kuenya mungkin akan segera terjual habis."},pitch:{pattern:4,category:"nakadaka",mora_count:5,downstep_mora:4,contour:"ウリキレ＼ル"}},{id:"vg-n2-00599",word:"遠足",reading:"えんそく",romaji:"ensoku",meaning:"trip; hike",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 遠足 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"全体として、遠足は楽しかった。",furigana:"全体として、遠足は楽しかった。",romaji:"ensoku",idText:"Secara keseluruhan, tamasya itu menyenangkan."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"エンソク￣"}},{id:"vg-n2-00600",word:"延長",reading:"えんちょう",romaji:"enchou",meaning:"extension; elongation",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 延長 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"宿泊をもう一晩延長できますか。",furigana:"宿泊をもう一晩延長できますか。",romaji:"enchou",idText:"Bolehkah saya memperpanjang masa menginap saya satu malam lagi?"},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"エンチョウ￣"}},{id:"vg-n2-00602",word:"追い掛ける",reading:"おいかける",romaji:"oikakeru",meaning:"mengejar atau mengejar seseorang",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 追い掛ける / 〜に関する 追い掛ける dalam wacana profesional.",exampleSentence:{jp:"犬が猫を追いかけていた。",furigana:"犬が猫を追いかけていた。",romaji:"oikakeru",idText:"Seekor anjing sedang mengejar kucing."},pitch:{pattern:4,category:"nakadaka",mora_count:5,downstep_mora:4,contour:"オイカケ＼ル"}},{id:"vg-n2-00603",word:"追い越す",reading:"おいこす",romaji:"oikosu",meaning:"lulus",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 追い越す / 〜に関する 追い越す dalam wacana profesional.",exampleSentence:{jp:"うさぎはかめに追い越された。",furigana:"うさぎはかめに追い越された。",romaji:"oikosu",idText:"Kelinci dikalahkan oleh kura-kura."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"オイコ＼ス"}},{id:"vg-n2-00605",word:"応援",reading:"おうえん",romaji:"ouen",meaning:"aid; assistance",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 応援 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"何事が起ころうとも、君を応援するよ。",furigana:"何事が起ころうとも、君を応援するよ。",romaji:"ouen",idText:"Aku akan mendampingimu apapun yang terjadi."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"オウエン￣"}},{id:"vg-n2-00608",word:"応接",reading:"おうせつ",romaji:"ousetsu",meaning:"penerimaan",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 応接 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"応接を使います。",furigana:"応接を使います。",romaji:"ousetsu",idText:"Menggunakan reception."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"オウセツ￣"}},{id:"vg-n2-00609",word:"応対",reading:"おうたい",romaji:"outai",meaning:"menerima; berurusan dengan",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 応対 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"その女店員が私に応対してくれた。",furigana:"その女店員が私に応対してくれた。",romaji:"outai",idText:"Gadis penjual itu menungguku."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"オウタイ￣"}}],explanations:[{id:"exp-1",grammarId:"gn2-00288",title:"Pola: 〜あがる",formula:"V-masu-stem + あがる",meaning:"selesai, rampung (intransitif — proses selesai dengan sendirinya)",nuanceNotes:'〜あがる adalah bentuk intransitif dari 〜あげる, menyatakan bahwa suatu proses atau karya telah selesai/rampung — dengan penekanan pada hasil akhir yang terbentuk, bukan pada siapa yang menyelesaikannya. Sering dipakai untuk produk, hasil kerja, atau kondisi yang "naik ke tahap selesai."',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜あがる",idText:"selesai, rampung (intransitif — proses selesai dengan sendirinya)"}],examples:[{jp:"新しいアプリがやっと出来あがった。",romaji:"",idText:"Aplikasi baru itu akhirnya selesai dibuat."},{jp:"ケーキが焼きあがったら声をかけてください。",romaji:"",idText:"Kalau kuenya sudah selesai dipanggang, tolong beritahu saya."}]},{id:"exp-2",grammarId:"gn2-00291",title:"Pola: 〜だす",formula:"V-masu-stem + だす",meaning:"mulai tiba-tiba, mengeluarkan (secara spontan atau tak terduga)",nuanceNotes:"〜だす menyatakan bahwa suatu tindakan atau peristiwa dimulai secara tiba-tiba atau mendadak, sering kali tanpa peringatan. Tidak seperti 〜はじめる yang menyatakan permulaan yang terencana atau alami, 〜だす menekankan aspek spontan atau tak terduga dari permulaan tindakan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜だす",idText:"mulai tiba-tiba, mengeluarkan (secara spontan atau tak terduga)"}],examples:[{jp:"急に子供が泣きだした。",romaji:"",idText:"Tiba-tiba anak itu mulai menangis."},{jp:"映画が始まったとたん、雨が降りだした。",romaji:"",idText:"Tepat saat film dimulai, hujan tiba-tiba turun."}]},{id:"exp-3",grammarId:"gn2-00292",title:"Pola: 〜はじめる",formula:"V-masu-stem + はじめる",meaning:"mulai melakukan ...",nuanceNotes:"〜はじめる menyatakan permulaan suatu tindakan. Dipakai secara luas untuk menyatakan bahwa seseorang mulai melakukan sesuatu, baik yang terencana maupun yang berlangsung secara alami dan bertahap. Ini adalah salah satu sufiks aspektual paling dasar dan paling sering digunakan dalam bahasa Jepang.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜はじめる",idText:"mulai melakukan ..."}],examples:[{jp:"日本語を勉強しはじめたのは去年のことだ。",romaji:"",idText:"Aku mulai belajar bahasa Jepang tahun lalu."},{jp:"やっと外が明るくなりはじめた。",romaji:"",idText:"Akhirnya di luar mulai terang — fajar pun datang."}]},{id:"exp-4",grammarId:"gn2-00293",title:"Pola: 〜おわる",formula:"V-masu-stem + おわる",meaning:"selesai melakukan ...",nuanceNotes:"〜おわる menyatakan bahwa suatu tindakan telah selesai dilakukan. Pasangan alami dari 〜はじめる (mulai) dan 〜つづける (lanjut). Dipakai untuk menyatakan titik akhir dari suatu kegiatan — saat seseorang berhenti karena sudah selesai, bukan karena terpaksa berhenti.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜おわる",idText:"selesai melakukan ..."}],examples:[{jp:"レポートを書きおわったのでやっと休める。",romaji:"",idText:"Laporan sudah selesai ditulis, jadi akhirnya bisa istirahat."},{jp:"全員が発表しおわったら、質問の時間にします。",romaji:"",idText:"Setelah semua orang selesai presentasi, kita akan masuk ke sesi tanya jawab."}]},{id:"exp-5",grammarId:"gn2-00294",title:"Pola: 〜つづける",formula:"V-masu-stem + つづける",meaning:"terus melakukan ..., melanjutkan ...",nuanceNotes:"〜つづける menyatakan bahwa suatu tindakan berlanjut terus-menerus tanpa henti. Ini adalah sufiks aspektual yang menandai kontinuitas — kebalikan dari penyelesaian (おわる) atau permulaan (はじめる). Dapat dipakai untuk tindakan yang disengaja maupun kondisi yang berlangsung terus.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜つづける",idText:"terus melakukan ..., melanjutkan ..."}],examples:[{jp:"雨が3日間降りつづけた。",romaji:"",idText:"Hujan terus turun selama 3 hari berturut-turut tanpa henti."},{jp:"諦めずに練習しつづけた結果、大会で優勝できた。",romaji:"",idText:"Berkat terus berlatih tanpa menyerah, aku bisa memenangkan kejuaraan."}]},{id:"exp-6",grammarId:"gn2-00297",title:"Pola: 〜にわたる / 〜にわたって",formula:"N (waktu / tempat / jangkauan) + にわたる / にわたって",meaning:"melintasi, mencakup (rentang waktu atau wilayah yang luas)",nuanceNotes:"〜にわたる / 〜にわたって menyatakan bahwa suatu hal mencakup, melintasi, atau berlangsung di seluruh rentang waktu atau ruang yang disebutkan. Dipakai untuk menunjukkan bahwa sesuatu tersebar atau berlangsung di sepanjang suatu periode atau wilayah secara menyeluruh.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜にわたる / 〜にわたって",idText:"melintasi, mencakup (rentang waktu atau wilayah yang luas)"}],examples:[{jp:"交渉は3日間にわたって行われた。",romaji:"",idText:"Negosiasi berlangsung selama 3 hari penuh."},{jp:"この問題は広い地域にわたる環境被害を引き起こした。",romaji:"",idText:"Masalah ini menimbulkan kerusakan lingkungan yang mencakup wilayah yang sangat luas."}]},{id:"exp-7",grammarId:"gn2-00298",title:"Pola: 〜かける",formula:"V-masu-stem + かける",meaning:"setengah jalan, hampir ..., mulai tapi belum selesai",nuanceNotes:"〜かける menyatakan bahwa suatu tindakan sudah dimulai tetapi belum selesai, atau hampir terjadi tetapi tidak jadi. Ada dua nuansa utama: (1) dalam proses tapi terganggu di tengah jalan (食べかける = sudah mulai makan tapi belum selesai); (2) hampir terjadi tapi tidak jadi/dicegah (死にかける = hampir mati, 言いかける = hampir mengatakan sesuatu tapi urung).",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜かける",idText:"setengah jalan, hampir ..., mulai tapi belum selesai"}],examples:[{jp:"食べかけたところで電話が鳴って席を立った。",romaji:"",idText:"Tepat saat baru mau makan, telepon berbunyi dan aku berdiri dari kursi."},{jp:"彼は事故で死にかけたが、奇跡的に助かった。",romaji:"",idText:"Dia hampir meninggal dalam kecelakaan itu, tapi ajaibnya selamat."}]},{id:"exp-8",grammarId:"gn2-00299",title:"Pola: 〜かけの",formula:"V-masu-stem + かけの + N",meaning:"yang setengah jalan, yang belum selesai (modifier atributif)",nuanceNotes:"〜かけの adalah bentuk atributif dari 〜かける, dipakai sebelum nomina untuk menerangkan benda atau hal yang sedang dalam kondisi setengah jalan atau belum selesai. Menggambarkan sesuatu yang prosesnya sudah dimulai tapi terhenti atau belum rampung.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜かけの",idText:"yang setengah jalan, yang belum selesai (modifier atributif)"}],examples:[{jp:"読みかけの本を机の上に置いてきた。",romaji:"",idText:"Aku meninggalkan buku yang sedang dibaca di atas meja."},{jp:"冷蔵庫に食べかけのケーキが残っている。",romaji:"",idText:"Di kulkas masih ada kue yang sudah dimakan sebagian."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah padanan makna istilah "冗長化 (じょうちょうか)" dalam arsitektur server?',sentencePrompt:'Istilah "冗長化 (じょうちょうか)" memiliki arti:',options:["Penyediaan sistem cadangan ganda untuk mencegah downtime","Penghapusan seluruh data cadangan","Pembatasan hak akses pengguna","Pemadaman daya server secara berkala"],correctAnswer:"Penyediaan sistem cadangan ganda untuk mencegah downtime",explanation:'"冗長化 (じょうちょうか)" adalah teknik redundansi: menduplikasi komponen kritis agar sistem tetap berjalan jika terjadi kegagalan.',diagnosticFeedback:{"Penghapusan seluruh data cadangan":"Salah: Menghapus cadangan adalah バックアップ削除 (bakkuappu sakujo).","Pembatasan hak akses pengguna":"Salah: Pembatasan akses adalah アクセス制限 (akusesu seigen).","Pemadaman daya server secara berkala":"Salah: Pemadaman daya adalah 定期停電 (teiki teiden)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat rumpang berikut untuk menyatakan beban yang terlalu banyak hingga tak sanggup dihitung:",sentencePrompt:"彼【かれ】の 功績【こうせき】は あまりにも 大【おお】きく、言葉【ことば】では 感謝【かんしゃ】の 気持【きも】ちを 伝【つた】え_____。",options:["きれない","きる","きれる","きった"],correctAnswer:"きれない",explanation:"Rasa terima kasih yang begitu besar hingga melampaui batas ungkapan kata-kata menuntut bentuk negatif potensial 〜きれない (tak sanggup tuntas).",diagnosticFeedback:{きる:"Salah: きる adalah bentuk positif transitif, kontradiktif dengan makna luapan rasa yang tak tuntas diungkapkan.",きれる:"Salah: きれる menyatakan sanggup tuntas secara tuntas, padahal konteksnya adalah rasa syukur tak terhingga.",きった:"Salah: きった adalah bentuk lampau positif."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Koneksi Verba): Manakah kalimat yang menggunakan konjugasi 〜きる secara benar?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["フル マラソン 42.195キロを 最後【さいご】まで 走【はし】りきった。","フル マラソンを 走【はし】るきった。","フル マラソンを 走【はし】ってきった。","フル マラソンを 走【はし】らきった。"],correctAnswer:"フル マラソン 42.195キロを 最後【さいご】まで 走【はし】りきった。",explanation:"Kata kerja 走る (hashiru) memiliki stem bentuk ます yaitu 走り (hashiri), disambung dengan きった menjadi 走りきった (tuntas berlari hingga akhir).",diagnosticFeedback:{"フル マラソンを 走【はし】るきった。":"Kekeliruan Konjugasi: Menggunakan bentuk kamus (走る). Wajib menggunakan V-stem (走り).","フル マラソンを 走【はし】ってきった。":"Kekeliruan Konjugasi: Menggunakan bentuk te-kei (走って) sebelum kiru tidak gramatikal.","フル マラソンを 走【はし】らきった。":"Kekeliruan Konjugasi: Bentuk *走ら bukan stem penghubung yang valid."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat resolusi komitmen yang padu:",sentencePrompt:"Susunlah frasa-frasa berikut agar membentuk kalimat yang gramatikal:",options:["一度 自分で 決めたことは、 途中で 諦めずに やりきるべきだ。","途中で 諦めずに 一度 自分で 決めたことは、 やりきるべきだ。","やりきるべきだ。 一度 自分で 決めたことは、 途中で 諦めずに","一度 自分で 決めたことは、 やりきるべきだ。 途中で 諦めずに"],correctAnswer:"一度 自分で 決めたことは、 途中で 諦めずに やりきるべきだ。",explanation:"Topik (一度自分で決めたことは) + Keterangan cara (途中で諦めずに) + Predikat kewajaran (やりきるべきだ).",diagnosticFeedback:{"途中で 諦めずに 一度 自分で 決めたことは、 やりきるべきだ。":"Kekeliruan Urutan: Keterangan cara mendahului topik utama membuat fokus kalimat bergeser.","やりきるべきだ。 一度 自分で 決めたことは、 途中で 諦めずに":"Kekeliruan Predikat: Predikat diletakkan di paling depan.","一度 自分で 決めたことは、 やりきるべきだ。 途中で 諦めずに":"Kekeliruan Struktur: Predikat memutus klausa keterangan cara di belakangnya."},tokens:["一度自分で","決めたことは、","途中で諦めずに","やりきるべきだ。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Respons Ketahanan Sistem): Saat Kenji mengingatkan: 「メモリを 最後まで 使いきっても サーバーが 停止しないよう、上限も 確認しておいてください」, bagaimana respons Anda?",sentencePrompt:"Pilihlah jawaban yang paling mencerminkan dedikasi keandalan sistem (SRE):",options:["承知いたしました！ クラウドの 冗長化を 徹底し、万全の 体制で 年末の ピークを 守り抜きます。","サーバーが 落ちたら 落ちたで、お正月休みを ゆっくり 満喫しますね。","オートスケールなんて 設定が 面倒なので、サーバー台数は 固定で いきましょう。","ユーザーが アクセスしすぎるのが 悪いので、アクセスを 全部 遮断します。"],correctAnswer:"承知いたしました！ クラウドの 冗長化を 徹底し、万全の 体制で 年末の ピークを 守り抜きます。",explanation:"Sikap proaktif yang mengedepankan ketersediaan layanan dan ketahanan beban tinggi.",diagnosticFeedback:{"サーバーが 落ちたら 落ちたで、お正月休みを ゆっくり 満喫しますね。":"Tidak Bertanggung Jawab: Membiarkan sistem tumbang demi liburan melanggar etika engineering.","オートスケールなんて 設定が 面倒なので、サーバー台数は 固定で いきましょう。":"Malas & Berisiko: Menolak konfigurasi elastisitas cloud memicu pemborosan atau down fatal.","ユーザーが アクセスしすぎるのが 悪いので、アクセスを 全部 遮断します。":"Melanggar Bisnis: Memblokir pengguna yang sah menghancurkan reputasi dan pendapatan perusahaan."}}],can_do_challenge:{statement:"Bisa melaporkan penyelesaian beban komputasi masif, mengidentifikasi kapasitas maksimal server, dan meminta eskalasi sumber daya saat overload.",situation:"Ruang kendali arsitektur sistem Nagoya, pukul 11.15.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜あがる!",modelAnswer:"Kenjiさん、旧【きゅう】システムでは 正直【しょうじき】さばききれない 状態【じょうたい】でした。しかし、今朝【けさ】新【あたら】しい 分散【ぶんさん】キューを 配備【はいび】し、全【すべ】ての トランザクションを 遅延【ちえん】なく 処理【しょり】しきる 構成【こうせい】に 刷新【さっしん】いたしました！",modelAnswerId:"Kenji-san, pada sistem lama sejujurnya kita kewalahan tak sanggup menampung beban tersebut. Akan tetapi, pagi tadi kami menerapkan distributed queue baru dan memperbarui konfigurasi agar mampu menuntaskan seluruh transaksi tanpa latensi!",culturalEtiquette:"Mengakui secara terus terang bahwa beban kerja sudah mencapai batas (処理しきれない) jauh lebih dihargai daripada berpura-pura sanggup lalu memicu kegagalan sistemik.",skillUnlocked:["Menguasai formulasi pola 〜あがる","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Ketuntasan Tindakan, Batas Kapasitas & Kelelahan Fisik"]},pocket_summary:{keyFormula:"V-stem + きる / きれる (menuntaskan tuntas / mampu menyelesaikan hingga habis), V-stem + きれない (tidak mampu menampung / terlalu banyak hingga tak tuntas)",coreWords:["裁【さば】く (hakim)","処理【しょり】 (pemrosesan, penanganan, pengolahan)","容量【ようりょう】","負荷【ふか】"],coreWarning:'Jangan memaksakan diri mengatakan "Dekimasu" jika data empiris menunjukkan kapasitas memori atau fisik sudah berada di zona bahaya merah.',quickDialogue:"A: ブディさん、年末【ねんまつ】の 増産【ぞうさん】に... → B: Kenjiさん、旧【きゅう】システムでは 正直【し..."}},"les-n2-u03-02":{pedagogical_framework:{what:{summary:"Menguasai pola 〜抜く (ぬく - bertahan berjuang menuntaskan hingga akhir melewati rintangan) dan 〜あげる (menuntaskan karya bernilai).",canDo:"Bisa menceritakan perjuangan mengatasi krisis teknis berat, merefleksikan daya tahan tim, dan mengapresiasi karya tuntas.",targetPatterns:["V-stem + 抜く (bertahan menuntaskan hingga akhir melewati kesulitan)","V-stem + あげる / あがる (menyelesaikan tuntas hingga menjadi wujud nyata)"],coreVocabSample:["克服【こくふく】する","完遂【かんすい】","試練【しれん】","結晶【けっしょう】","協力【きょうりょく】","精巧【せいこう】","粘【ねば】り","実績【じっせき】"]},sensei_context:{sceneIntro:"Ruang evaluasi proyek Nagoya. Tim baru saja melewati masa genting migrasi arsitektur cloud tanpa satu pun galat selama 72 jam nonstop.",dailyMission:'Mampu merefleksikan kerja keras dan ketahanan mental tim menggunakan "nuku" dan "ageru" dalam laporan refleksi Kaizen.',whyOrder:'Jika pola "kiru" berfokus pada habisnya kapasitas, pola "nuku" menekankan tekad psikologis dan daya juang mengatasi kesulitan luar biasa.'},cultural_notes:{title:"Semangat Ketekunan dan Daya Tahan (やり抜く力 - Grit) di Jepang",etiquette:"Menyelesaikan tugas sulit hingga tuntas (やり抜く) adalah nilai tertinggi dalam etos kerja Jepang. Hal ini mencerminkan keandalan dan loyalitas profesional.",taboos:"Hindari memakai 〜抜く untuk pekerjaan ringan yang selesai dalam waktu singkat tanpa ada hambatan berarti."},pronunciation_tips:{title:'Artikulasi Kuat pada Verba "nuku"',moraNote:"Lafalkan nu-ku dengan vokal u yang bulat dan berbobot.",soundTip:"Bentuk lampau 抜いた (nuita) dilafalkan mengalir tanpa memanjangkan mora i."},common_pitfalls:[{title:"Tertukar Antara 〜抜く (Menembus Hambatan Berat) vs 〜きる (Sekadar Menghabiskan)",caseScenario:"Menggambarkan perjuangan berpikir keras memeras otak selama seminggu untuk memecahkan misteri bug.",pitfallWarning:'"考【かんが】えきった 末【すえ】に、解決【かいけつ】策【さく】を 見【み】つけた。"',rightSolution:'"考【かんが】え抜【ぬ】いた 末【すえ】に、解決【かいけつ】策【さく】を 見【み】つけ出【だ】した。"',explanation:"〜考え抜く menyiratkan proses kontemplasi mendalam yang penuh perjuangan mental melewati rintangan berat."},{title:"Memasukkan Kata Kerja Pasif Sebelum 抜く",caseScenario:"Menggunakan verba yang tidak mengandung kehendak kemauan keras manusia.",pitfallWarning:'"雨【あめ】が 降【ふ】り抜【ぬ】いた。"',rightSolution:'"困難【こんなん】を 乗【の】り越【こ】え、最後【さいご】まで 走【はし】り抜【ぬ】いた。"',explanation:"〜抜く menuntut subjek yang memiliki kehendak sadar (Volitional) untuk berjuang melewati penderitaan."}],who_and_when:{situational_context:"Pidato penutupan proyek, evaluasi kinerja tahunan, atau artikel inspiratif profil keberhasilan tim.",social_relations:"Apresiasi kolegial yang tulus antara manajer proyek dan seluruh jajaran staf pelaksana.",when_not_to_use:"Jangan gunakan pada aktivitas santai tanpa tantangan."},scenario:{title:"Refleksi Keberhasilan Rilis Arsitektur Cloud Tanpa Hambatan",setting:"Ruang serbaguna kantor Nagoya, pukul 17.00.",narrative:"Kenji dan Budi mengapresiasi daya juang tim lintas negara yang berhasil mempertahankan stabilitas sistem selama rilis kritis."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Systems Architect",avatar:"👨‍💻",jp:"ブディさん、72時間【じかんにん】連続【れんぞく】の クラウド 移行【いこう】ミッション、トラブルなく 完了【かんりょう】いたしましたね。本当【ほんとう】に お疲【つか】れ様【さま】でした！",furigana:"ブディさん、72時間連続の クラウド 移行ミッション、トラブルなく 完了いたしましたね。本当に お疲れ様でした！",romaji:"Budi-san, nanajuuni jikan renzoku no kuraudo ikou misshon, toraburu naku kanryou itashimashita ne. Hontou ni otsukaresama deshita!",idText:"Budi, misi migrasi cloud 72 jam nonstop telah selesai tanpa kendala. Benar-benar kerja keras yang luar biasa!"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ありがとうございます！ 予期【よき】せぬ 障害【しょうがい】も 多【おお】く 苦【くる】しい 局面【きょくめん】ばかりでしたが、チーム 全員【ぜんいん】で 議論【ぎろん】を 重【かさ】ね、知恵【ちえ】を 絞【しぼ】り抜【ぬ】いて 乗り越【のりこ】える ことが できました。",furigana:"ありがとうございます！ 予期せぬ 障害も 多く 苦しい 局面ばかりでしたが、チーム 全員で 議論を 重ね、知恵を 絞り抜いて 乗り越える ことが できました。",romaji:"Arigatou gozaimasu! Yokisenu shougai mo ooku kurushii kyokumen bakari deshita ga, chiimu zenin de giron o kasane, chie o shiborinuite norikoeru koto ga dekimashita.",idText:"Terima kasih banyak! Kendala tak terduga memang banyak dan situasinya serba genting, tetapi seluruh tim berdiskusi intensif, memeras segenap daya pikir hingga tuntas, dan berhasil melaluinya."},{id:"d3",speaker:"Kenji",speakerRole:"Senior Systems Architect",avatar:"👨‍💻",jp:"最後【さいご】まで 諦【あきら】めずに やり抜【ぬ】いた 姿勢【しせい】は、全社【ぜんしゃ】の 誇【ほこ】りです。この 経験【けいけん】を 活【い】かして、次【つぎ】の アーキテクチャ 仕様【しよう】書【しょ】も 素晴【すば】らしく 書【か】き上【あ】げてください。",furigana:"最後まで 諦めずに やり抜いた 姿勢は、全社の 誇りです。この 経験を 活かして、次の アーキテクチャ 仕様書も 素晴らしく 書き上げてください。",romaji:"Saigo made akiramezu ni yarinuita shisei wa, zensha no hokori desu. Kono keiken o ikashite, tsugi no aakitekucha shiyousho mo subarashiku kakiagete kudasai.",idText:"Sikap berjuang menuntaskan tugas hingga akhir tanpa menyerah adalah kebanggaan seluruh perusahaan. Manfaatkan pengalaman ini untuk menyusun dokumen spesifikasi arsitektur berikutnya dengan sempurna."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ 今回【こんかい】の 成功【せいこう】体験【たいけん】を 糧【かて】に、さらに 高【たか】い 目標【もくひょう】に 向【む】かって 挑戦【ちょうせん】し抜【ぬ】く 覚悟【かくご】です。",furigana:"はい！ 今回の 成功体験を 糧に、さらに 高い 目標に 向かって 挑戦し抜く 覚悟です。",romaji:"Hai! Konkai no seikou taiken o kate ni, sara ni takai mokuhyou ni mukatte choushenshinuku kakugo desu.",idText:"Baik! Menjadikan pengalaman sukses kali ini sebagai modal berharga, saya bertekad baja untuk terus berjuang menuntaskan tantangan target yang lebih tinggi."}],vocab_breakdown:[{id:"vg-n2-00738",word:"加速",reading:"かそく",romaji:"kasoku",meaning:"percepatan",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 加速 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"その政策は、インフレを加速させるだけだ。",furigana:"その政策は、インフレを加速させるだけだ。",romaji:"kasoku",idText:"Kebijakan tersebut hanya akan mempercepat inflasi."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"カソク￣"}},{id:"vg-n2-00742",word:"片付く",reading:"かたづく",romaji:"katazuku",meaning:"mengaturnya",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 片付く / 〜に関する 片付く dalam wacana profesional.",exampleSentence:{jp:"ごたごたが片付いてさばさばした。",furigana:"ごたごたが片付いてさばさばした。",romaji:"katazuku",idText:"Saya merasa lega ketika semua masalah teratasi."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"カタヅ＼ク"}},{id:"vg-n2-00744",word:"固まる",reading:"かたまる",romaji:"katamaru",meaning:"mengeras",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 固まる / 〜に関する 固まる dalam wacana profesional.",exampleSentence:{jp:"セメントは２、３時間で固まる。",furigana:"セメントは２、３時間で固まる。",romaji:"katamaru",idText:"Semen akan mengeras dalam beberapa jam."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"カタマル￣"}},{id:"vg-n2-00746",word:"傾く",reading:"かたむく",romaji:"katamuku",meaning:"condong ke arah",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 傾く / 〜に関する 傾く dalam wacana profesional.",exampleSentence:{jp:"そのポールは左に傾いた。",furigana:"そのポールは左に傾いた。",romaji:"katamuku",idText:"Tiangnya condong ke kiri."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"カタブ＼ク"}},{id:"vg-n2-00747",word:"片寄る",reading:"かたよる",romaji:"katayoru",meaning:"menjadi sepihak",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 片寄る / 〜に関する 片寄る dalam wacana profesional.",exampleSentence:{jp:"ハンバーガーばかり食べていると、栄養が偏るよ。",furigana:"ハンバーガーばかり食べていると、栄養が偏るよ。",romaji:"katayoru",idText:"Pola makan Anda akan menjadi sangat tidak seimbang jika yang Anda makan hanyalah hamburger."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"カタヨ＼ル"}},{id:"vg-n2-00752",word:"担ぐ",reading:"かつぐ",romaji:"katsugu",meaning:"bahu",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 担ぐ / 〜に関する 担ぐ dalam wacana profesional.",exampleSentence:{jp:"男は袋を肩に担いだ。",furigana:"男は袋を肩に担いだ。",romaji:"katsugu",idText:"Pria itu melemparkan tas ke bahunya."},pitch:{pattern:2,category:"nakadaka",mora_count:3,downstep_mora:2,contour:"カツ＼グ"}},{id:"vg-n2-00753",word:"括弧",reading:"かっこ",romaji:"kakko",meaning:"tanda kurung",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 括弧 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"カッコ内の言葉を短縮形にしなさい。",furigana:"カッコ内の言葉を短縮形にしなさい。",romaji:"kakko",idText:"Masukkan kata-kata dalam tanda kurung ke dalam bentuk yang disingkat."},pitch:{pattern:1,category:"atamadaka",mora_count:3,downstep_mora:1,contour:"カ＼ッコ"}},{id:"vg-n2-00755",word:"活躍",reading:"かつやく",romaji:"katsuyaku",meaning:"aktivitas",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 活躍 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"元気で活躍していることと思います。",furigana:"元気で活躍していることと思います。",romaji:"katsuyaku",idText:"Saya harap semuanya berjalan baik untuk Anda."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"カツヤク￣"}}],explanations:[{id:"exp-1",grammarId:"gn2-00304",title:"Pola: 〜ところ(だ)",formula:"V-dict + ところ(だ) / V-te-iru + ところ(だ) / V-ta + ところ(だ)",meaning:"tepat ketika ..., saat ... (momen spesifik dalam suatu proses)",nuanceNotes:'〜ところ(だ) dipakai untuk menyatakan momen spesifik dari suatu tindakan berdasarkan tahap prosesnya. Tiga bentuk utama: (1) V-dict + ところ = "tepat akan melakukan" (belum mulai); (2) V-te-iru + ところ = "sedang melakukan saat ini"; (3) V-ta + ところ = "baru saja selesai melakukan."',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ところ(だ)",idText:"tepat ketika ..., saat ... (momen spesifik dalam suatu proses)"}],examples:[{jp:"今から出かけるところです。",romaji:"",idText:"Saya tepat mau berangkat sekarang."},{jp:"ちょうど夕食を食べているところなんだ。",romaji:"",idText:"Aku sedang makan malam ini sekarang."}]},{id:"exp-2",grammarId:"gn2-00305",title:"Pola: 〜ところを",formula:"V-te-iru + ところを / V-dict + ところを / V-ta + ところを",meaning:"saat sedang ..., tepat ketika ... (momen yang dilihat atau menimpa seseorang)",nuanceNotes:"〜ところを dipakai untuk menyatakan saat atau momen ketika seseorang sedang melakukan sesuatu dan dilihat, ditangkap, atau dipergoki oleh pihak lain. Partikel を menunjukkan bahwa momen itu menjadi objek dari tindakan orang lain (melihat, menangkap, menghentikan, dsb.). Sering dipakai dalam konteks pengawasan, kejadian kebetulan, atau ekspresi sopan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ところを",idText:"saat sedang ..., tepat ketika ... (momen yang dilihat atau menimpa seseorang)"}],examples:[{jp:"試験中にカンニングしているところを先生に見られた。",romaji:"",idText:"Aku ketahuan guru sedang menyontek di tengah ujian."},{jp:"お忙しいところを、お時間をいただきありがとうございます。",romaji:"",idText:"Terima kasih sudah meluangkan waktu meski Anda sedang sibuk."}]},{id:"exp-3",grammarId:"gn2-00009",title:"Pola: 〜を通じて / 〜を通して",formula:"N + を通じて / を通して",meaning:"melalui ... / sepanjang ...",nuanceNotes:'〜を通じて berarti "melalui suatu media/perantara" atau "sepanjang suatu periode". を通して lebih menekankan proses.',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜を通じて / 〜を通して",idText:"melalui ... / sepanjang ..."}],examples:[{jp:"SNSを通じて、友達と連絡を取る。",romaji:"",idText:"Saya berkomunikasi dengan teman melalui media sosial."},{jp:"一年を通じて、温暖な気候だ。",romaji:"",idText:"Sepanjang tahun, iklimnya hangat."}]},{id:"exp-4",grammarId:"gn2-00021",title:"Pola: 〜ことにする",formula:"V-dict / V-ない + ことにする",meaning:"memutuskan untuk ... / sengaja ...",nuanceNotes:"〜ことにする menyatakan keputusan atau pilihan sadar dari pembicara.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ことにする",idText:"memutuskan untuk ... / sengaja ..."}],examples:[{jp:"毎日運動することにした。",romaji:"",idText:"Saya memutuskan untuk olahraga setiap hari."},{jp:"お酒を飲まないことにしている。",romaji:"",idText:"Saya sengaja tidak minum alkohol."}]},{id:"exp-5",grammarId:"gn2-00066",title:"Pola: 〜ことにしている",formula:"V-dict / V-nai + ことにしている",meaning:"saya membiasakan diri untuk ... / saya selalu ...",nuanceNotes:"〜ことにしている menyatakan kebiasaan atau kebijakan pribadi yang dibuat sendiri oleh pembicara secara sadar dan konsisten dijalankan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ことにしている",idText:"saya membiasakan diri untuk ... / saya selalu ..."}],examples:[{jp:"健康のために、毎朝30分歩くことにしている。",romaji:"",idText:"Demi kesehatan, saya selalu berjalan kaki 30 menit setiap pagi."},{jp:"寝る前にスマホを見ないことにしている。",romaji:"",idText:"Saya membiasakan diri tidak melihat HP sebelum tidur."},{jp:"食事は腹八分目に抑えることにしている。",romaji:"",idText:"Saya selalu membatasi makan sampai sekitar 80% kenyang."}]},{id:"exp-6",grammarId:"gn2-00159",title:"Pola: 〜得る / 〜得ない",formula:"V-stem + 得る (うる/える) / V-stem + 得ない (えない)",meaning:"〜得る: bisa terjadi, ada kemungkinan | 〜得ない: tidak mungkin terjadi, mustahil",nuanceNotes:"〜得る menyatakan kemungkinan bahwa sesuatu bisa terjadi atau bisa dilakukan dalam prinsipnya. Bentuk negatifnya 〜得ない menyatakan kemustahilan yang mendasar. Sering digunakan dalam konteks formal dan akademik.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜得る / 〜得ない",idText:"〜得る: bisa terjadi, ada kemungkinan | 〜得ない: tidak mungkin terjadi, mustahil"}],examples:[{jp:"そのような事態は十分に起こり得る。",romaji:"",idText:"Situasi seperti itu sangat mungkin terjadi."},{jp:"一人の人間があらゆることを知ることはあり得ない。",romaji:"",idText:"Tidak mungkin seorang manusia mengetahui segalanya."}]},{id:"exp-7",grammarId:"gn2-00231",title:"Pola: 〜まい",formula:"V-dict (Gr.1&2) + まい / V-masu-stem (Gr.2, opsional) + まい",meaning:"tidak akan ... / tidak berniat ... (negatif volitional)",nuanceNotes:"〜まい adalah bentuk negatif dari volitional — menyatakan tekad atau niat untuk tidak melakukan sesuatu, atau perkiraan bahwa sesuatu tidak akan terjadi. Merupakan ekspresi formal atau bernuansa sastra.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜まい",idText:"tidak akan ... / tidak berniat ... (negatif volitional)"}],examples:[{jp:"あんな失敗は二度とするまいと心に誓った。",romaji:"",idText:"Aku berjanji dalam hati untuk tidak mengulangi kesalahan seperti itu lagi."},{jp:"彼はもう来るまいと思っていた。",romaji:"",idText:"Dia pikir dia tidak akan datang lagi."}]},{id:"exp-8",grammarId:"gn2-00282",title:"Pola: 〜きれない",formula:"V-masu-stem + きれない",meaning:"tidak bisa menyelesaikan semua ..., terlalu banyak untuk ...",nuanceNotes:"〜きれない adalah bentuk negatif potensial dari 〜きる, menyatakan bahwa seseorang tidak mampu menyelesaikan atau menghabiskan sesuatu secara penuh — karena terlalu banyak, terlalu berat, atau melampaui kemampuan. Bentuk ini sangat umum dan ekspresif dalam percakapan sehari-hari.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜きれない",idText:"tidak bisa menyelesaikan semua ..., terlalu banyak untuk ..."}],examples:[{jp:"こんなにたくさんの料理、とても食べきれない。",romaji:"",idText:"Makanan sebanyak ini sungguh tidak bisa aku habiskan semuanya."},{jp:"彼女への気持ちがまだ忘れきれない。",romaji:"",idText:"Perasaanku padanya masih belum bisa benar-benar kulupakan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah padanan makna istilah "知恵を絞る (ちえをしぼる)" dalam penyelesaian masalah?',sentencePrompt:'Ungkapan idiomatik "知恵を絞る" bermakna:',options:["Memeras segenap daya pikir dan kreativitas untuk mencari solusi","Menyerah tanpa berpikir","Menyalin jawaban dari internet tanpa izin","Menyalahkan orang lain atas kebuntuan"],correctAnswer:"Memeras segenap daya pikir dan kreativitas untuk mencari solusi",explanation:'"知恵を絞る" tersusun dari 知恵 (kebijaksanaan/akal) + 絞る (memeras), menggambarkan upaya berpikir sekuat tenaga.',diagnosticFeedback:{"Menyerah tanpa berpikir":"Salah: Menyerah adalah 諦める (akirameru).","Menyalin jawaban dari internet tanpa izin":"Salah: Menyalin tanpa izin adalah 剽窃 (hyousetsu) atau コピペ.","Menyalahkan orang lain atas kebuntuan":"Salah: Menyalahkan orang lain adalah 他人のせいにする."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat rumpang berikut untuk menyatakan tindakan bertahan melewati penderitaan perang/krisis:",sentencePrompt:"先人【せんじん】たちは 過酷【かこく】な 時代【じだい】を 懸命【けんめい】に 生【い】き_____、平和【へいわ】な 社会【しゃかい】を 築【きず】き上【あ】げた。",options:["抜いた","きった","かけた","だした"],correctAnswer:"抜いた",explanation:"Konteks berjuang bertahan hidup melewati masa-masa yang sangat berat menuntut pola 生き抜いた (bertahan hidup hingga akhir).",diagnosticFeedback:{きった:"Salah: 生ききる lebih menekankan menghabiskan hidup hingga tuntas, bukan menembus penderitaan berat.",かけた:"Salah: 生きかける bermakna nyaris hidup / setengah jalan hidup.",だした:"Salah: 生きだした bermakna mulai hidup."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Pembedaan Makna): Manakah kalimat yang tepat menggunakan pola 〜抜く untuk perjuangan berat menembus rintangan?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["苦【くる】しい 練習【れんしゅう】に 耐【た】え抜【ぬ】いて、ついに 優勝【ゆうしょう】旗【き】を 手【て】に 入【い】れた。","簡単【かんたん】な クイズを 解【と】き抜【ぬ】いた。","耐【た】える 抜【ぬ】いて、優勝した。","耐【た】えて 抜【ぬ】いた。"],correctAnswer:"苦【くる】しい 練習【れんしゅう】に 耐【た】え抜【ぬ】いて、ついに 優勝【ゆうしょう】旗【き】を 手【て】に 入【い】れた。",explanation:"Menahan beratnya latihan keras hingga akhir adalah konteks autentik untuk 耐え抜く (耐え + 抜く).",diagnosticFeedback:{"簡単【かんたん】な クイズを 解【と】き抜【ぬ】いた。":"Kekeliruan Nuansa: Kuis mudah tidak melibatkan penderitaan atau rintangan berat, pantang memakai 抜く.","耐【た】える 抜【ぬ】いて、優勝した。":"Kekeliruan Konjugasi: Menggunakan bentuk kamus (耐える). Wajib menggunakan V-stem (耐え).","耐【た】えて 抜【ぬ】いた。":"Kekeliruan Konjugasi: Menggunakan te-kei (耐えて) sebelum nuku tidak gramatikal."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat pernyataan dedikasi yang utuh:",sentencePrompt:"Susunlah frasa-frasa berikut agar membentuk kalimat yang gramatikal:",options:["どんな 困難が あっても、 初志を 貫き通す 覚悟です。","初志を 貫き通す どんな 困難が あっても、 覚悟です。","覚悟です。 どんな 困難が あっても、 初志を 貫き通す","貫き通す どんな 困難が あっても、 覚悟です。 初志を"],correctAnswer:"どんな 困難が あっても、 初志を 貫き通す 覚悟です。",explanation:"Konsesi pengandaian (どんな困難があっても) + Objek tekad (初志を) + Verba majemuk (貫き通す) + Predikat ketetapan hati (覚悟です).",diagnosticFeedback:{"初志を 貫き通す どんな 困難が あっても、 覚悟です。":"Kekeliruan Urutan: Klausa objek dan predikat memotong klausa pengandaian.","覚悟です。 どんな 困難が あっても、 初志を 貫き通す":"Kekeliruan Predikat: Predikat diletakkan di awal kalimat.","貫き通す どんな 困難が あっても、 覚悟です。 初志を":"Kekeliruan Sintaksis: Objek 初志を terpisah dari verba yang menerangkannya."},tokens:["どんな困難が","あっても、","初志を","貫き通す覚悟です。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Respons Daya Juang): Saat Kenji mengapresiasi: 「最後まで 諦めずに やり抜いた 姿勢は、全社の 誇りです」, apa tanggapan terbaik Anda?",sentencePrompt:"Pilihlah jawaban yang paling rendah hati dan berorientasi pada kemajuan berkelanjutan:",options:["はい！ 今回の 成功体験を 糧に、さらに 高い 目標に 向かって 挑戦し抜く 覚悟です。","私が 優秀だから 成功しただけですよ。他の メンバーは 役に立ちませんでした。","もう 疲れ果てたので、二度と こんな 難しい 仕事は 引き受けません。","成功したんだから、特別ボーナスを 今すぐ 1000万円 振り込んでください。"],correctAnswer:"はい！ 今回の 成功体験を 糧に、さらに 高い 目標に 向かって 挑戦し抜く 覚悟です。",explanation:"Menunjukkan kerendahan hati profesional sekaligus tekad membidik target yang lebih tinggi.",diagnosticFeedback:{"私が 優秀だから 成功しただけですよ。他の メンバーは 役に立ちませんでした。":"Sombong & Toksik: Menjelekkan rekan tim dan mengklaim keberhasilan sepihak menghancurkan kerja sama.","もう 疲れ果てたので、二度と こんな 難しい 仕事は 引き受けません。":"Defaitis: Mengeluh dan menolak berkembang bertentangan dengan prinsip Kaizen.","成功したんだから、特別ボーナスを 今すぐ 1000万円 振り込んでください。":"Tidak Beretika: Menuntut bonus finansial secara agresif dalam forum apresiasi resmi sangat tidak sopan."}}],can_do_challenge:{statement:"Bisa menceritakan perjuangan mengatasi krisis teknis berat, merefleksikan daya tahan tim, dan mengapresiasi karya tuntas.",situation:"Ruang serbaguna kantor Nagoya, pukul 17.00.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ところ(だ)!",modelAnswer:"ありがとうございます！ 予期【よき】せぬ 障害【しょうがい】も 多【おお】く 苦【くる】しい 局面【きょくめん】ばかりでしたが、チーム 全員【ぜんいん】で 議論【ぎろん】を 重【かさ】ね、知恵【ちえ】を 絞【しぼ】り抜【ぬ】いて 乗り越【のりこ】える ことが できました。",modelAnswerId:"Terima kasih banyak! Kendala tak terduga memang banyak dan situasinya serba genting, tetapi seluruh tim berdiskusi intensif, memeras segenap daya pikir hingga tuntas, dan berhasil melaluinya.",culturalEtiquette:"Menyelesaikan tugas sulit hingga tuntas (やり抜く) adalah nilai tertinggi dalam etos kerja Jepang. Hal ini mencerminkan keandalan dan loyalitas profesional.",skillUnlocked:["Menguasai formulasi pola 〜ところ(だ)","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Ketuntasan Tindakan, Batas Kapasitas & Kelelahan Fisik"]},pocket_summary:{keyFormula:"V-stem + 抜く (bertahan menuntaskan hingga akhir melewati kesulitan), V-stem + あげる / あがる (menyelesaikan tuntas hingga menjadi wujud nyata)",coreWords:["克服【こくふく】する (mengatasi; mengalahkan (hambatan, ketakutan, kelemahan))","完遂【かんすい】","試練【しれん】","結晶【けっしょう】 (kristal; kristalisasi)"],coreWarning:"Hindari memakai 〜抜く untuk pekerjaan ringan yang selesai dalam waktu singkat tanpa ada hambatan berarti.",quickDialogue:"A: ブディさん、72時間【じかんにん】連続【れんぞく】... → B: ありがとうございます！ 予期【よき】せぬ 障害【し..."}}},i={"les-n2-u04-01":{pedagogical_framework:{what:{summary:"Menguasai verba majemuk kemahiran operasional: 〜こなす (menguasai dengan terampil/lancar) dan 〜こむ (melakukan secara mendalam/terpatri).",canDo:"Bisa melaporkan penguasaan pengoperasian mesin atau sistem rumit, serta menjelaskan pendalaman analisis data teknis di laboratorium.",targetPatterns:["V-masu + こなす (menguasai dengan terampil / menangani dengan lincah)","V-masu + こむ (melakukan secara mendalam / terpatri kuat)"],coreVocabSample:["区分【くぶん】","組み立【くみた】てる","捜査【そうさ】","設定【せってい】","習得【しゅうとく】","調整【ちょうせい】する","適応【てきおう】","検証【けんしょう】"]},sensei_context:{sceneIntro:"Pusat riset dan laboratorium pengujian robotika industri di Tsukuba Science City. Kenji (Senior Systems Architect) meninjau kemampuan Budi dalam mengonfigurasi parameter lengan robot.",dailyMission:'Gunakan verba "atsukaikonasu" dan "yomikomu" untuk mendemonstrasikan kemahiran teknis tingkat tinggi di hadapan lead engineer.',whyOrder:"Setelah aspek batas fisik (kireru/kirenai) di Unit 3, Unit 4 beralih ke spektrum kemahiran positif: bagaimana mengubah keterampilan dasar menjadi penguasaan profesional yang terampil (konasu)."},cultural_notes:{title:"Etika Penguasaan Alat & Penyerapan Ilmu (習熟 - Shuujuku)",etiquette:"Di lingkungan engineering Jepang, menguasai alat rumit bukan sekadar tahu tombolnya, melainkan mampu mengoperasikannya secara intuitif dan efisien (tsukaikonasu). Catat poin penting saat demonstrasi teknis.",taboos:'Hindari mengklaim "sudah mahir" (tsukaikonaseru) jika belum memverifikasi hasil kalibrasi pada uji beban nyata di bawah supervisi.'},pronunciation_tips:{title:"Intonasi Verba Majemuk (Fukugoudoushi)",moraNote:'Pada verba majemuk seperti "atsukai-konasu", aksen ritmis stabil mengalir tanpa meninggikan vokal akhir su: a-tsu-ka-i-ko-na-su.',soundTip:'Beri penekanan mora tegas pada "ko" saat mengucapkan "yomikomu" untuk mempertegas kedalaman pemahaman.'},common_pitfalls:[{title:"Tertukar Antara 〜こなす (Kemahiran Terampil) vs 〜きる (Ketuntasan Total)",caseScenario:'Ingin mengatakan "saya mampu mengoperasikan software rumit ini dengan lancar", tetapi memakai ~kiru.',pitfallWarning:"この 複雑【ふくざつ】な ソフトを 使【つか】いきれます。 (Artinya habis digunakan, bukan mahir)",rightSolution:"この 複雑【ふくざつ】な ソフトを 使【つか】いこなせます。 (Tepat: mahir mengoperasikan)",explanation:"〜こなす berfokus pada kemahiran, kelancaran, dan keahlian menangani tugas sulit, sedangkan 〜きる berfokus pada menyelesaikan sesuatu sampai habis tuntas."},{title:"Menggabungkan Verba Transitif ke Konteks Non-Aksi",caseScenario:"Memakai ~konasu pada fenomena alamiah yang bukan keterampilan kerja.",pitfallWarning:"雨【あめ】が 降【ふ】りこなしている。 (Salah total)",rightSolution:"仕事【しごと】を 手際【てぎわ】よく こなしている。 (Tepat)",explanation:"〜こなす hanya dapat dilekatkan pada verba yang melibatkan keterampilan, usaha, atau pengolahan aktif manusia."}],who_and_when:{situational_context:"Evaluasi keterampilan teknis, sesi review kode, uji coba instrumen laboratorium, atau pelaporan kesiapan produksi.",social_relations:"Ragam profesional sopan (Teineigo) yang mencerminkan etos pembelajar yang tekun kepada Lead Architect (Kenji).",when_not_to_use:"Jangan memakai konasu untuk meremehkan pekerjaan orang lain seolah-olah pekerjaan itu sepele."},scenario:{title:"Kalibrasi Lengan Robotik Tsukuba",setting:"Lab Pengujian Robotika Industri, Tsukuba Science City, pukul 10.30",narrative:"Kenji mengamati Budi mengonfigurasi parameter gerak motor servo presisi tinggi."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Systems Architect",avatar:"👨‍💻",jp:"ブディさん、新型【しんがた】ロボットアームの 複雑【ふくざつ】な 制御【せいぎょ】プログラムは、もう 扱【あつか】いこなせそうですか？",furigana:"ブディさん、新型ロボットアームの 複雑な 制御プログラムは、もう 扱いこなせそうですか？",romaji:"Budi-san, shingata robotto aamu no fukuzatsuna seigyo puroguramu wa, mou atsukaikonasesou desu ka?",idText:"Budi, apakah kamu sudah bisa menguasai dengan mahir program kendali lengan robot model baru yang rumit ini?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、健二【けんじ】さん！ マニュアルを しっかり 読【よ】み込【こ】んだので、基本【きほん】操作【そうさ】は スムーズに こなせるように なりました。",furigana:"はい、健二さん！ マニュアルを しっかり 読み込んだので、基本操作は スムーズに こなせるように なりました。",romaji:"Hai, Kenji-san! Manyuaru o shikkari yomikonda node, kihon sousa wa sumuuzu ni konaseru you ni narimashita.",idText:"Ya, Kenji-san! Karena saya telah mempelajari manualnya secara mendalam, saya sudah bisa menjalankan pengoperasian dasar dengan lancar."},{id:"d3",speaker:"Kenji",speakerRole:"Senior Systems Architect",avatar:"👨‍💻",jp:"素早【すばや】い 習得【しゅうとく】ですね。ただし、高精度【こうせいど】な 溶接【ようせつ】作業【さぎょう】を やり抜【ぬ】くには、さらなる 微調整【びちょうせい】が 必要【ひつよう】です。",furigana:"素早い 習得ですね。ただし、高精度な 溶接作業を やり抜くには、さらなる 微調整が 必要です。",romaji:"Subayai shuutoku desu ne. Tadashi, kouseidona yousetsu sagyou o yarinuku ni wa, saranaru bichousei ga hitsuyou desu.",idText:"Penguasaan yang cepat ya. Namun, untuk menuntaskan pekerjaan pengelasan presisi tinggi sampai tuntas, masih diperlukan penyesuaian halus lebih lanjut."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ エラーログを 徹底的【てっていてき】に 洗【あら】い出【だ】し、完璧【かんぺき】に 設定【せってい】を 仕上【しあ】げます。",furigana:"承知いたしました！ エラーログを 徹底的に 洗い出し、完璧に 設定を 仕上げます。",romaji:"Shouchi itashimashita! Eraarogu o tetteiteki ni araidashi, kampeki ni settei o shiagemasu.",idText:"Dimengerti! Saya akan menyisir log kesalahan secara menyeluruh dan menyempurnakan pengaturannya secara sempurna."}],vocab_breakdown:[{id:"vg-n2-00877",word:"区分",reading:"くぶん",romaji:"kubun",meaning:"pembagian",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 区分 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"土地は８つに区分された。",furigana:"土地は８つに区分された。",romaji:"kubun",idText:"Tanah itu dibagi menjadi 8 bidang."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"クブン￣"}},{id:"vg-n2-00879",word:"組み立てる",reading:"くみたてる",romaji:"kumitateru",meaning:"berkumpul",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 組み立てる / 〜に関する 組み立てる dalam wacana profesional.",exampleSentence:{jp:"昨日、アンプを組み立てた。",furigana:"昨日、アンプを組み立てた。",romaji:"kumitateru",idText:"Saya membuat amplifier kemarin."},pitch:{pattern:4,category:"nakadaka",mora_count:5,downstep_mora:4,contour:"クミタテ＼ル"}},{id:"vg-n2-00880",word:"汲む",reading:"くむ",romaji:"kumu",meaning:"menggambar",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 汲む / 〜に関する 汲む dalam wacana profesional.",exampleSentence:{jp:"バケツに水を汲んでくるよ。",furigana:"バケツに水を汲んでくるよ。",romaji:"kumu",idText:"Aku akan mengambil seember air."},pitch:{pattern:0,category:"heiban",mora_count:2,downstep_mora:0,contour:"クム￣"}},{id:"vg-n2-00881",word:"酌む",reading:"くむ",romaji:"kumu",meaning:"menuangkan sake",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 酌む / 〜に関する 酌む dalam wacana profesional.",exampleSentence:{jp:"酌むを使います。",furigana:"酌むを使います。",romaji:"kumu",idText:"Menggunakan menuangkan sake."},pitch:{pattern:0,category:"heiban",mora_count:2,downstep_mora:0,contour:"クム￣"}},{id:"vg-n2-00883",word:"悔やむ",reading:"くやむ",romaji:"kuyamu",meaning:"berduka",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 悔やむ / 〜に関する 悔やむ dalam wacana profesional.",exampleSentence:{jp:"よーし！覚えてろ。後で悔やむなよ。",furigana:"よーし！覚えてろ。後で悔やむなよ。",romaji:"kuyamu",idText:"Baiklah! Anda akan menyesali hal ini."},pitch:{pattern:2,category:"nakadaka",mora_count:3,downstep_mora:2,contour:"クヤ＼ム"}},{id:"vg-n2-00884",word:"クリーニング",reading:"クリーニング",romaji:"kuriiningu",meaning:"cleaning; dry cleaning",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を クリーニング (objek tindakan kerja/bisnis).",exampleSentence:{jp:"クリーニング取ってきておいて。",furigana:"クリーニング取ってきておいて。",romaji:"kuriiningu",idText:"Tolong pick up my dry cleaning."},pitch:{pattern:4,category:"nakadaka",mora_count:0,downstep_mora:0,contour:"￣"}},{id:"vg-n2-00885",word:"くるむ",reading:"くるむ",romaji:"kurumu",meaning:"terbungkus",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の くるむ / 〜に関する くるむ dalam wacana profesional.",exampleSentence:{jp:"くるむを使います。",furigana:"くるむを使います。",romaji:"kurumu",idText:"Menggunakan terbungkus."},pitch:{pattern:2,category:"nakadaka",mora_count:3,downstep_mora:2,contour:"クル＼ム"}},{id:"vg-n2-00887",word:"咥える",reading:"くわえる",romaji:"kuwaeru",meaning:"tahan di mulut seseorang",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 咥える / 〜に関する 咥える dalam wacana profesional.",exampleSentence:{jp:"彼はパイプをくわえて話した。",furigana:"彼はパイプをくわえて話した。",romaji:"kuwaeru",idText:"Dia berbicara dengan pipa di mulutnya."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"クワエル￣"}}],explanations:[{id:"exp-1",grammarId:"gn2-00283",title:"Pola: 〜きれる",formula:"V-masu-stem + きれる",meaning:"bisa menyelesaikan ..., mampu sampai tuntas",nuanceNotes:"〜きれる adalah bentuk potensial dari 〜きる, menyatakan bahwa seseorang mampu menyelesaikan atau menghabiskan sesuatu secara penuh dan tuntas. Sering dipakai dalam konteks pertanyaan atau pernyataan tentang kemampuan menyelesaikan sesuatu yang tampaknya banyak atau sulit.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜きれる",idText:"bisa menyelesaikan ..., mampu sampai tuntas"}],examples:[{jp:"このケーキ、全部食べきれるかな？量が多いけど。",romaji:"",idText:"Kue ini bisa dihabiskan semuanya tidak ya? Porsinya banyak soalnya."},{jp:"一日でこの仕事を片付けきれると思う。",romaji:"",idText:"Aku rasa bisa membereskan semua pekerjaan ini dalam satu hari."}]},{id:"exp-2",grammarId:"gn2-00289",title:"Pola: 〜こなす",formula:"V-masu-stem + こなす",meaning:"berhasil menangani, menguasai (dengan terampil)",nuanceNotes:"〜こなす menyatakan bahwa seseorang berhasil menangani atau menguasai sesuatu yang sulit atau kompleks dengan terampil. Tidak hanya selesai, tapi selesai dengan baik dan kompeten. Dipakai untuk menggambarkan keterampilan dalam menggunakan alat, bahasa, atau menyelesaikan tugas-tugas yang menantang.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜こなす",idText:"berhasil menangani, menguasai (dengan terampil)"}],examples:[{jp:"新しいソフトをやっと使いこなせるようになった。",romaji:"",idText:"Akhirnya aku bisa menggunakan software baru itu dengan mahir."},{jp:"彼はどんな仕事でも上手にこなす。",romaji:"",idText:"Dia bisa menangani pekerjaan apapun dengan terampil."}]},{id:"exp-3",grammarId:"gn2-00290",title:"Pola: 〜こむ",formula:"V-masu-stem + こむ",meaning:"masuk ke dalam, melakukan secara intensif/mendalam",nuanceNotes:"〜こむ sebagai sufiks verba majemuk mengandung dua makna utama: (1) masuk ke dalam suatu ruang atau kondisi secara fisik (押し込む, 飛び込む); dan (2) melakukan sesuatu secara intensif, mendalam, atau hingga terbenam — termasuk keyakinan atau pemikiran yang tertanam kuat (思い込む, 信じ込む). Sufiks ini sangat produktif dalam bahasa Jepang.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜こむ",idText:"masuk ke dalam, melakukan secara intensif/mendalam"}],examples:[{jp:"彼は自分が絶対に正しいと思いこんでいる。",romaji:"",idText:"Dia sudah telanjur yakin sekali bahwa dirinya pasti benar."},{jp:"ノートにポイントをしっかり書きこんでおいた。",romaji:"",idText:"Aku sudah menuliskan poin-poin penting secara lengkap di buku catatan."}]},{id:"exp-4",grammarId:"gn2-00295",title:"Pola: 〜かえる",formula:"V-masu-stem + かえる",meaning:"melakukan balik/kembali, mengubah dengan cara yang berbeda",nuanceNotes:"〜かえる sebagai sufiks verba majemuk menyatakan bahwa suatu tindakan dilakukan kembali dengan cara yang berbeda atau berlawanan, atau mengubah sesuatu melalui tindakan yang diulang. Contoh: 言いかえる (mengatakan ulang dengan kata lain/mengoreksi ucapan), 考えかえす (memikirkan kembali).",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜かえる",idText:"melakukan balik/kembali, mengubah dengan cara yang berbeda"}],examples:[{jp:"難しい専門用語を分かりやすく言いかえた。",romaji:"",idText:"Istilah teknis yang sulit diubah menjadi ungkapan yang lebih mudah dipahami."},{jp:"一度決めたことを急に言いかえるのは信頼を損なう。",romaji:"",idText:"Tiba-tiba mengubah apa yang sudah diputuskan dapat merusak kepercayaan."}]},{id:"exp-5",grammarId:"gn2-00296",title:"Pola: 〜なおす",formula:"V-masu-stem + なおす",meaning:"melakukan ulang, memperbaiki dengan melakukan lagi",nuanceNotes:'〜なおす menyatakan bahwa suatu tindakan dilakukan ulang untuk memperbaiki kesalahan atau hasil yang tidak memuaskan sebelumnya. Nuansanya adalah "melakukan lagi karena yang pertama salah atau kurang baik." Sangat produktif dan umum dipakai dalam situasi pekerjaan, tulisan, dan koreksi.',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜なおす",idText:"melakukan ulang, memperbaiki dengan melakukan lagi"}],examples:[{jp:"間違えた箇所を全部書きなおした。",romaji:"",idText:"Aku menulis ulang semua bagian yang salah."},{jp:"このコードにバグがあるので書きなおす必要がある。",romaji:"",idText:"Kode ini ada bug-nya, jadi perlu ditulis ulang."}]},{id:"exp-6",grammarId:"gn2-00300",title:"Pola: 〜もどる / 〜にもどる",formula:"V-masu-stem + もどる / N + にもどる",meaning:"kembali ke keadaan semula, kembali lagi ke ...",nuanceNotes:"〜もどる sebagai sufiks verba majemuk atau pola gramatikal menyatakan kembali ke kondisi, tempat, atau keadaan sebelumnya. Dipakai baik sebagai sufiks (引きもどる = kembali mundur) maupun sebagai pola 〜にもどる (kembali ke N — kondisi/topik/tempat).",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜もどる / 〜にもどる",idText:"kembali ke keadaan semula, kembali lagi ke ..."}],examples:[{jp:"本題にもどりましょう。",romaji:"",idText:"Mari kembali ke topik utama."},{jp:"元の状態にもどるのに1週間かかった。",romaji:"",idText:"Butuh waktu satu minggu untuk kembali ke kondisi semula."}]},{id:"exp-7",grammarId:"gn2-00301",title:"Pola: 〜かわる / 代わる代わる",formula:"V-masu-stem + かわる / 代わる代わる (idiom adverbia)",meaning:"bergantian melakukan, berubah (sebagai verba majemuk)",nuanceNotes:'〜かわる sebagai sufiks verba majemuk menyatakan adanya perubahan atau pergantian dalam konteks tindakan yang dilakukan. Contoh: 入れかわる (silih berganti/bertukar posisi), 移りかわる (berubah seiring waktu). Bentuk idiomatis 代わる代わる (かわるがわる) berarti "bergantian satu per satu" dan dipakai sebagai adverbia.',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜かわる / 代わる代わる",idText:"bergantian melakukan, berubah (sebagai verba majemuk)"}],examples:[{jp:"リーダーが次々と入れかわって、組織が混乱した。",romaji:"",idText:"Pemimpin silih berganti, sehingga organisasi menjadi kacau."},{jp:"子供たちが代わる代わる（かわるがわる）ゲームをした。",romaji:"",idText:"Para anak-anak bermain game secara bergantian."}]},{id:"exp-8",grammarId:"gn2-00302",title:"Pola: 〜あう",formula:"V-masu-stem + あう",meaning:"saling melakukan, melakukan bersama-sama (resiprok)",nuanceNotes:"〜あう menyatakan bahwa suatu tindakan dilakukan secara timbal balik antara dua pihak atau lebih — artinya, kedua pihak melakukan tindakan yang sama terhadap satu sama lain. Ini adalah sufiks resiprok dalam bahasa Jepang. Contoh: 助けあう (saling membantu), 愛しあう (saling mencintai), 話しあう (saling berbicara/berdiskusi).",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜あう",idText:"saling melakukan, melakukan bersama-sama (resiprok)"}],examples:[{jp:"困ったときは助けあうのが大切だ。",romaji:"",idText:"Di saat susah, saling membantu itu hal yang penting."},{jp:"二人は長時間話しあった結果、和解できた。",romaji:"",idText:"Setelah berbicara panjang lebar satu sama lain, keduanya berhasil berdamai."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "区分 (くぶん)" dalam manajemen suku cadang industri?',sentencePrompt:'Istilah "区分 (くぶん)" dalam logistik industri bermakna:',options:["Pengelompokan atau pembagian kategori secara teratur","Pembersihan tangki cairan pendingin","Pembatalan kontrak pemasok bahan baku","Pemasangan kabel daya tegangan tinggi"],correctAnswer:"Pengelompokan atau pembagian kategori secara teratur",explanation:'"区分 (くぶん)" bermakna pembagian, klasifikasi, atau pemilahan kategori sistematis.',diagnosticFeedback:{"Pembersihan tangki cairan pendingin":"Salah: Pembersihan adalah 洗浄 (senjou) atau 清掃 (seisou).","Pembatalan kontrak pemasok bahan baku":"Salah: Pembatalan kontrak adalah 契約解除 (keiyaku kaijo).","Pemasangan kabel daya tegangan tinggi":"Salah: Pemasangan kabel adalah 配線 (haisen)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola yang menyatakan kemahiran pengoperasian:",sentencePrompt:"新人【しんじん】ながら、彼【かれ】は 最新【さいしん】の 測定器【そくていき】を 実【じつ】に 見事【みごと】に [　　] いる。",options:["扱【あつか】いこなして","扱【あつか】いきれて","扱【あつか】いあわせて","扱【あつか】いなおして"],correctAnswer:"扱【あつか】いこなして",explanation:"Pola 〜こなす menyatakan kemampuan mengoperasikan sesuatu yang rumit secara mahir dan luwes.",diagnosticFeedback:{"扱【あつか】いきれて":"Kekeliruan Nuansa: 〜きる menyatakan menghabiskan atau menyudahi, bukan kemahiran terampil.","扱【あつか】いあわせて":"Kekeliruan Pola: 〜あう menyatakan saling melakukan secara timbal balik.","扱【あつか】いなおして":"Kekeliruan Pola: 〜なおす menyatakan mengulang kembali dari awal karena ada kekurangan."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Nuansa Gramatikal): Manakah kalimat yang menggunakan pola 〜こなす secara tepat?",sentencePrompt:"Pilihlah kalimat dengan pemakaian 〜こなす yang paling gramatikal dan alami:",options:["彼【かれ】は 膨大【ぼうだい】な 事務【じむ】処理【しょり】を 迅速【じんそく】に こなした。","雨【あめ】が 朝【あさ】から 激【はげ】しく 降【ふ】りこなしている。","疲【つか】れすぎて、もう 一歩【いっぽ】も 歩【ある】きこなせない。","会議【かいぎ】室【しつ】の 電灯【でんとう】を 全部【ぜんぶ】 消【け】しこなした。"],correctAnswer:"彼【かれ】は 膨大【ぼうだい】な 事務【じむ】処理【しょり】を 迅速【じんそく】に こなした。",explanation:"〜こなす digunakan untuk menyelesaikan tugas yang membutuhkan keterampilan atau efisiensi (memproses tugas).",diagnosticFeedback:{"雨【あめ】が 朝【あさ】から 激【はげ】しく 降【ふ】りこなしている。":"Kekeliruan Subjek: Fenomena alam tidak dapat dipadukan dengan 〜こなす yang membutuhkan kehendak/keterampilan.","疲【つか】れすぎて、もう 一歩【いっぽ】も 歩【ある】きこなせない。":"Kekeliruan Pola: Untuk batas fisik ketidakmampuan melangkah, gunakan 歩けない atau 歩ききれない.","会議【かいぎ】室【しつ】の 電灯【でんとう】を 全部【ぜんぶ】 消【け】しこなした。":"Kekeliruan Kolokasi: Mematikan lampu adalah tindakan mekanis sederhana, tepatnya 消し終えた atau 消しきった."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun frasa-frasa berikut menjadi kalimat padu yang gramatikal:",sentencePrompt:"Susunlah frasa-frasa berikut:",options:["マニュアルを 読【よ】み込【こ】んで 設定【せってい】を こなす","設定【せってい】を こなす マニュアルを 読【よ】み込【こ】んで","読【よ】み込【こ】んで マニュアルを 設定【せってい】を こなす","マニュアルを こなす 設定【せってい】を 読【よ】み込【こ】んで"],correctAnswer:"マニュアルを 読【よ】み込【こ】んで 設定【せってい】を こなす",explanation:"Urutan alami: Pelajari manual secara mendalam (マニュアルを読み込んで), lalu selesaikan pengaturan dengan mahir (設定をこなす).",diagnosticFeedback:{"設定【せってい】を こなす マニュアルを 読【よ】み込【こ】んで":"Kekeliruan Urutan: Klausa prasyarat penjelas terbalik dari klausa tindakan akhir.","読【よ】み込【こ】んで マニュアルを 設定【せってい】を こなす":"Kekeliruan Partikel: Partikel objek を mendahului kata kerjanya, bukan sebaliknya.","マニュアルを こなす 設定【せってい】を 読【よ】み込【こ】んで":"Kekeliruan Kolokasi: Objek manual dipadukan dengan membaca (yomikomu), bukan konasu."},tokens:["マニュアルを","読【よ】み込【こ】んで","設定【せってい】を","こなす"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Respons Kerja Profesional): Saat Kenji mengingatkan: 「高精度な 溶接作業を やり抜くには、さらなる 微調整が 必要です」, apa respons terbaik Anda?",sentencePrompt:"Pilihlah tanggapan profesional yang menunjukkan ketelitian teknis dan kesiapan bekerja tuntas:",options:["承知【しょうち】いたしました！ エラーログを 徹底的【てっていてき】に 洗【あら】い出【だ】し、完璧【かんぺき】に 設定【せってい】を 仕上【しあ】げます。","もう 基準【きじゅん】内【ない】なので、これ 以上【いじょう】の 微調整【びちょうせい】は 面倒【めんどう】ですから 省略【しょうりゃく】します。","健二【けんじ】さん、ロボットの ことは 忘【わす】れて、一緒【いっしょ】に ゲームでも しませんか？","微調整【びちょうせい】なんて 私【わたし】の 仕事【しごと】じゃないので、メーカーの 人【ひと】を 呼【よ】んでください。"],correctAnswer:"承知【しょうち】いたしました！ エラーログを 徹底的【てっていてき】に 洗【あら】い出【だ】し、完璧【かんぺき】に 設定【せってい】を 仕上【しあ】げます。",explanation:"Menunjukkan komitmen terhadap standar mutu tinggi (Kaizen) dan kesiapan bekerja tuntas.",diagnosticFeedback:{"もう 基準【きじゅん】内【ない】なので、これ 以上【いじょう】の 微調整【びちょうせい】は 面倒【めんどう】ですから 省略【しょうりゃく】します。":"Ceroboh & Malas: Mengabaikan arahan presisi lead engineer membahayakan mutu produk.","健二【けんじ】さん、ロボットの ことは 忘【わす】れて、一緒【いっしょ】に ゲームでも しませんか？":"Tidak Profesional: Mengajak bermain di tengah proses pengujian teknis melanggar etika kerja.","微調整【びちょうせい】なんて 私【わたし】の 仕事【しごと】じゃないので、メーカーの 人【ひと】を 呼【よ】んでください。":"Lepas Tanggung Jawab: Menolak tugas inti kalibrasi merusak kepercayaan tim engineering."}}],can_do_challenge:{statement:"Bisa melaporkan penguasaan pengoperasian mesin atau sistem rumit, serta menjelaskan pendalaman analisis data teknis di laboratorium.",situation:"Lab Pengujian Robotika Industri, Tsukuba Science City, pukul 10.30",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜きれる!",modelAnswer:"はい、健二【けんじ】さん！ マニュアルを しっかり 読【よ】み込【こ】んだので、基本【きほん】操作【そうさ】は スムーズに こなせるように なりました。",modelAnswerId:"Ya, Kenji-san! Karena saya telah mempelajari manualnya secara mendalam, saya sudah bisa menjalankan pengoperasian dasar dengan lancar.",culturalEtiquette:"Di lingkungan engineering Jepang, menguasai alat rumit bukan sekadar tahu tombolnya, melainkan mampu mengoperasikannya secara intuitif dan efisien (tsukaikonasu). Catat poin penting saat demonstrasi teknis.",skillUnlocked:["Menguasai formulasi pola 〜きれる","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Kemahiran Teknis, Penyerapan Ilmu & Adaptasi Beban"]},pocket_summary:{keyFormula:"V-masu + こなす (menguasai dengan terampil / menangani dengan lincah), V-masu + こむ (melakukan secara mendalam / terpatri kuat)",coreWords:["区分【くぶん】 (pembagian)","組み立【くみた】てる (berkumpul)","捜査【そうさ】 (penggeledahan (khususnya dalam investigasi kriminal); investigasi)","設定【せってい】 (pendirian; penciptaan)"],coreWarning:'Hindari mengklaim "sudah mahir" (tsukaikonaseru) jika belum memverifikasi hasil kalibrasi pada uji beban nyata di bawah supervisi.',quickDialogue:"A: ブディさん、新型【しんがた】ロボットアームの 複雑... → B: はい、健二【けんじ】さん！ マニュアルを しっかり..."}},"les-n2-u04-02":{pedagogical_framework:{what:{summary:"Menguasai pola penentuan prasyarat prosedural: 〜上で (setelah menuntaskan prasyarat A, barulah melakukan B) dan tindak lanjut instan: 〜次第 (segera setelah X selesai).",canDo:"Bisa mengoordinasikan eksekusi prosedur bertahap dan melaporkan komitmen tindak lanjut seketika dalam alur kerja rekayasa.",targetPatterns:["V-ta / Nの + 上で (setelah ... / berlandaskan hasil ...)","V-masu + 次第 (segera setelah ... langsung ...)"],coreVocabSample:["検討【けんとう】","実施【じっし】","確認【かくにん】する","報告【ほうこく】","連携【れんけい】","提出【ていしゅつ】","診断【しんだん】","手順【てじゅん】"]},sensei_context:{sceneIntro:"Ruang integrasi sistem robotika Tsukuba. Kenji menginstruksikan prosedur uji komunikasi antarmuka PLC sebelum penghubungan jalur transfer otomatis.",dailyMission:'Gunakan frasa "kakunin no ue de" dan "shutoku shidai" untuk menegaskan kepatuhan SOP bertahap.',whyOrder:"Pola ~ue de adalah tulang punggung kepatuhan prosedur industri Jepang: tiada tindakan kritis tanpa verifikasi prasyarat tertulis terlebih dahulu."},cultural_notes:{title:"Verifikasi Bertahap (確認の上で - Kakunin no Ue de) dalam SOP",etiquette:'Menyatakan "kakunin no ue de susumemasu" memberikan rasa aman maksimal bagi atasan bahwa langkah kerja tidak diambil secara gegabah.',taboos:"Jangan memakai 〜次第 untuk hal-hal di masa lampau. Pola ini khusus merujuk komitmen tindakan masa depan begitu kondisi terpenuhi."},pronunciation_tips:{title:'Artikulasi "Ue de" dan "Shidai"',moraNote:'Frasa "ue de" dilafalkan dengan dua vokal bersih u-e tanpa menyatukannya menjadi diftong kotor.',soundTip:'Pada "shidai", beri intonasi turun lembut di akhir mora i.'},common_pitfalls:[{title:"Salah Bentuk Verba Sebelum 〜上で",caseScenario:"Memasukkan bentuk kamus untuk tindakan yang mensyaratkan selesainya tahap awal.",pitfallWarning:"確認【かくにん】する 上【うえ】で、連絡【れんらく】します。 (Rancu)",rightSolution:"確認【かくにん】した 上【うえ】で、連絡【れんらく】します。 (Tepat)",explanation:'Bila bermakna "setelah melakukan X baru melakukan Y", verba sebelum 上で wajib berbentuk lampau (Ta-kei) atau Nomina + の.'},{title:"Memakai Kata Kerja Masa Lampau Sebelum 〜次第",caseScenario:'Mengatakan "sudah selesai shidai".',pitfallWarning:"準備【じゅんび】が 終【お】わった 次第【しだい】、行【い】きました。 (Salah)",rightSolution:"準備【じゅんび】が 終【お】わり 次第【しだい】、伺【うかが】います。 (Tepat: masa depan)",explanation:"〜次第 (segera setelah) selalu dilekatkan pada Verba Masu-stem dan predikat penutupnya wajib berupa niat/instruksi masa depan."}],who_and_when:{situational_context:"Penyampaian rencana implementasi sistem, briefing alur kerja kepada vendor, dan konfirmasi jadwal rilis.",social_relations:"Komunikasi eksekutif formal antara lead engineer dan staf rekayasa.",when_not_to_use:'Jangan gunakan pada rutinitas refleks alamiah sehari-hari seperti "setelah bangun tidur langsung membuka mata".'},scenario:{title:"Otorisasi Uji Integrasi Jalur Otomatis",setting:"Terminal Kontrol Pusat Lab Tsukuba, pukul 14.15",narrative:"Kenji mengecek kepatuhan verifikasi sensor Budi sebelum menghubungkan sinyal ke konveyor utama."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Systems Architect",avatar:"👨‍💻",jp:"ブディさん、自動【じどう】搬送【はんそう】システムへの 本格【ほんかく】接続【せつぞく】は、安全【あんぜん】確認【かくにん】の 上【うえ】で 進【すす】めていますか？",furigana:"ブディさん、自動搬送システムへの 本格接続は、安全確認の 上で 進めていますか？",romaji:"Budi-san, jidou hansou shisutemu e no honkaku setsuzoku wa, anzen kakunin no ue de susumete imasu ka?",idText:"Budi, apakah penyambungan utama ke sistem konveyor otomatis ini kamu jalankan setelah verifikasi keselamatan?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ 各【かく】センサーの 通信【つうしん】テストを 実施【じっし】した 上【うえ】で、異常【いじょう】がないことを 確認【かくにん】いたしました。",furigana:"はい！ 各センサーの 通信テストを 実施した 上で、異常がないことを 確認いたしました。",romaji:"Hai! Kaku sensaa no tsuushin tesuto o jisshi shita ue de, ijou ga nai koto o kakunin itashimashita.",idText:"Ya! Setelah melaksanakan uji komunikasi pada masing-masing sensor, saya telah memastikan bahwa tidak ada anomali."},{id:"d3",speaker:"Kenji",speakerRole:"Senior Systems Architect",avatar:"👨‍💻",jp:"了解【りょうかい】です。では、最終【さいしゅう】テストの ログが 出【で】次第【しだい】、すぐに 開発【かいはつ】チームへ 共有【きょうゆう】してください。",furigana:"了解です。では、最終テストの ログが 出次第、すぐに 開発チームへ 共有してください。",romaji:"Ryoukai desu. Dewa, saishuu tesuto no rogu ga deshidai, sugu ni kaihatsu chiimu e kyouyuu shite kudasai.",idText:"Paham. Kalau begitu, segera setelah log pengujian akhir keluar, tolong langsung bagikan ke tim pengembang."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"かしこまりました！ ログを 取得【しゅとく】し次第【しだい】、速【すみ】やかに 分析【ぶんせき】レポートを 提出【ていしゅつ】いたします。",furigana:"かしこまりました！ ログを 取得し次第、速やかに 分析レポートを 提出いたします。",romaji:"Kashikomarimashita! Rogu o shutoku shishidai, sumiyaka ni bunseki repooto o teishutsu itashimasu.",idText:"Dimengerti! Segera setelah berhasil memperoleh log-nya, saya akan langsung menyerahkan laporan analisisnya."}],vocab_breakdown:[{id:"vg-n2-01042",word:"裂く",reading:"さく",romaji:"saku",meaning:"sobek",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 裂く / 〜に関する 裂く dalam wacana profesional.",exampleSentence:{jp:"その少女はその布を裂いた。",furigana:"その少女はその布を裂いた。",romaji:"saku",idText:"Gadis itu merobek kainnya."},pitch:{pattern:1,category:"atamadaka",mora_count:2,downstep_mora:1,contour:"サ＼ク"}},{id:"vg-n2-01045",word:"削除",reading:"さくじょ",romaji:"sakujo",meaning:"elimination; cancellation",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 削除 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"このファイルは削除して下さい。",furigana:"このファイルは削除して下さい。",romaji:"sakujo",idText:"Tolong hapus file ini."},pitch:{pattern:1,category:"atamadaka",mora_count:3,downstep_mora:1,contour:"サ＼クジョ"}},{id:"vg-n2-01046",word:"作成",reading:"さくせい",romaji:"sakusei",meaning:"frame; draw up",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 作成 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"その老人は遺言を作成した。",furigana:"その老人は遺言を作成した。",romaji:"sakusei",idText:"Orang tua itu menyatakan keinginannya."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"サクセイ￣"}},{id:"vg-n2-01047",word:"作製",reading:"さくせい",romaji:"sakusei",meaning:"manufaktur",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 作製 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"合鍵の作製には2日ほどかかります。",furigana:"合鍵の作製には2日ほどかかります。",romaji:"sakusei",idText:"Diperlukan waktu sekitar dua hari untuk membuat kunci duplikat."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"サクセイ￣"}},{id:"vg-n2-01048",word:"探る",reading:"さぐる",romaji:"saguru",meaning:"pencarian",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 探る / 〜に関する 探る dalam wacana profesional.",exampleSentence:{jp:"遠まわしに彼の意見を探った。",furigana:"遠まわしに彼の意見を探った。",romaji:"saguru",idText:"I sounded him out about his views."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"サグル￣"}},{id:"vg-n2-01049",word:"囁く",reading:"ささやく",romaji:"sasayaku",meaning:"berbisik",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 囁く / 〜に関する 囁く dalam wacana profesional.",exampleSentence:{jp:"一人の教授がささやいた。",furigana:"一人の教授がささやいた。",romaji:"sasayaku",idText:"One of his colleagues whispered."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"ササヤ＼ク"}},{id:"vg-n2-01050",word:"刺さる",reading:"ささる",romaji:"sasaru",meaning:"menempel",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 刺さる / 〜に関する 刺さる dalam wacana profesional.",exampleSentence:{jp:"釘が車のタイヤに刺さった。",furigana:"釘が車のタイヤに刺さった。",romaji:"sasaru",idText:"Sebuah paku menusuk ban."},pitch:{pattern:2,category:"nakadaka",mora_count:3,downstep_mora:2,contour:"ササ＼ル"}},{id:"vg-n2-01054",word:"差し引き",reading:"さしひき",romaji:"sashihiki",meaning:"deduction; subtraction",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 差し引き (objek tindakan kerja/bisnis).",exampleSentence:{jp:"差し引きを使います。",furigana:"差し引きを使います。",romaji:"sashihiki",idText:"Menggunakan deduction; subtraction."},pitch:{pattern:2,category:"nakadaka",mora_count:4,downstep_mora:2,contour:"サシ＼ヒキ"}}],explanations:[{id:"exp-1",grammarId:"gn2-00006",title:"Pola: 〜上で",formula:"V-た / N + の + 上で",meaning:"setelah ... / dalam hal ... / dari segi ...",nuanceNotes:"〜上で memiliki dua makna: (1) setelah melakukan sesuatu sebagai syarat; (2) dari segi / dalam konteks.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜上で",idText:"setelah ... / dalam hal ... / dari segi ..."}],examples:[{jp:"よく考えた上で、決めてください。",romaji:"",idText:"Setelah berpikir baik-baik, silakan putuskan."},{jp:"仕事の上での悩みを話した。",romaji:"",idText:"Saya berbicara tentang masalah dalam pekerjaan."}]},{id:"exp-2",grammarId:"gn2-00019",title:"Pola: 〜次第",formula:"V-stem / N + 次第",meaning:"(1) segera setelah ... (2) tergantung pada ...",nuanceNotes:"〜次第 bermakna ganda: (1) segera setelah tindakan selesai; (2) bergantung pada kondisi yang disebutkan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜次第",idText:"(1) segera setelah ... (2) tergantung pada ..."}],examples:[{jp:"準備ができ次第、出発します。",romaji:"",idText:"Segera setelah persiapan selesai, kami akan berangkat."},{jp:"結果次第で、方針が変わります。",romaji:"",idText:"Kebijakan akan berubah tergantung pada hasilnya."}]},{id:"exp-3",grammarId:"gn2-00047",title:"Pola: 〜さえ〜ば",formula:"N + さえ + V-ba / Adj-kereba / N + でさえあれば",meaning:"asalkan ... / kalau saja ... (satu syarat cukup)",nuanceNotes:"〜さえ〜ば menyatakan bahwa jika satu syarat kunci terpenuhi, maka segalanya akan baik-baik saja. Satu kondisi itu sudah cukup untuk menghasilkan hasil yang diharapkan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜さえ〜ば",idText:"asalkan ... / kalau saja ... (satu syarat cukup)"}],examples:[{jp:"お金さえあれば、何でもできる。",romaji:"",idText:"Asalkan ada uang, apa pun bisa dilakukan."},{jp:"健康でさえあれば、それで十分だ。",romaji:"",idText:"Asalkan sehat, itu sudah cukup."},{jp:"彼が来てさえくれれば、問題ない。",romaji:"",idText:"Asalkan dia mau datang, tidak ada masalah."}]},{id:"exp-4",grammarId:"gn2-00054",title:"Pola: 〜次第で",formula:"N + 次第で / 次第では",meaning:"tergantung pada ... (hasilnya bisa berbeda)",nuanceNotes:"〜次第で menyatakan bahwa hasil atau kondisi akhir sepenuhnya ditentukan oleh faktor yang disebutkan. Faktor itu menjadi penentu utama.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜次第で",idText:"tergantung pada ... (hasilnya bisa berbeda)"}],examples:[{jp:"努力次第で、結果は変わる。",romaji:"",idText:"Tergantung pada usaha, hasilnya bisa berubah."},{jp:"天気次第で、ピクニックを中止するかもしれない。",romaji:"",idText:"Tergantung cuaca, piknik mungkin akan dibatalkan."},{jp:"返事次第では、計画を変更する必要がある。",romaji:"",idText:"Tergantung jawabannya, mungkin perlu mengubah rencana."}]},{id:"exp-5",grammarId:"gn2-00089",title:"Pola: 〜とあれば",formula:"V-plain / N + とあれば",meaning:"kalau memang ... — rela melakukan apapun / demi ...",nuanceNotes:"〜とあれば menyatakan bahwa jika suatu kondisi tertentu terpenuhi, pembicara rela atau bersedia melakukan apa saja. Biasanya mengungkapkan kesediaan atau pengorbanan yang kuat.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜とあれば",idText:"kalau memang ... — rela melakukan apapun / demi ..."}],examples:[{jp:"君のためとあれば、何でもするよ。",romaji:"",idText:"Kalau memang demi kamu, aku akan lakukan apa saja."},{jp:"会社の存続とあれば、給料カットも仕方がない。",romaji:"",idText:"Kalau memang demi kelangsungan perusahaan, pemotongan gaji pun tidak apa-apa."},{jp:"子供のためとあれば、親は何でも惜しまない。",romaji:"",idText:"Kalau demi anak, orang tua tidak akan segan melakukan apapun."}]},{id:"exp-6",grammarId:"gn2-00090",title:"Pola: 〜とあっては",formula:"V-plain / N + とあっては",meaning:"dalam kondisi seperti ini ... / mengingat keadaan yang ...",nuanceNotes:"〜とあっては menyatakan bahwa mengingat kondisi atau situasi tertentu yang sudah ada, suatu konsekuensi logis tidak bisa dihindari.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜とあっては",idText:"dalam kondisi seperti ini ... / mengingat keadaan yang ..."}],examples:[{jp:"社長自らの命令とあっては、従わないわけにはいかない。",romaji:"",idText:"Mengingat ini perintah langsung dari presiden direktur, tidak ada pilihan selain mematuhi."},{jp:"これほどの非常事態とあっては、冷静でいるのは難しい。",romaji:"",idText:"Dalam kondisi darurat seserius ini, sulit untuk tetap tenang."},{jp:"彼女の一言とあっては、断れない。",romaji:"",idText:"Kalau sudah kata-kata darinya, tidak bisa menolak."}]},{id:"exp-7",grammarId:"gn2-00099",title:"Pola: 〜いかんによって",formula:"N + いかんによって / いかんによっては",meaning:"tergantung pada ... / bergantung bagaimana ...",nuanceNotes:"〜いかんによって menyatakan bahwa hasil atau tindakan bergantung pada kondisi atau variabel tertentu yang disebutkan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜いかんによって",idText:"tergantung pada ... / bergantung bagaimana ..."}],examples:[{jp:"交渉の結果いかんによっては、契約を見直す可能性がある。",romaji:"",idText:"Tergantung hasil negosiasinya, ada kemungkinan kontrak perlu ditinjau ulang."},{jp:"対応いかんによって、顧客の信頼を失うこともある。",romaji:"",idText:"Tergantung bagaimana penanganannya, kepercayaan pelanggan bisa hilang."}]},{id:"exp-8",grammarId:"gn2-00104",title:"Pola: 〜に応じて",formula:"N + に応じて / に応じた (+ N)",meaning:"sesuai dengan ... / menyesuaikan dengan ... / bergantung pada ...",nuanceNotes:"〜に応じて menyatakan bahwa sesuatu berubah atau disesuaikan mengikuti kondisi, permintaan, atau situasi yang disebutkan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に応じて",idText:"sesuai dengan ... / menyesuaikan dengan ... / bergantung pada ..."}],examples:[{jp:"状況に応じて対応を変える必要がある。",romaji:"",idText:"Perlu mengubah respons sesuai situasi yang berkembang."},{jp:"収入に応じて税額が決まります。",romaji:"",idText:"Jumlah pajak ditentukan sesuai pendapatan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "検討 (けんとう)" dalam evaluasi teknis?',sentencePrompt:'Istilah "検討 (けんとう) する" dalam rapat teknis bermakna:',options:["Mengkaji, meneliti, atau mempertimbangkan secara saksama","Membuang peralatan lama ke tempat daur ulang","Memberhentikan operasional pabrik secara permanen","Mengganti oli mesin setiap 500 jam kerja"],correctAnswer:"Mengkaji, meneliti, atau mempertimbangkan secara saksama",explanation:'"検討 (けんとう)" bermakna mengkaji kelayakan, menimbang opsi, atau memeriksa secara mendalam sebelum memutuskan.',diagnosticFeedback:{"Membuang peralatan lama ke tempat daur ulang":"Salah: Pembuangan barang bekas adalah 廃棄 (haiki).","Memberhentikan operasional pabrik secara permanen":"Salah: Penutupan fasilitas permanen adalah 閉鎖 (heisa).","Mengganti oli mesin setiap 500 jam kerja":"Salah: Penggantian oli adalah オイル交換 (oiru koukan)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat dengan pola yang menyatakan tindakan seketika setelah suatu peristiwa:",sentencePrompt:"工場長【こうじょうちょう】が 到着【とうちゃく】[　　]、直【ただ】ちに 全体【ぜんたい】ミーティングを 始【はじ】めます。",options:["し次第【しだい】","した 上【うえ】で","する につれて","した ところで"],correctAnswer:"し次第【しだい】",explanation:'V-masu + 次第 menyatakan "segera setelah X terjadi, langsung melakukan Y". 到着し次第 = begitu tiba langsung...',diagnosticFeedback:{"した 上【うえ】で":"Kekeliruan Nuansa: 〜上で menekankan musyawarah atau pertimbangan prasyarat yang memakan waktu, bukan kesegeraan instan.","する につれて":"Kekeliruan Pola: 〜につれて menyatakan perubahan proporsional bertahap (seiring berjalannya waktu).","した ところで":"Kekeliruan Pola: 〜たところで menyatakan konsesi skeptis (bahkan seandainya X dilakukan pun, hasilnya sia-sia)."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Kesesuaian Bentuk): Manakah kalimat yang menggunakan pola 〜上で secara tepat?",sentencePrompt:"Pilihlah kalimat yang menggunakan 〜上で dengan bentuk gramatikal yang benar:",options:["両親【りょうしん】と 相談【そうだん】した 上【うえ】で、進路【しんろ】を 決【き】めたいと 思【おも】います。","両親【りょうしん】と 相談【そうだん】する 上【うえ】で、進路【しんろ】を 決【き】めました。","進路【しんろ】を 決【き】めた 上【うえ】で、両親【りょうしん】に 相談【そうだん】を 頼【たの】まれました。","相談【そうだん】の 上【うえ】に、進路【しんろ】が 自然【しぜん】に 決【き】まりました。"],correctAnswer:"両親【りょうしん】と 相談【そうだん】した 上【うえ】で、進路【しんろ】を 決【き】めたいと 思【おも】います。",explanation:"Bentuk lampau (Ta-kei) + 上で menyatakan bahwa tindakan kedua dilakukan berlandaskan hasil dari tindakan pertama (setelah berdiskusi).",diagnosticFeedback:{"両親【りょうしん】と 相談【そうだん】する 上【うえ】で、進路【しんろ】を 決【き】めました。":'Kekeliruan Bentuk: Sebelum 上で untuk arti "setelah", kata kerja wajib berbentuk lampau (soudan shita), bukan kamus.',"進路【しんろ】を 決【き】めた 上【うえ】で、両親【りょうしん】に 相談【そうだん】を 頼【たの】まれました。":"Logika Terbalik: Menetapkan masa depan baru kemudian berdiskusi memutarbalikkan etika pertimbangan keluarga.","相談【そうだん】の 上【うえ】に、進路【しんろ】が 自然【しぜん】に 決【き】まりました。":'Kekeliruan Partikel: Bentuk yang baku adalah 〜の上で, sedangkan 〜の上に bermakna "selain daripada itu / ditambah lagi".'}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi alur laporan kerja yang benar:",sentencePrompt:"Susunlah frasa-frasa berikut:",options:["ログを 取得【しゅとく】し次第【しだい】 レポートを 提出【ていしゅつ】いたします","レポートを 提出【ていしゅつ】いたします ログを 取得【しゅとく】し次第【しだい】","取得【しゅとく】し次第【しだい】 ログを レポートを 提出【ていしゅつ】いたします","ログを レポートを 取得【しゅとく】し次第【しだい】 提出【ていしゅつ】いたします"],correctAnswer:"ログを 取得【しゅとく】し次第【しだい】 レポートを 提出【ていしゅつ】いたします",explanation:"Urutan baku: Klausa syarat waktu (ログを取得し次第) mendahului tindakan utama (レポートを提出いたします).",diagnosticFeedback:{"レポートを 提出【ていしゅつ】いたします ログを 取得【しゅとく】し次第【しだい】":"Kekeliruan Urutan: Predikat penutup ditaruh di depan klausa waktu.","取得【しゅとく】し次第【しだい】 ログを レポートを 提出【ていしゅつ】いたします":'Kekeliruan Sintaksis: Objek "rogu o" harus berada sebelum verba "shutoku shi-shidai".',"ログを レポートを 取得【しゅとく】し次第【しだい】 提出【ていしゅつ】いたします":'Tumpukan Partikel: Menggabungkan dua partikel objek "o" berturut-turut tanpa pemisah klausa membuat kalimat rusak.'},tokens:["ログを","取得【しゅとく】し次第【しだい】","レポートを","提出【ていしゅつ】いたします"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Komitmen Eksekusi): Saat Kenji mengarahkan: 「最終テストの ログが 出次第、すぐに 開発チームへ 共有してください」, bagaimana tanggapan terbaik Anda?",sentencePrompt:"Pilihlah tanggapan yang menunjukkan kecepatan tindak lanjut dan tanggung jawab:",options:["かしこまりました！ ログを 取得【しゅとく】し次第【しだい】、速【すみ】やかに 分析【ぶんせき】レポートを 提出【ていしゅつ】いたします。","今【いま】は 忙【いそが】しいので、来週【らいしゅう】の 金曜日【きんようび】くらいに 送【おく】れば いいですか？","共有【きょうゆう】するの 忘【わす】れそうなので、健二【けんじ】さんが 自分【じぶん】で ログを 取【と】ってください。","テストなんて どうでもいいので、早【はや】く 帰【かえ】って ビールを 飲【の】みましょう！"],correctAnswer:"かしこまりました！ ログを 取得【しゅとく】し次第【しだい】、速【すみ】やかに 分析【ぶんせき】レポートを 提出【ていしゅつ】いたします。",explanation:'Ragam Kenjougo "teishutsu itashimasu" dan komitmen "shutoku shishidai" adalah standar kerja profesional Jepang.',diagnosticFeedback:{"今【いま】は 忙【いそが】しいので、来週【らいしゅう】の 金曜日【きんようび】くらいに 送【おく】れば いいですか？":'Lamban: Mengulur waktu hingga minggu depan bertentangan dengan instruksi "sugu ni".',"共有【きょうゆう】するの 忘【わす】れそうなので、健二【けんじ】さんが 自分【じぶん】で ログを 取【と】ってください。":"Kurang Ajar: Melempar tugas kembali kepada supervisor sangat tidak pantas.","テストなんて どうでもいいので、早【はや】く 帰【かえ】って ビールを 飲【の】みましょう！":"Meremehkan Tugas: Mengabaikan integritas testing dan mengajak minum di jam kerja."}}],can_do_challenge:{statement:"Bisa mengoordinasikan eksekusi prosedur bertahap dan melaporkan komitmen tindak lanjut seketika dalam alur kerja rekayasa.",situation:"Terminal Kontrol Pusat Lab Tsukuba, pukul 14.15",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜上で!",modelAnswer:"はい！ 各【かく】センサーの 通信【つうしん】テストを 実施【じっし】した 上【うえ】で、異常【いじょう】がないことを 確認【かくにん】いたしました。",modelAnswerId:"Ya! Setelah melaksanakan uji komunikasi pada masing-masing sensor, saya telah memastikan bahwa tidak ada anomali.",culturalEtiquette:'Menyatakan "kakunin no ue de susumemasu" memberikan rasa aman maksimal bagi atasan bahwa langkah kerja tidak diambil secara gegabah.',skillUnlocked:["Menguasai formulasi pola 〜上で","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Kemahiran Teknis, Penyerapan Ilmu & Adaptasi Beban"]},pocket_summary:{keyFormula:"V-ta / Nの + 上で (setelah ... / berlandaskan hasil ...), V-masu + 次第 (segera setelah ... langsung ...)",coreWords:["検討【けんとう】 (pertimbangan, peninjauan, mengkaji / mempertimbangkan)","実施【じっし】 (pelaksanaan, penyelenggaraan, pemberlakuan (resmi/hukum))","確認【かくにん】する (mengkonfirmasi, memverifikasi, memeriksa ulang)","報告【ほうこく】 (laporan, pelaporan)"],coreWarning:"Jangan memakai 〜次第 untuk hal-hal di masa lampau. Pola ini khusus merujuk komitmen tindakan masa depan begitu kondisi terpenuhi.",quickDialogue:"A: ブディさん、自動【じどう】搬送【はんそう】システム... → B: はい！ 各【かく】センサーの 通信【つうしん】テス..."}}},t={"les-n2-u05-01":{pedagogical_framework:{what:{summary:"Menguasai penyesuaian kebutuhan profesional: 〜に応じた (yang disesuaikan dengan...) dan evaluasi standar sikap: 〜ようでは (kalau bersikap begitu, mustahil...).",canDo:"Bisa merancang panduan kerja yang adaptif terhadap kapasitas individu serta mengevaluasi kedewasaan sikap kerja secara konstruktif.",targetPatterns:["N + に応じた / に応じて (yang disesuaikan dengan / sejalan dengan)","V-plain + ようでは / ようじゃ (kalau bersikap demikian, maka mustahil...)"],coreVocabSample:["適応【てきおう】","配慮【はいりょ】","共感【きょうかん】","指導【しどう】","理解【りかい】","ゆとり","対応【たいおう】","姿勢【しせい】"]},sensei_context:{sceneIntro:"Ruang istirahat dan konsultasi pendampingan magang multinasional di Shizuoka. Sakura (Konsultan Manajemen) berdiskusi dengan Budi mengenai metode bimbingan rekan magang baru.",dailyMission:'Gunakan "ni oujita" untuk menawarkan solusi personal dan pahami peringatan "you dewa" untuk menjaga ketenangan membimbing.',whyOrder:"Komunikasi N2 tidak hanya menuntut instruksi teknis, melainkan kecerdasan emosional dalam menyesuaikan pendekatan pengajaran terhadap kapasitas rekan kerja."},cultural_notes:{title:"Bimbingan Adaptif (個別指導) dan Kedewasaan Sikap (大人の対応)",etiquette:"Dalam filosofi Omoiyari, instruktur senior harus menunjukkan kematangan emosi. Bila mentor tampak panik, junior akan kehilangan rasa percaya diri.",taboos:"Jangan menggunakan frasa 〜ようでは untuk memarahi bawahan di depan forum umum. Sampaikan kritik tajam ini hanya dalam sesi mentoring empat mata (Mendan)."},pronunciation_tips:{title:"Intonasi Penyesuaian dan Peringatan",moraNote:'Pada "ni oujita", morfem ou dilafalkan panjang 2 mora: o-o-ji-ta.',soundTip:'Pada "you dewa", turunkan sedikit nada pada de-wa untuk memberi penekanan peringatan yang berbobot tanpa terdengar berteriak.'},common_pitfalls:[{title:"Tertukar Antara 〜に応じた (Modifikasi Nomina) vs 〜に応じて (Bentuk Adverbial)",caseScenario:'Menggunakan "ni oujite" langsung sebelum kata benda tanpa partikel modifikasi.',pitfallWarning:"能力【のうりょく】に 応【おう】じて 指導【しどう】マニュアル (Kurang tepat secara gramatikal)",rightSolution:"能力【のうりょく】に 応【おう】じた 指導【しどう】マニュアル (Tepat: menerangkan nomina)",explanation:"Bila menerangkan kata benda berikutnya, gunakan bentuk 〜に応じた. Bila memodifikasi kata kerja predikat, gunakan 〜に応じて."},{title:"Salah Nada Akibat 〜ようでは yang Bersifat Negatif Mutlak",caseScenario:"Memakai 〜ようでは untuk hasil yang positif.",pitfallWarning:"頑張【がんば】る ようでは、成功【せいこう】します。 (Salah)",rightSolution:"ミスを 恐【おそ】れる ようでは、成長【せいちょう】できない。 (Tepat: hasil negatif/kendala)",explanation:"Pola 〜ようでは selalu diikuti oleh klausa evaluasi negatif (tidak akan berhasil, payah, tidak ada kemajuan)."}],who_and_when:{situational_context:"Penyusunan kurikulum pelatihan internal, evaluasi kinerja bulanan staf, dan konsultasi empat mata.",social_relations:"Konsultasi kolegial hangat antara mentor senior (Sakura) dan praktisi pembelajar (Budi).",when_not_to_use:"Jangan gunakan 〜ようでは kepada atasan langsung karena menyiratkan penilaian meremehkan standar kompetensi lawan bicara."},scenario:{title:"Penyempurnaan Modul Pelatihan Adaptif",setting:"Ruang Konsultasi Kemitraan Shizuoka, pukul 11.00",narrative:"Sakura menelaah draf materi orientasi magang yang disusun Budi agar ramah bagi peserta pemula."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Konsultan Manajemen",avatar:"👩‍🏫",jp:"ブディさん、現場【げんば】の 習熟【しゅうじゅく】度【ど】に 応【おう】じた 指導【しどう】マニュアルの 改訂【かいてい】は、うまく 進【すす】んでいますか？",furigana:"ブディさん、現場の 習熟度に 応じた 指導マニュアルの 改訂は、うまく 進んでいますか？",romaji:"Budi-san, gemba no shuujukudo ni oujita shidou manyuaru no kaitei wa, umaku susunde imasu ka?",idText:"Budi, apakah revisi manual bimbingan yang disesuaikan dengan tingkat kemahiran lapangan berjalan lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、さくらさん！ 各自【かくじ】の 理解度【りかいど】に 応【おう】じて、図解【ずかい】入【い】りの 解説【かいせつ】を 追加【ついか】しております。",furigana:"はい、さくらさん！ 各自の 理解度に 応じて、図解入りの 解説を 追加しております。",romaji:"Hai, Sakura-san! Kakuji no rikaido ni oujite, zukaiiri no kaisetsu o tsuika shite orimasu.",idText:"Ya, Sakura-san! Disesuaikan dengan tingkat pemahaman masing-masing, saya telah menambahkan penjelasan bergambar."},{id:"d3",speaker:"Sakura",speakerRole:"Konsultan Manajemen",avatar:"👩‍🏫",jp:"丁寧【ていねい】な 工夫【くふう】ですね。ただ、指導者【しどうしゃ】が 焦【あせ】る ようでは、後輩【こうはい】たちも 不安【ふあん】に なってしまいますよ。",furigana:"丁寧な 工夫ですね。ただ、指導者が 焦る ようでは、後輩たちも 不安に なってしまいますよ。",romaji:"Teineina kufuu desu ne. Tada, shidousha ga aseru you dewa, kouhaitachi mo fuan ni natte shimaimasu yo.",idText:"Inovasi yang teliti ya. Namun, kalau instrukturnya tampak tergesa-gesa/panik, para junior pun akan ikut merasa cemas lho."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ご指摘【してき】の 通【とお】りです。常【つね】に 余裕【よゆう】を 持【も】って、温【あたた】かく サポートするよう 心【こころ】がけます。",furigana:"ご指摘の 通りです。常に 余裕を 持って、温かく サポートするよう 心がけます。",romaji:"Goshiteki no toori desu. Tsuneni yoyuu o motte, atatakaku sapooto suru you kokorogakemasu.",idText:"Tepat seperti yang Anda sampaikan. Saya akan selalu berupaya tenang dan memberikan pendampingan yang hangat."}],vocab_breakdown:[{id:"vg-n2-01186",word:"消化",reading:"しょうか",romaji:"shouka",meaning:"pencernaan",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 消化 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"食物は胃の中で消化される。",furigana:"食物は胃の中で消化される。",romaji:"shouka",idText:"Makanan dicerna di perut."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"ショウカ￣"}},{id:"vg-n2-01199",word:"乗車",reading:"じょうしゃ",romaji:"jousha",meaning:"naik kereta api; menarik",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 乗車 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"ご乗車ありがとうございます。",furigana:"ご乗車ありがとうございます。",romaji:"jousha",idText:"Welcome aboard!"},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"ジョウシャ￣"}},{id:"vg-n2-01205",word:"消毒",reading:"しょうどく",romaji:"shoudoku",meaning:"desinfeksi; sterilisasi",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 消毒 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"消毒を使います。",furigana:"消毒を使います。",romaji:"shoudoku",idText:"Menggunakan disinfection; sterilization."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ショウドク￣"}},{id:"vg-n2-01207",word:"蒸発",reading:"じょうはつ",romaji:"jouhatsu",meaning:"penguapan; hilangnya yang tidak dapat dijelaskan",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 蒸発 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"聞きましたわよ。ご両親が借金を残して蒸発したそうですわね。",furigana:"聞きましたわよ。ご両親が借金を残して蒸発したそうですわね。",romaji:"jouhatsu",idText:"Saya pernah mendengarnya. Orang tuamu menghilang, hutangnya habis bukan?"},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ジョウハツ￣"}},{id:"vg-n2-01209",word:"勝負",reading:"しょうぶ",romaji:"shoubu",meaning:"victory or defeat; match",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 勝負 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"ボブはスケートではきみといい勝負だ。",furigana:"ボブはスケートではきみといい勝負だ。",romaji:"shoubu",idText:"Bob adalah pasangan yang cocok untukmu dalam skating."},pitch:{pattern:1,category:"atamadaka",mora_count:3,downstep_mora:1,contour:"ショ＼ウブ"}},{id:"vg-n2-01210",word:"小便",reading:"しょうべん",romaji:"shouben",meaning:"(sehari-hari) urin; kencing",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 小便 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"「小便が琥珀色だと言われたら、脱水症状だ」",furigana:"「小便が琥珀色だと言われたら、脱水症状だ」",romaji:"shouben",idText:'"Jika mereka mengatakan kencing Anda berwarna kuning, itu berarti Anda mengalami dehidrasi."'},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"ショウベ＼ン"}},{id:"vg-n2-01214",word:"消耗",reading:"しょうもう",romaji:"shoumou",meaning:"kelelahan; konsumsi",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 消耗 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"その男の子の世話で彼女は非常に精力を消耗する。",furigana:"その男の子の世話で彼女は非常に精力を消耗する。",romaji:"shoumou",idText:"Merawat anak laki-laki itu sangat menguras energinya."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ショウコウ￣"}},{id:"vg-n2-01215",word:"省略",reading:"しょうりゃく",romaji:"shouryaku",meaning:"omission; abbreviation",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 省略 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"この句では前置詞を省略できる。",furigana:"この句では前置詞を省略できる。",romaji:"shouryaku",idText:"Anda dapat menghilangkan preposisi dalam frasa ini."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ショウリャク￣"}}],explanations:[{id:"exp-1",grammarId:"gn2-00105",title:"Pola: 〜に応じた",formula:"N + に応じた + N (bentuk atributif)",meaning:"yang disesuaikan dengan ... / yang sesuai dengan ...",nuanceNotes:'〜に応じた adalah bentuk atributif (prenominal) dari に応じて, digunakan langsung sebelum nomina untuk menyatakan "N yang disesuaikan dengan X".',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に応じた",idText:"yang disesuaikan dengan ... / yang sesuai dengan ..."}],examples:[{jp:"個人の能力に応じた学習計画を作成してください。",romaji:"",idText:"Tolong buat rencana belajar yang disesuaikan dengan kemampuan masing-masing individu."},{jp:"ニーズに応じたサービスを提供することが重要だ。",romaji:"",idText:"Penting untuk menyediakan layanan yang disesuaikan dengan kebutuhan pelanggan."}]},{id:"exp-2",grammarId:"gn2-00187",title:"Pola: 〜ようでは",formula:"V-plain + ようでは / い-Adj-plain + ようでは / N + の + ようでは",meaning:"kalau sampai ..., kalau kondisinya seperti itu ...",nuanceNotes:"〜ようでは menyatakan kondisi hipotetis yang tidak diinginkan sebagai dasar untuk penilaian negatif atau peringatan. Mengungkapkan bahwa jika kondisi demikian memang terjadi, maka hasilnya akan bermasalah.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ようでは",idText:"kalau sampai ..., kalau kondisinya seperti itu ..."}],examples:[{jp:"こんな簡単な問題も解けないようでは、試験は無理だ。",romaji:"",idText:"Kalau soal semudah ini saja tidak bisa diselesaikan, ujiannya tidak akan berhasil."},{jp:"部下の名前も覚えていないようでは、リーダーとして失格だ。",romaji:"",idText:"Kalau sampai nama bawahannya sendiri tidak hafal, itu tidak layak sebagai pemimpin."}]},{id:"exp-3",grammarId:"gn2-00188",title:"Pola: 〜ようでは困る",formula:"V-plain + ようでは困る / い-Adj-plain + ようでは困る",meaning:"tidak baik kalau sampai ..., tidak bisa dibiarkan kalau ...",nuanceNotes:"〜ようでは困る adalah pola spesifik dari ようでは yang diikuti 困る — menyatakan bahwa suatu kondisi atau perilaku yang disebutkan tidak bisa diterima atau bermasalah. Sering digunakan untuk menyampaikan ketidakpuasan atau peringatan kepada orang yang dinilai.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ようでは困る",idText:"tidak baik kalau sampai ..., tidak bisa dibiarkan kalau ..."}],examples:[{jp:"毎回遅刻するようでは困る。",romaji:"",idText:"Tidak bisa dibiarkan kalau setiap kali selalu datang terlambat."},{jp:"指示を一度しか言わないのに聞いていないようでは困る。",romaji:"",idText:"Tidak baik kalau instruksi yang hanya disampaikan sekali saja tidak diperhatikan."}]},{id:"exp-4",grammarId:"gn2-00198",title:"Pola: 〜を条件に",formula:"N + を条件に(して) / V-plain + ことを条件に",meaning:"dengan syarat ..., asalkan ...",nuanceNotes:"〜を条件に menyatakan bahwa suatu tindakan atau persetujuan baru akan berlaku jika syarat tertentu terpenuhi. Syarat ini bersifat aktif dan harus benar-benar dipenuhi — berbeda dari asumsi yang sudah diterima. Pola ini sering muncul dalam konteks negosiasi, perjanjian, atau izin.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜を条件に",idText:"dengan syarat ..., asalkan ..."}],examples:[{jp:"毎日練習することを条件に、チームへの入部を許可した。",romaji:"",idText:"Dengan syarat berlatih setiap hari, dia diizinkan masuk tim."},{jp:"秘密を守ることを条件に、話してあげた。",romaji:"",idText:"Asalkan merahasiakannya, saya ceritakan kepadanya."},{jp:"給料の引き上げを条件に、残業に応じた。",romaji:"",idText:"Dengan syarat kenaikan gaji, dia menyetujui lembur."}]},{id:"exp-5",grammarId:"gn2-00220",title:"Pola: 〜次第で",formula:"N + 次第で / 次第だ / 次第では",meaning:"tergantung pada ..., bergantung pada ...",nuanceNotes:'〜次第で menyatakan bahwa hasil atau kondisi sepenuhnya bergantung pada hal yang disebutkan. Mengandung makna bahwa faktor tersebut adalah penentu yang krusial — jika berbeda, hasilnya pun akan berbeda. Bentuk 〜次第では menambahkan nuansa "tergantung pada situasinya, bisa jadi...".',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜次第で",idText:"tergantung pada ..., bergantung pada ..."}],examples:[{jp:"努力次第で、結果は変わる。",romaji:"",idText:"Hasilnya akan berubah tergantung pada usaha yang dilakukan."},{jp:"やり方次第で、うまくいくこともある。",romaji:"",idText:"Tergantung caranya, bisa saja berhasil."},{jp:"状況次第では、計画を変更する可能性もある。",romaji:"",idText:"Tergantung situasi, ada kemungkinan rencana akan diubah."}]},{id:"exp-6",grammarId:"gn2-00222",title:"Pola: 〜とあれば",formula:"N / phrase + とあれば",meaning:"kalau memang ... / jika situasinya demikian maka (rela melakukan)",nuanceNotes:"〜とあれば menyatakan bahwa jika kondisi atau alasan yang disebutkan terpenuhi, maka pembicara bersedia atau merasa harus melakukan sesuatu. Mengandung nuansa kerelaan atau dorongan kuat karena situasinya.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜とあれば",idText:"kalau memang ... / jika situasinya demikian maka (rela melakukan)"}],examples:[{jp:"子供のためとあれば、どんな苦労も厭わない。",romaji:"",idText:"Kalau memang demi anak, tidak ada kesulitan yang tidak rela aku tanggung."},{jp:"彼女の頼みとあれば、断れない。",romaji:"",idText:"Kalau memang itu permintaannya, aku tidak bisa menolak."}]},{id:"exp-7",grammarId:"gn2-00240",title:"Pola: 〜いかん",formula:"N + いかん",meaning:"tergantung bagaimana / bergantung pada ... (formal)",nuanceNotes:"〜いかん menyatakan bahwa sesuatu bergantung pada kondisi atau cara yang disebutkan. Merupakan ekspresi formal yang sering muncul dalam konteks administratif, hukum, atau tulisan resmi.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜いかん",idText:"tergantung bagaimana / bergantung pada ... (formal)"}],examples:[{jp:"今後の対応いかんでは、契約を解除することになる。",romaji:"",idText:"Tergantung bagaimana penanganan ke depannya, bisa saja kontrak dibatalkan."},{jp:"結果いかんによって、次の対策を検討する。",romaji:"",idText:"Tergantung pada hasilnya, kami akan mempertimbangkan langkah selanjutnya."}]},{id:"exp-8",grammarId:"gn2-00241",title:"Pola: 〜いかんによっては",formula:"N + いかんによっては",meaning:"tergantung bagaimana ... / bergantung pada kondisi/hasil ...",nuanceNotes:"〜いかんによっては menyatakan bahwa bergantung pada kondisi atau hasilnya, konsekuensi tertentu mungkin terjadi. Menekankan bahwa ada kemungkinan perubahan atau variasi berdasarkan kondisi yang disebutkan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜いかんによっては",idText:"tergantung bagaimana ... / bergantung pada kondisi/hasil ..."}],examples:[{jp:"検査の結果いかんによっては、入院が必要になるかもしれない。",romaji:"",idText:"Tergantung hasil pemeriksaan, mungkin diperlukan rawat inap."},{jp:"今後の態度いかんによっては、処分を検討することになる。",romaji:"",idText:"Bergantung pada sikap ke depannya, akan dipertimbangkan sanksi."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "適応 (てきおう)" dalam pendampingan kerja multinasional?',sentencePrompt:'Istilah "環境【かんきょう】への 適応【てきおう】" bermakna:',options:["Penyesuaian diri secara harmonis terhadap lingkungan baru","Penolakan terhadap budaya setempat secara terang-terangan","Pengrusakan fasilitas kantor akibat frustrasi","Pergantian kewarganegaraan secara mendadak"],correctAnswer:"Penyesuaian diri secara harmonis terhadap lingkungan baru",explanation:'"適応 (てきおう)" bermakna proses beradaptasi dan menyesuaikan diri dengan kondisi atau iklim lingkungan kerja.',diagnosticFeedback:{"Penolakan terhadap budaya setempat secara terang-terangan":"Salah: Penolakan adalah 拒絶 (kyozetsu) atau 反発 (hampatsu).","Pengrusakan fasilitas kantor akibat frustrasi":"Salah: Pengrusakan barang adalah 器物損壊 (kibutsu sonkai).","Pergantian kewarganegaraan secara mendadak":"Salah: Pergantian kewarganegaraan adalah 帰化 (kika)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat dengan pola modifikasi nomina yang tepat:",sentencePrompt:"参加者【さんかしゃ】の 年齢【ねんれい】や 体力【たいりょく】[　　] トレーニング計画【けいかく】を 作成【さくせい】した。",options:["に 応【おう】じた","に 応【おう】じて","の 上【うえ】で","し 次第【しだい】"],correctAnswer:"に 応【おう】じた",explanation:"Untuk memodifikasi kata benda berikutnya (トレーニング計画), gunakan bentuk 〜に応じた (yang disesuaikan dengan...).",diagnosticFeedback:{"に 応【おう】じて":"Kekeliruan Bentuk: 〜に応じて berfungsi sebagai adverbia predikat, sedangkan di sini kalimat membutuhkan pemodifikasi nomina (keikaku).","の 上【うえ】で":'Kekeliruan Nuansa: 〜の上で bermakna "setelah menuntaskan pertimbangan", bukan kesesuaian proporsi karakteristik peserta.',"し 次第【しだい】":"Kekeliruan Pola: 〜次第 berarti segera setelah, tidak cocok dengan nomina usia/stamina."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Kaidah Konsekuensi): Manakah kalimat yang menggunakan 〜ようでは secara benar?",sentencePrompt:"Pilihlah kalimat yang menggunakan 〜ようでは secara gramatikal dan bernuansa tepat:",options:["こんな 簡単【かんたん】な 単語【たんご】で つまずく ようでは、N2 合格【ごうかく】など 思【おぼ】つかない。","毎日【まいにち】 一生懸命【いっしょうけんめい】 勉強【べんきょう】する ようでは、きっと 合格【ごうかく】できる。","笑顔【えがお】で 挨拶【あいさつ】する ようでは、みんなから 信頼【しんらい】される。","時間【じかん】を 厳守【げんしゅ】する ようでは、プロの 技術者【ぎじゅつしゃ】として 頼【たよ】もしい。"],correctAnswer:"こんな 簡単【かんたん】な 単語【たんご】で つまずく ようでは、N2 合格【ごうかく】など 思【おぼ】つかない。",explanation:"Pola 〜ようでは mensyaratkan kondisi negatif/kekurangan di klausa pertama yang berujung pada kemustahilan/kegagalan di klausa kedua.",diagnosticFeedback:{"毎日【まいにち】 一生懸命【いっしょうけんめい】 勉強【べんきょう】する ようでは、きっと 合格【ごうかく】できる。":"Kekeliruan Makna: Klausa kedua bernada positif berhasil (goukaku dekiru), tidak boleh dipadukan dengan 〜ようでは.","笑顔【えがお】で 挨拶【あいさつ】する ようでは、みんなから 信頼【しんらい】される。":"Kekeliruan Nada: Menyapa dengan ramah adalah perbuatan terpuji, tidak cocok untuk pola kritik 〜ようでは.","時間【じかん】を 厳守【げんしゅ】する ようでは、プロの 技術者【ぎじゅつしゃ】として 頼【たよ】もしい。":"Kekeliruan Nada: Tepat waktu adalah kualitas profesional positif, bertentangan dengan fungsi celaan 〜ようでは."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun frasa-frasa berikut menjadi kalimat nasihat yang benar:",sentencePrompt:"Susunlah frasa-frasa berikut:",options:["指導者【しどうしゃ】が 焦【あせ】る ようでは 後輩【こうはい】も 不安【ふあん】になる","後輩【こうはい】も 不安【ふあん】になる 指導者【しどうしゃ】が 焦【あせ】る ようでは","焦【あせ】る ようでは 指導者【しどうしゃ】が 後輩【こうはい】も 不安【ふあん】になる","指導者【しどうしゃ】が 不安【ふあん】になる 焦【あせ】る ようでは 後輩【こうはい】も"],correctAnswer:"指導者【しどうしゃ】が 焦【あせ】る ようでは 後輩【こうはい】も 不安【ふあん】になる",explanation:"Urutan logis: Klausa syarat pengandaian celaan (指導者が焦るようでは) mendahului dampak psikologis junior (後輩も不安になる).",diagnosticFeedback:{"後輩【こうはい】も 不安【ふあん】になる 指導者【しどうしゃ】が 焦【あせ】る ようでは":"Kekeliruan Urutan: Konsekuensi diletakkan mendahului klausa syarat pengandaian.","焦【あせ】る ようでは 指導者【しどうしゃ】が 後輩【こうはい】も 不安【ふあん】になる":"Kekeliruan Subjek: Partikel subjek が harus berada langsung setelah nomina pemimpin (shidousha ga).","指導者【しどうしゃ】が 不安【ふあん】になる 焦【あせ】る ようでは 後輩【こうはい】も":"Susunan Acak: Merancukan subjek pemimpin dengan predikat cemas."},tokens:["指導者【しどうしゃ】が","焦【あせ】る ようでは","後輩【こうはい】も","不安【ふあん】になる"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Kematangan Emosi): Saat Sakura menasihati: 「指導者が 焦るようでは、後輩たちも 不安になってしまいますよ」, bagaimana respons terbaik Anda?",sentencePrompt:"Pilihlah tanggapan yang menunjukkan keterbukaan menerima masukan dan ketenangan mental:",options:["ご指摘【してき】の 通【とお】りです。常【つね】に 余裕【よゆう】を 持【も】って、温【あたた】かく サポートするよう 心【こころ】がけます。","後輩【こうはい】たちが 悪【わる】いんです！ 何度【なんど】 言【い】っても 理解【りかい】しないから イライラするんです。","さくらさん、そんな 小【ちい】さな ことで 私【わたし】に 説教【せっきょう】しないでください。","もう 指導【しどう】なんて やめたいです。明日【あした】から 会社【かいしゃ】を 休【やす】みます。"],correctAnswer:"ご指摘【してき】の 通【とお】りです。常【つね】に 余裕【よゆう】を 持【も】って、温【あたた】かく サポートするよう 心【こころ】がけます。",explanation:"Menerima masukan mentor dengan berjiwa besar (Goshiteki no toori desu) dan bertekad menjaga ketenangan.",diagnosticFeedback:{"後輩【こうはい】たちが 悪【わる】いんです！ 何度【なんど】 言【い】っても 理解【りかい】しないから イライラするんです。":"Menyalahkan Bawahan: Melampiaskan emosi dan menyalahkan peserta didik bertentangan dengan profesionalisme pembimbing.","さくらさん、そんな 小【ちい】さな ことで 私【わたし】に 説教【せっきょう】しないでください。":"Defensif & Menentang: Menolak saran konstruksi mentor dengan nada kasar.","もう 指導【しどう】なんて やめたいです。明日【あした】から 会社【かいしゃ】を 休【やす】みます。":"Kanak-kanak: Mengancam bolos kerja saat diberi masukan menunjukkan ketidakmatangan mental."}}],can_do_challenge:{statement:"Bisa merancang panduan kerja yang adaptif terhadap kapasitas individu serta mengevaluasi kedewasaan sikap kerja secara konstruktif.",situation:"Ruang Konsultasi Kemitraan Shizuoka, pukul 11.00",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜に応じた!",modelAnswer:"はい、さくらさん！ 各自【かくじ】の 理解度【りかいど】に 応【おう】じて、図解【ずかい】入【い】りの 解説【かいせつ】を 追加【ついか】しております。",modelAnswerId:"Ya, Sakura-san! Disesuaikan dengan tingkat pemahaman masing-masing, saya telah menambahkan penjelasan bergambar.",culturalEtiquette:"Dalam filosofi Omoiyari, instruktur senior harus menunjukkan kematangan emosi. Bila mentor tampak panik, junior akan kehilangan rasa percaya diri.",skillUnlocked:["Menguasai formulasi pola 〜に応じた","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Gejolak Emosi, Dorongan Spontan & Resonansi Batin"]},pocket_summary:{keyFormula:"N + に応じた / に応じて (yang disesuaikan dengan / sejalan dengan), V-plain + ようでは / ようじゃ (kalau bersikap demikian, maka mustahil...)",coreWords:["適応【てきおう】 (adaptation; accommodation)","配慮【はいりょ】 (perhatian/pertimbangan terhadap orang lain, kepedulian)","共感【きょうかん】 (simpati; tanggapan)","指導【しどう】 (bimbingan, arahan, pembinaan, panduan instruksional)"],coreWarning:"Jangan menggunakan frasa 〜ようでは untuk memarahi bawahan di depan forum umum. Sampaikan kritik tajam ini hanya dalam sesi mentoring empat mata (Mendan).",quickDialogue:"A: ブディさん、現場【げんば】の 習熟【しゅうじゅく】... → B: はい、さくらさん！ 各自【かくじ】の 理解度【りか..."}},"les-n2-u05-02":{pedagogical_framework:{what:{summary:"Menguasai ekspresi emosi mendalam tak terbendung: 〜てならない (rasa batin alamiah yang sangat kuat) dan komitmen tanggung jawab etis: 〜わけにはいかない (secara moral/tanggung jawab tidak boleh menyerah).",canDo:"Bisa mengutarakan rasa empati tulus terhadap rekan kerja yang menghadapi kesulitan, serta menegaskan tekad pantang menyerah.",targetPatterns:["V-te / A-kute / Na-de + ならない (sangat terasa hingga tak tertahankan)","V-dict + わけにはいかない (secara etis/tanggung jawab tidak mungkin melakukan...)"],coreVocabSample:["共感【きょうかん】","尊重【そんちょう】","心配【しんぱい】する","責任【せきにん】","励【はげ】ます","有機【ゆうき】","絆【きずな】","全力【ぜんりょく】"]},sensei_context:{sceneIntro:"Sore hari di teras ruang bimbingan Shizuoka. Sakura dan Budi mengamati peserta magang baru yang tampak rindu kampung halaman dan berdiskusi bagaimana memberikan dukungan moril.",dailyMission:'Ungkapkan empati mendalam dengan "wakatte naranai" dan tegaskan integritas kepemimpinan dengan "makeru wake ni wa ikanai".',whyOrder:"Pola ~te naranai mengekspresikan dorongan batin alamiah (spontan/involunter), sementara ~wake ni wa ikanai adalah jangkar etis: menyelaraskan perasaan hati dengan integritas tanggung jawab sosial."},cultural_notes:{title:"Empati Tulus (共感 - Kyoukan) dan Tanggung Jawab Moral Senior (先輩の責任)",etiquette:"Mengakui rasa cemas batin (shimpai de naranai) kepada mentor menunjukkan kejujuran emosional, namun harus diimbangi tekad tidak boleh menyerah (akirameru wake ni wa ikanai).",taboos:"Jangan gunakan 〜てならない untuk kondisi fisik murni sesaat (seperti kebelet buang air kecil). Untuk kondisi fisik mendesak, gunakan 〜てたまらない."},pronunciation_tips:{title:"Intonasi Kelembutan Rasa Batin",moraNote:'Pada frasa "te naranai", artikulasikan na-ra-na-i dengan tempo lembut menurun untuk mencerminkan kedalaman batin.',soundTip:'Pada "wake ni wa ikanai", beri penekanan ketegasan pada mora "wa-ke" untuk mempertegas batas prinsip moral.'},common_pitfalls:[{title:"Tertukar Antara 〜てならない (Perasaan Batin Spontan) vs 〜てたまらない (Sensasi Fisik Mendesak)",caseScenario:"Ingin mengatakan sangat haus ingin minum.",pitfallWarning:"のどが 渇【かわ】いて ならない。 (Kurang alami)",rightSolution:"のどが 渇【かわ】いて たまらない。 (Tepat: sensasi fisik mendesak)",explanation:"〜てならない digunakan untuk emosi batiniah abstrak (khawatir, penasaran, sedih, rindu), sedangkan 〜てたまらない mencakup sensasi fisik mendesak (haus, gatal, lapar)."},{title:"Memakai Verba yang Bukan Emosi Spontan Sebelum 〜てならない",caseScenario:"Memasukkan verba tindakan sengaja ke dalam ~te naranai.",pitfallWarning:"パソコンを 買【か】って ならない。 (Salah total)",rightSolution:"気【き】に なって ならない。 (Tepat: dorongan rasa penasaran)",explanation:"Pola ini hanya dapat dipadukan dengan kata sifat emosi (shimpai, fuan, kanashii) atau verba spontan (omowareru, ki ni naru)."}],who_and_when:{situational_context:"Percakapan refleksi empat mata mengenai dinamika tim, konseling bimbingan mental peserta, dan penetapan tekad proyek.",social_relations:"Hubungan saling percaya yang mendalam antara mentor (Sakura) dan junior teladan (Budi).",when_not_to_use:"Jangan gunakan di depan forum audit legal formal yang menuntut bahasa statistik kaku tanpa emosi."},scenario:{title:"Dukungan Moril Peserta Magang di Shizuoka",setting:"Teras Gedung Pelatihan Shizuoka, pukul 16.45",narrative:"Matahari terbenam. Sakura dan Budi merenungkan tantangan emosional yang dihadapi para peserta magang baru."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Konsultan Manajemen",avatar:"👩‍🏫",jp:"ブディさん、新【あたら】しく 来【き】た 実習【じっしゅう】生【せい】たちが 日本【にほん】の 寒【さむ】さに 慣【な】れたか、心配【しんぱい】で なりませんね。",furigana:"ブディさん、新しく 来た 実習生たちが 日本の 寒さに 慣れたか、心配で なりませんね。",romaji:"Budi-san, atarashiku kita jisshuuseitachi ga Nihon no samusa ni nareta ka, shimpai de narimasen ne.",idText:"Budi, memikirkan apakah para peserta magang yang baru datang sudah terbiasa dengan dinginnya Jepang, rasanya sangat mencemaskan ya."},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"本当【ほんとう】に そうですね。私【わたし】も 来日【らいにち】当初【とうしょ】は 不安【ふあん】でしたから、彼【かれ】らの 気持【きも】ちが 分【わ】かって なりません。",furigana:"本当に そうですね。私も 来日当初は 不安でしたから、彼らの 気持ちが 分かって なりません。",romaji:"Hontou ni sou desu ne. Watashi mo rainichi tousho wa fuan deshita kara, karera no kimochi ga wakatte narimasen.",idText:"Benar sekali. Karena saya pun dulu saat awal tiba di Jepang merasa cemas, saya sangat bisa merasakan apa yang ada di hati mereka."},{id:"d3",speaker:"Sakura",speakerRole:"Konsultan Manajemen",avatar:"👩‍🏫",jp:"分【わ】かります。でも、先輩【せんぱい】として 私【わたし】たちが 弱気【よわき】に なる わけには いきませんね。",furigana:"分かります。でも、先輩として 私たちが 弱気に なる わけには いきませんね。",romaji:"Wakarimasu. Demo, sempai to shite watashitachi ga yowaki ni naru wake ni wa ikimasen ne.",idText:"Saya paham. Namun, sebagai senior, tidak mungkin bagi kita untuk bersikap lemah/pesimistis kan."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"おっしゃる 通【とお】りです！ 頼【たよ】れる 先輩【せんぱい】として、全力【ぜんりょく】で 彼【かれ】らの 生活【せいかつ】と 学【まな】びを 支【ささ】えてまいります。",furigana:"おっしゃる 通りです！ 頼れる 先輩として、全力で 彼らの 生活と 学びを 支えてまいります。",romaji:"Ossharu toori desu! Tayoreru sempai to shite, zenryoku de karera no seikatsu to manabi o sasaete mairimasu.",idText:"Tepat seperti yang Anda katakan! Sebagai senior yang dapat diandalkan, saya akan mendukung kehidupan dan pembelajaran mereka sekuat tenaga."}],vocab_breakdown:[{id:"vg-n2-01394",word:"揃う",reading:"そろう",romaji:"sorou",meaning:"menjadi lengkap",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 揃う / 〜に関する 揃う dalam wacana profesional.",exampleSentence:{jp:"この手袋は両方がそろっていない。",furigana:"この手袋は両方がそろっていない。",romaji:"sorou",idText:"Sarung tangan mereka tidak berpasangan."},pitch:{pattern:2,category:"nakadaka",mora_count:3,downstep_mora:2,contour:"ソロ＼ウ"}},{id:"vg-n2-01395",word:"揃える",reading:"そろえる",romaji:"soroeru",meaning:"mengatur segala sesuatunya",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 揃える / 〜に関する 揃える dalam wacana profesional.",exampleSentence:{jp:"パーティーには食べ物や飲物が豊富に揃えて有った。",furigana:"パーティーには食べ物や飲物が豊富に揃えて有った。",romaji:"soroeru",idText:"Makanan dan minuman berlimpah di pesta itu."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"ソロエ＼ル"}},{id:"vg-n2-01397",word:"存じる",reading:"ぞんじる",romaji:"zonjiru",meaning:"mengetahui / kenal",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 存じる / 〜に関する 存じる dalam wacana profesional.",exampleSentence:{jp:"いっこうに存じません。",furigana:"いっこうに存じません。",romaji:"zonjiru",idText:"I know nothing about it."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"ゾンジ＼ル"}},{id:"vg-n2-01407",word:"対照",reading:"たいしょう",romaji:"taishou",meaning:"contrast; antithesis",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 対照 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"赤は青と美しい対照をなす。",furigana:"赤は青と美しい対照をなす。",romaji:"taishou",idText:"Merah sangat kontras dengan biru."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"タイショウ￣"}},{id:"vg-n2-01411",word:"体操",reading:"たいそう",romaji:"taisou",meaning:"gymnastics; physical exercises",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 体操 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"朝食前にいつも体操をします。",furigana:"朝食前にいつも体操をします。",romaji:"taisou",idText:"I always take some exercise before breakfast."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"タイソウ￣"}},{id:"vg-n2-01419",word:"ダイヤル",reading:"ダイヤル",romaji:"daiyaru",meaning:"panggil",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を ダイヤル (objek tindakan kerja/bisnis).",exampleSentence:{jp:"彼は自転車のロックのダイヤルを回した。",furigana:"彼は自転車のロックのダイヤルを回した。",romaji:"daiyaru",idText:"Dia memutar tombol kunci sepeda."},pitch:{pattern:0,category:"heiban",mora_count:0,downstep_mora:0,contour:"￣"}},{id:"vg-n2-01423",word:"高める",reading:"たかめる",romaji:"takameru",meaning:"menaikkan",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 高める / 〜に関する 高める dalam wacana profesional.",exampleSentence:{jp:"その小説は彼の名声を更に高めた。",furigana:"その小説は彼の名声を更に高めた。",romaji:"takameru",idText:"Novel itu menambah reputasinya."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"タカメ＼ル"}},{id:"vg-n2-01424",word:"耕す",reading:"たがやす",romaji:"tagayasu",meaning:"sampai",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 耕す / 〜に関する 耕す dalam wacana profesional.",exampleSentence:{jp:"農家の人達は鋤で土を耕す。",furigana:"農家の人達は鋤で土を耕す。",romaji:"tagayasu",idText:"Para petani mengolah tanah dengan bajak."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"タガヤ＼ス"}}],explanations:[{id:"exp-1",grammarId:"gn2-00243",title:"Pola: 〜いかんで",formula:"N + いかんで",meaning:"tergantung pada ... / ditentukan oleh ... (formal/tertulis)",nuanceNotes:"〜いかんで menyatakan bahwa sesuatu ditentukan atau dipengaruhi oleh kondisi yang disebutkan. Digunakan dalam konteks formal untuk menyatakan ketergantungan langsung pada suatu faktor.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜いかんで",idText:"tergantung pada ... / ditentukan oleh ... (formal/tertulis)"}],examples:[{jp:"この交渉の成否は、あなたの判断いかんで決まる。",romaji:"",idText:"Berhasil atau tidaknya negosiasi ini ditentukan oleh keputusanmu."},{jp:"今後の努力いかんで、昇進の可能性もある。",romaji:"",idText:"Tergantung pada usahamu ke depan, ada kemungkinan promosi jabatan."}]},{id:"exp-2",grammarId:"gn2-00244",title:"Pola: 〜如何",formula:"N + 如何",meaning:"tergantung pada ... (sangat formal/tertulis)",nuanceNotes:"〜如何 adalah penulisan kanji dari いかん — digunakan dalam dokumen sangat formal seperti peraturan perusahaan, surat resmi, dan pengumuman pemerintah. Maknanya identik dengan いかんで dan いかんによっては, namun levelnya lebih tinggi.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜如何",idText:"tergantung pada ... (sangat formal/tertulis)"}],examples:[{jp:"応募の合否は書類審査の結果如何による。",romaji:"",idText:"Diterima atau tidaknya lamaran bergantung pada hasil seleksi dokumen."},{jp:"今後の対応如何では、法的措置も辞さない。",romaji:"",idText:"Tergantung penanganan ke depan, tindakan hukum pun tidak akan dihindari."}]},{id:"exp-3",grammarId:"gn2-00007",title:"Pola: 〜かねない",formula:"V-stem + かねない",meaning:"bisa jadi ... (hal negatif) / ada kemungkinan ...",nuanceNotes:"〜かねない mengungkapkan kemungkinan terjadinya sesuatu yang negatif atau tidak diinginkan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜かねない",idText:"bisa jadi ... (hal negatif) / ada kemungkinan ..."}],examples:[{jp:"こんな運転をしていたら、事故を起こしかねない。",romaji:"",idText:"Kalau mengemudi seperti ini, bisa jadi terjadi kecelakaan."},{jp:"放っておくと、もっと悪化しかねない。",romaji:"",idText:"Kalau dibiarkan, bisa makin parah."}]},{id:"exp-4",grammarId:"gn2-00008",title:"Pola: 〜かねる",formula:"V-stem + かねる",meaning:"tidak bisa (melakukan) ... / sulit untuk ...",nuanceNotes:"〜かねる menyatakan bahwa secara psikologis atau moral pembicara tidak dapat atau sulit untuk melakukan sesuatu.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜かねる",idText:"tidak bisa (melakukan) ... / sulit untuk ..."}],examples:[{jp:"その要求には応じかねます。",romaji:"",idText:"Kami sulit memenuhi permintaan tersebut."},{jp:"一人では決めかねます。",romaji:"",idText:"Saya tidak bisa memutuskan sendiri."}]},{id:"exp-5",grammarId:"gn2-00013",title:"Pola: 〜ばかりか",formula:"V/Adj plain / N + ばかりか",meaning:"tidak hanya ... bahkan ...",nuanceNotes:"〜ばかりか menambahkan informasi yang mengejutkan atau melebihi ekspektasi dari apa yang disebutkan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ばかりか",idText:"tidak hanya ... bahkan ..."}],examples:[{jp:"彼は歌うばかりか、踊ることもできる。",romaji:"",idText:"Tidak hanya menyanyi, dia bahkan bisa menari."},{jp:"宿題を忘れたばかりか、教科書まで忘れた。",romaji:"",idText:"Tidak hanya lupa PR, bahkan buku teksnya pun lupa."}]},{id:"exp-6",grammarId:"gn2-00017",title:"Pola: 〜わけにはいかない",formula:"V-dict / V-ない + わけにはいかない",meaning:"tidak mungkin (bisa) ... / tidak boleh ...",nuanceNotes:"〜わけにはいかない menyatakan bahwa secara sosial, moral, atau situasional seseorang tidak bisa melakukan sesuatu.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜わけにはいかない",idText:"tidak mungkin (bisa) ... / tidak boleh ..."}],examples:[{jp:"約束したから、行かないわけにはいかない。",romaji:"",idText:"Karena sudah berjanji, tidak mungkin tidak pergi."},{jp:"試験前なのに、遊んでいるわけにはいかない。",romaji:"",idText:"Menjelang ujian, tidak boleh bermain-main."}]},{id:"exp-7",grammarId:"gn2-00018",title:"Pola: 〜に違いない",formula:"V/Adj plain / N + に違いない",meaning:"pasti ... / tidak salah lagi ...",nuanceNotes:"〜に違いない menyatakan keyakinan kuat pembicara bahwa sesuatu pasti benar.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に違いない",idText:"pasti ... / tidak salah lagi ..."}],examples:[{jp:"彼が来ないに違いない。",romaji:"",idText:"Pasti dia tidak akan datang."},{jp:"この映画は面白いに違いない。",romaji:"",idText:"Film ini pasti menarik."}]},{id:"exp-8",grammarId:"gn2-00020",title:"Pola: 〜てならない",formula:"V-te / い-Adj-くて / な-Adj-で + ならない",meaning:"sangat ... / tidak tahan merasa ...",nuanceNotes:"〜てならない mengungkapkan perasaan yang sangat kuat dan alami (tidak bisa ditahan) dari dalam diri.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜てならない",idText:"sangat ... / tidak tahan merasa ..."}],examples:[{jp:"故郷が恋しくてならない。",romaji:"",idText:"Sangat merindukan kampung halaman."},{jp:"彼のことが心配でならない。",romaji:"",idText:"Sangat khawatir akan dia."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "共感 (きょうかん)" dalam pembinaan sosial?',sentencePrompt:'Istilah "共感 (きょうかん) を 寄【よ】せる" bermakna:',options:["Merasakan simpati dan memahami perasaan orang lain secara mendalam","Mengirimkan barang pesanan melalui kurir ekspres","Memaksa orang lain mengikuti pandangan sepihak kita","Mengambil alih kepemilikan aset secara ilegal"],correctAnswer:"Merasakan simpati dan memahami perasaan orang lain secara mendalam",explanation:'"共感 (きょうかん)" bermakna resonansi perasaan, empati, dan ikut merasakan apa yang dirasakan pihak lain.',diagnosticFeedback:{"Mengirimkan barang pesanan melalui kurir ekspres":"Salah: Pengiriman ekspres adalah 速達 (sokutatsu) atau 宅急便 (takkyuubin).","Memaksa orang lain mengikuti pandangan sepihak kita":"Salah: Pemaksaan pandangan adalah 意見の押し付け (iken no oshitsuke).","Mengambil alih kepemilikan aset secara ilegal":"Salah: Pengambilalihan ilegal adalah 横領 (ouryou) atau 略奪 (ryakudatsu)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat dengan pola yang menyatakan desakan rasa batin yang mendalam:",sentencePrompt:"故郷【こきょう】の 家族【かぞく】が 元気【げんき】で 暮【く】らしているか、心配【しんぱい】で [　　]。",options:["ならない","たまらない","いられない","いかない"],correctAnswer:"ならない",explanation:"心配でならない menyatakan dorongan rasa cemas batiniah spontan yang tak terbendung dari lubuk hati.",diagnosticFeedback:{たまらない:"Kekeliruan Nuansa: 〜たまらない lebih lazim untuk dorongan hasrat subjektif atau fisik mendesak, sedangkan untuk kecemasan batin yang mendalam, 〜ならない adalah bentuk paling elegan.",いられない:"Kekeliruan Pola: 〜てはいられない menyatakan tidak bisa terus-terusan berdiam diri.",いかない:"Kekeliruan Pola: 〜わけにはいかない menyatakan batasan norma moral/sosial, bukan ungkapan perasaan."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Kaidah Tanggung Jawab Moral): Manakah kalimat yang menggunakan 〜わけにはいかない secara tepat?",sentencePrompt:"Pilihlah kalimat dengan penggunaan 〜わけにはいかない yang gramatikal dan berbobot moral:",options:["明日【あした】は 大事【だいじ】な 試験【しけん】が あるので、今夜【こんや】は 遊【あそ】んでいる わけには いかない。","今日【きょう】は 日曜日【にちようび】なので、早起【はやお】きする わけには いかない。","お腹【なか】が 空【す】いたので、ご飯【はん】を 食【た】べる わけには いかない。","天気【てんき】が いいので、散歩【さんぽ】に 行【い】く わけには いかない。"],correctAnswer:"明日【あした】は 大事【だいじ】な 試験【しけん】が あるので、今夜【こんや】は 遊【あそ】んでいる わけには いかない。",explanation:"〜わけにはいかない digunakan ketika ada alasan kewajiban moral, tanggung jawab, atau situasi sosial yang melarang kita bersikap santai.",diagnosticFeedback:{"今日【きょう】は 日曜日【にちようび】なので、早起【はやお】きする わけには いかない。":"Kekeliruan Logika: Hari Minggu boleh saja bangun pagi, tidak ada pelanggaran moral yang melarangnya.","お腹【なか】が 空【す】いたので、ご飯【はん】を 食【た】べる わけには いかない。":"Logika Rusak: Bila lapar, sewajarnya makan, bukan dilarang oleh norma moral.","天気【てんき】が いいので、散歩【さんぽ】に 行【い】く わけには いかない。":"Logika Terbalik: Cuaca cerah justru mendukung jalan-jalan, bukan menjadi kendala etis."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun frasa-frasa berikut menjadi kalimat penegasan tekad yang benar:",sentencePrompt:"Susunlah frasa-frasa berikut:",options:["先輩【せんぱい】として 私【わたし】たちが 弱気【よわき】に なる わけには いかない","弱気【よわき】に なる 先輩【せんぱい】として 私【わたし】たちが わけには いかない","私【わたし】たちが わけには いかない 先輩【せんぱい】として 弱気【よわき】に なる","先輩【せんぱい】として わけには いかない 私【わたし】たちが 弱気【よわき】に なる"],correctAnswer:"先輩【せんぱい】として 私【わたし】たちが 弱気【よわき】に なる わけには いかない",explanation:"Urutan baku: Kedudukan peran (先輩として) + subjek (私たちが) + predikat kondisi (弱気になる) + penutup moral (わけにはいかない).",diagnosticFeedback:{"弱気【よわき】に なる 先輩【せんぱい】として 私【わたし】たちが わけには いかない":"Kekeliruan Urutan: Predikat diletakkan di depan sebelum frasa kedudukan sosial.","私【わたし】たちが わけには いかない 先輩【せんぱい】として 弱気【よわき】に なる":'Kekeliruan Penutup: Pola "wake ni wa ikanai" wajib berada di akhir kalimat penutup.',"先輩【せんぱい】として わけには いかない 私【わたし】たちが 弱気【よわき】に なる":"Kekeliruan Sintaksis: Pola penutup memotong di tengah kalimat."},tokens:["先輩【せんぱい】として","私【わたし】たちが","弱気【よわき】に なる","わけには いかない"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Sikap Kepemimpinan): Saat Sakura mengingatkan: 「先輩として 私たちが 弱気になる わけにはいきませんね」, apa komitmen terbaik Anda?",sentencePrompt:"Pilihlah respons yang mencerminkan keteguhan integritas kepemimpinan:",options:["おっしゃる 通【とお】りです！ 頼【たよ】れる 先輩【せんぱい】として、全力【ぜんりょく】で 彼【かれ】らの 生活【せいかつ】と 学【まな】びを 支【ささ】えてまいります。","もう 嫌【いや】です。自分【じぶん】の ことだけで 精一杯【せいいっぱい】なので、後輩【こうはい】の 面倒【めんどう】なんか 見【み】たくありません。","さくらさん、会社【かいしゃ】から 特別【とくべつ】な 手当【てあて】が 出【で】ないなら、何【なに】も 手伝【てつだ】いませんよ。","実習【じっしゅう】生【せい】なんて 誰【だれ】でも できる 仕事【しごと】ですから、放置【ほうち】しておけば 勝手【かって】に 育【そだ】ちます。"],correctAnswer:"おっしゃる 通【とお】りです！ 頼【たよ】れる 先輩【せんぱい】として、全力【ぜんりょく】で 彼【かれ】らの 生活【せいかつ】と 学【まな】びを 支【ささ】えてまいります。",explanation:"Menunjukkan integritas teladan sebagai senior (Sempai) dengan komitmen penuh (Zenryoku de).",diagnosticFeedback:{"もう 嫌【いや】です。自分【じぶん】の ことだけで 精一杯【せいいっぱい】なので、後輩【こうはい】の 面倒【めんどう】なんか 見【み】たくありません。":"Egois: Menolak tanggung jawab membimbing junior merusak kekompakan tim.","さくらさん、会社【かいしゃ】から 特別【とくべつ】な 手当【てあて】が 出【で】ないなら、何【なに】も 手伝【てつだ】いませんよ。":"Materialistis: Menuntut tunjangan uang saat dimintai dukungan moril sangat tidak etis.","実習【じっしゅう】生【せい】なんて 誰【だれ】でも できる 仕事【しごと】ですから、放置【ほうち】しておけば 勝手【かって】に 育【そだ】ちます。":"Abai & Lalai: Mengabaikan junior di masa adaptasi melanggar prinsip pembinaan aman dan bermartabat."}}],can_do_challenge:{statement:"Bisa mengutarakan rasa empati tulus terhadap rekan kerja yang menghadapi kesulitan, serta menegaskan tekad pantang menyerah.",situation:"Teras Gedung Pelatihan Shizuoka, pukul 16.45",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜いかんで!",modelAnswer:"本当【ほんとう】に そうですね。私【わたし】も 来日【らいにち】当初【とうしょ】は 不安【ふあん】でしたから、彼【かれ】らの 気持【きも】ちが 分【わ】かって なりません。",modelAnswerId:"Benar sekali. Karena saya pun dulu saat awal tiba di Jepang merasa cemas, saya sangat bisa merasakan apa yang ada di hati mereka.",culturalEtiquette:"Mengakui rasa cemas batin (shimpai de naranai) kepada mentor menunjukkan kejujuran emosional, namun harus diimbangi tekad tidak boleh menyerah (akirameru wake ni wa ikanai).",skillUnlocked:["Menguasai formulasi pola 〜いかんで","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Gejolak Emosi, Dorongan Spontan & Resonansi Batin"]},pocket_summary:{keyFormula:"V-te / A-kute / Na-de + ならない (sangat terasa hingga tak tertahankan), V-dict + わけにはいかない (secara etis/tanggung jawab tidak mungkin melakukan...)",coreWords:["共感【きょうかん】 (simpati; tanggapan)","尊重【そんちょう】 (menghormati, menghargai, menjunjung tinggi)","心配【しんぱい】する (khawatir, cemas, mengkhawatirkan)","責任【せきにん】 (tanggung jawab)"],coreWarning:"Jangan gunakan 〜てならない untuk kondisi fisik murni sesaat (seperti kebelet buang air kecil). Untuk kondisi fisik mendesak, gunakan 〜てたまらない.",quickDialogue:"A: ブディさん、新【あたら】しく 来【き】た 実習【じ... → B: 本当【ほんとう】に そうですね。私【わたし】も 来..."}}},r={"les-n2-u06-01":{pedagogical_framework:{what:{summary:"Menguasai ekspresi kepatuhan regulasi institusi: 〜ことになっている (telah menjadi aturan/regulasi baku) dan keterpaksaan rasional: 〜ざるを得ない (terpaksa harus dilakukan demi keselamatan/kepatuhan).",canDo:"Bisa menjelaskan ketentuan SOP kepatuhan data dan mengambil keputusan darurat yang tak terhindarkan dalam audit perusahaan.",targetPatterns:["V-dict / V-nai + ことになっている (telah ditetapkan sebagai regulasi/aturan umum)","V-nai + ざるを得ない (terpaksa harus ... tiada pilihan lain)"],coreVocabSample:["規約【きやく】","遵守【じゅんしゅ】","監査【かんさ】","保護【ほご】","規則【きそく】","承認【しょうにん】する","対応【たいおう】","決定【けってい】"]},sensei_context:{sceneIntro:"Kantor cabang Tokyo saat audit kepatuhan regulasi keselamatan kerja dan perlindungan data. Nakamura (Manajer SDM & Regulasi) meninjau protokol keamanan informasi bersama Budi.",dailyMission:'Gunakan "koto ni natte iru" untuk menegaskan regulasi baku dan "zaru o enai" saat menjelaskan tindakan perbaikan mendesak.',whyOrder:"Di level N2, pembelajar harus mampu membedakan aturan objektif eksternal (koto ni natte iru) dari komitmen personal (koto ni shite iru) dan mengekspresikan keputusan rasional yang tak terelakkan."},cultural_notes:{title:"Kepatuhan Regulasi (コンプライアンス遵守) dalam Budaya Korporat Jepang",etiquette:'Menjelaskan aturan dengan frasa "koto ni natte orimasu" terdengar objektif dan profesional, tidak terkesan memaksakan kehendak pribadi kepada lawan bicara.',taboos:'Jangan melanggar ketetapan "koto ni natte iru" tanpa otorisasi tertulis dari bagian kepatuhan hukum (Houmubu).'},pronunciation_tips:{title:'Artikulasi "Zaru o enai" yang Mengalir',moraNote:'Frasa "za-ru-o-e-na-i" memiliki 6 mora. Lafalkan secara berkesinambungan tanpa jeda tersendat di tengah mora o.',soundTip:'Pada "koto ni natte iru", jaga nada heiban datar tanpa lonjakan aksen mendadak.'},common_pitfalls:[{title:"Tertukar Antara 〜ことになっている (Aturan Institusi) vs 〜ことにしている (Disiplin Pribadi)",caseScenario:"Ingin mengatakan bahwa kantor mewajibkan memakai kartu ID.",pitfallWarning:"社員証【しゃいんしょう】を つける ことに しています。 (Artinya disiplin pribadi, bukan aturan kantor)",rightSolution:"社員証【しゃいんしょう】を つける ことに なっています。 (Tepat: aturan baku perusahaan)",explanation:"〜ことになっている menandakan aturan, jadwal, atau hukum yang ditentukan pihak luar, sedangkan 〜ことにしている adalah kebiasaan pribadi."},{title:"Salah Konjugasi pada Verba Suru untuk 〜ざるを得ない",caseScenario:"Mengonjugasikan suru menjadi shizaru o enai.",pitfallWarning:"延期【えんき】しざるを えない。 (Bentuk tidak baku)",rightSolution:"延期【えんき】せざるを えない。 (Tepat: konjugasi khusus suru -> se-zaru)",explanation:"Verba suru memiliki bentuk konjugasi irregular khusus sebelum ざるを得ない, yaitu せざるを得ない (bukan shizaru)."}],who_and_when:{situational_context:"Audit kepatuhan tahunan, penjelasan aturan kerja kepada karyawan baru, dan perumusan mitigasi insiden.",social_relations:"Komunikasi formal manajerial antara Manajer SDM (Nakamura) dan staf operasional (Budi).",when_not_to_use:'Jangan gunakan "zaru o enai" untuk hal-hal yang dilakukan dengan sukacita atau atas kemauan sendiri.'},scenario:{title:"Audit Keamanan Data Server Tokyo",setting:"Ruang Rapat Audit Kepatuhan, Lantai 12 Marunouchi, pukul 09.30",narrative:"Nakamura menginspeksi kepatuhan enkripsi basis data pelanggan pasca pembaruan regulasi privasi."}},dialogue:[{id:"d1",speaker:"Nakamura",speakerRole:"Manajer SDM & Regulasi",avatar:"👩‍💼",jp:"ブディさん、新【あたら】しい セキュリティ規約【きやく】では、顧客【こきゃく】データは 全【すべ】て 暗号【あんごう】化【か】して 保管【ほかん】する ことに なっていますよね？",furigana:"ブディさん、新しい セキュリティ規約では、顧客データは 全て 暗号化して 保管する ことに なっていますよね？",romaji:"Budi-san, atarashii sekyuriti kiyaku dewa, kokyaku deeta wa subete angouka shite hokan suru koto ni natte imasu yo ne?",idText:"Budi, berdasarkan regulasi keamanan baru, semua data pelanggan telah ditetapkan untuk disimpan dalam bentuk terenkripsi, bukan?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、中村【なかむら】さん！ 規約【きやく】の 通【とお】り、全【すべ】ての サーバーで 自動【じどう】暗号【あんごう】化【か】を 完了【かんりょう】する ことに なっております。",furigana:"はい、中村さん！ 規約の 通り、全ての サーバーで 自動暗号化を 完了する ことに なっております。",romaji:"Hai, Nakamura-san! Kiyaku no toori, subete no saabaa de jidou angouka o kanryou suru koto ni natte orimasu.",idText:"Ya, Nakamura-san! Sesuai regulasi, telah ditetapkan bahwa enkripsi otomatis diselesaikan di semua server."},{id:"d3",speaker:"Nakamura",speakerRole:"Manajer SDM & Regulasi",avatar:"👩‍💼",jp:"旧型【きゅうがた】サーバーの 移行【いこう】が 遅【おく】れた 場合【ばあい】は、一時的【いちじてき】に システムを 停止【ていし】せざるを 得【え】ませんね。",furigana:"旧型サーバーの 移行が 遅れた 場合は、一時的に システムを 停止せざるを 得ませんね。",romaji:"Kyuugata saabaa no ikou ga okureta baai wa, ichijiteki ni shisutemu o teishi sezaru o emasen ne.",idText:"Jika migrasi server model lama terlambat, maka mau tidak mau kita terpaksa harus menghentikan sistem untuk sementara ya."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい。停止【ていし】という 事態【じたい】を 避【さ】けるため、今夜【こんや】のうちに 全【すべ】ての バックアップと 移行【いこう】を 完了【かんりょう】させます！",furigana:"はい。停止という 事態を 避けるため、今夜のうちに 全ての バックアップと 移行を 完了させます！",romaji:"Hai. Teishi to iu jitai o sakeru tame, konya no uchi ni subete no bakkuappu to ikou o kanryou sasemasu!",idText:"Ya. Demi menghindari situasi penghentian sistem, saya akan menuntaskan semua pencadangan dan migrasi malam ini juga!"}],vocab_breakdown:[{id:"vg-n2-01528",word:"浸ける",reading:"つける",romaji:"tsukeru",meaning:"mencelupkan ke dalam",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 浸ける / 〜に関する 浸ける dalam wacana profesional.",exampleSentence:{jp:"彼はスプーンをスープの中につけた。",furigana:"彼はスプーンをスープの中につけた。",romaji:"tsukeru",idText:"Dia mencelupkan sendoknya ke dalam sup."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"ツケル￣"}},{id:"vg-n2-01529",word:"着ける",reading:"つける",romaji:"tsukeru",meaning:"lampirkan",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 着ける / 〜に関する 着ける dalam wacana profesional.",exampleSentence:{jp:"おまえの上着は私の勘定につけておきなさい。",furigana:"おまえの上着は私の勘定につけておきなさい。",romaji:"tsukeru",idText:"Letakkan mantelmu di akunku."},pitch:{pattern:2,category:"nakadaka",mora_count:3,downstep_mora:2,contour:"ツケ＼ル"}},{id:"vg-n2-01530",word:"伝わる",reading:"つたわる",romaji:"tsutawaru",meaning:"diturunkan",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 伝わる / 〜に関する 伝わる dalam wacana profesional.",exampleSentence:{jp:"光は音よりはるかに早く伝わる。",furigana:"光は音よりはるかに早く伝わる。",romaji:"tsutawaru",idText:"Light travels much faster than sound."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ツタワル￣"}},{id:"vg-n2-01531",word:"突っ込む",reading:"つっこむ",romaji:"tsukkomu",meaning:"terjun ke dalam",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 突っ込む / 〜に関する 突っ込む dalam wacana profesional.",exampleSentence:{jp:"人の問題に鼻を突っ込むのはよしてくれよ。",furigana:"人の問題に鼻を突っ込むのはよしてくれよ。",romaji:"tsukkomu",idText:"Berhenti mencampuri urusan orang lain."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"ツッコ＼ム"}},{id:"vg-n2-01532",word:"努める",reading:"つとめる",romaji:"tsutomeru",meaning:"melayani",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 努める / 〜に関する 努める dalam wacana profesional.",exampleSentence:{jp:"お手伝いさんたちは主人の命令を実行しようと努めた。",furigana:"お手伝いさんたちは主人の命令を実行しようと努めた。",romaji:"tsutomeru",idText:"Para pelayan berusaha melaksanakan perintah tuannya."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"ツトメ＼ル"}},{id:"vg-n2-01533",word:"務める",reading:"つとめる",romaji:"tsutomeru",meaning:"melayani",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 務める / 〜に関する 務める dalam wacana profesional.",exampleSentence:{jp:"彼女は私たちの団体では重要な役を務めている。",furigana:"彼女は私たちの団体では重要な役を務めている。",romaji:"tsutomeru",idText:"Dia playing an important role in our organization."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"ツトメ＼ル"}},{id:"vg-n2-01536",word:"繋がる",reading:"つながる",romaji:"tsunagaru",meaning:"diikat menjadi satu",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 繋がる / 〜に関する 繋がる dalam wacana profesional.",exampleSentence:{jp:"私たちは血がつながっている。",furigana:"私たちは血がつながっている。",romaji:"tsunagaru",idText:"Kami related by blood."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ツナガル￣"}},{id:"vg-n2-01537",word:"繋げる",reading:"つなげる",romaji:"tsunageru",meaning:"menghubungkan",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 繋げる / 〜に関する 繋げる dalam wacana profesional.",exampleSentence:{jp:"私のテープレコーダーは君のアンプにもつなげられる。",furigana:"私のテープレコーダーは君のアンプにもつなげられる。",romaji:"tsunageru",idText:"Tape recorder saya kompatibel dengan amplifier Anda."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ツナゲル￣"}}],explanations:[{id:"exp-1",grammarId:"gn2-00022",title:"Pola: 〜ことになっている",formula:"V-dict / V-ない + ことになっている",meaning:"sudah ditetapkan bahwa ... / seharusnya ...",nuanceNotes:"〜ことになっている menyatakan aturan, ketentuan, atau jadwal yang sudah ditetapkan dari luar.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ことになっている",idText:"sudah ditetapkan bahwa ... / seharusnya ..."}],examples:[{jp:"会議は9時に始まることになっている。",romaji:"",idText:"Rapat sudah ditetapkan mulai pukul 9."},{jp:"社内ではスーツを着ることになっている。",romaji:"",idText:"Di kantor, sudah menjadi aturan untuk memakai setelan."}]},{id:"exp-2",grammarId:"gn2-00029",title:"Pola: 〜ざるを得ない",formula:"V-ない-stem + ざるを得ない（例外: する→せざるを得ない）",meaning:"terpaksa ... / tidak bisa tidak ...",nuanceNotes:"〜ざるを得ない menyatakan bahwa pembicara terpaksa melakukan sesuatu karena tidak ada pilihan lain.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ざるを得ない",idText:"terpaksa ... / tidak bisa tidak ..."}],examples:[{jp:"事情があって、断らざるを得なかった。",romaji:"",idText:"Ada alasan, terpaksa harus menolak."},{jp:"証拠があるから、認めざるを得ない。",romaji:"",idText:"Karena ada bukti, terpaksa harus mengakui."}]},{id:"exp-3",grammarId:"gn2-00043",title:"Pola: 〜によると / 〜によれば",formula:"N (sumber) + によると / によれば + [informasi] + そうだ / とのことだ",meaning:"menurut ... (informasi dari sumber luar)",nuanceNotes:"〜によると digunakan untuk menyampaikan informasi yang bersumber dari luar — berita, laporan, atau perkataan orang lain. Kalimat sering diakhiri dengan そうだ atau とのことだ.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜によると / 〜によれば",idText:"menurut ... (informasi dari sumber luar)"}],examples:[{jp:"天気予報によると、明日は雨らしい。",romaji:"",idText:"Menurut prakiraan cuaca, besok sepertinya akan hujan."},{jp:"彼女の話によると、会議は中止になったそうだ。",romaji:"",idText:"Menurut ceritanya, rapat katanya dibatalkan."},{jp:"報告書によれば、売上は増加している。",romaji:"",idText:"Menurut laporan, penjualan sedang meningkat."}]},{id:"exp-4",grammarId:"gn2-00055",title:"Pola: 〜次第だ / 〜次第です",formula:"N + 次第だ / [penjelasan] + という次第だ",meaning:"sepenuhnya tergantung pada ... / itulah alasannya ...",nuanceNotes:"〜次第だ memiliki dua makna: (1) menyatakan bahwa sesuatu sepenuhnya bergantung pada faktor tertentu (akhir kalimat); (2) menjelaskan kronologi atau alasan keadaan saat ini.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜次第だ / 〜次第です",idText:"sepenuhnya tergantung pada ... / itulah alasannya ..."}],examples:[{jp:"あとはあなた次第だ。",romaji:"",idText:"Sisanya sepenuhnya tergantung padamu."},{jp:"成功するかどうかは努力次第だ。",romaji:"",idText:"Berhasil atau tidak sepenuhnya tergantung pada usaha."},{jp:"ご連絡が遅くなり、申し訳ないという次第です。",romaji:"",idText:"Itulah mengapa kami terlambat menghubungi Anda, kami mohon maaf."}]},{id:"exp-5",grammarId:"gn2-00061",title:"Pola: 〜ざるを得ない",formula:"V-nai-stem + ざるを得ない (する → せざるを得ない)",meaning:"tidak bisa tidak ... / terpaksa ...",nuanceNotes:"〜ざるを得ない mengungkapkan bahwa seseorang terpaksa melakukan sesuatu karena tidak ada pilihan lain — bukan karena keinginan sendiri.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ざるを得ない",idText:"tidak bisa tidak ... / terpaksa ..."}],examples:[{jp:"電車が止まったので、タクシーで行かざるを得なかった。",romaji:"",idText:"Karena kereta berhenti, terpaksa harus naik taksi."},{jp:"体調が悪くて、会議を欠席せざるを得ない。",romaji:"",idText:"Badan tidak enak, terpaksa tidak hadir rapat."},{jp:"証拠を見せられては、認めざるを得ない。",romaji:"",idText:"Setelah diberi bukti, terpaksa harus mengakui."}]},{id:"exp-6",grammarId:"gn2-00062",title:"Pola: 〜わけにはいかない",formula:"V-dict / V-nai + わけにはいかない",meaning:"tidak bisa melakukan ... / tidak mungkin melakukan ... (hambatan sosial atau moral)",nuanceNotes:"〜わけにはいかない menyatakan bahwa sesuatu tidak bisa dilakukan karena ada hambatan sosial, moral, atau situasional — bukan karena ketidakmampuan fisik.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜わけにはいかない",idText:"tidak bisa melakukan ... / tidak mungkin melakukan ... (hambatan sosial atau moral)"}],examples:[{jp:"みんなが頑張っているのに、私だけ休むわけにはいかない。",romaji:"",idText:"Padahal semua sedang kerja keras, masa saya sendiri yang istirahat."},{jp:"約束したから、断るわけにはいかない。",romaji:"",idText:"Karena sudah berjanji, tidak bisa menolak."},{jp:"ここで諦めるわけにはいかない。",romaji:"",idText:"Di titik ini, tidak mungkin menyerah."}]},{id:"exp-7",grammarId:"gn2-00063",title:"Pola: 〜わけがない",formula:"V-plain / Adj-plain / N + な + わけがない",meaning:"tidak mungkin ... (berdasarkan logika — nada heran)",nuanceNotes:"〜わけがない digunakan untuk menyatakan bahwa sesuatu mustahil terjadi, berdasarkan penalaran logis pembicara. Sering membawa nuansa kaget atau tidak percaya.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜わけがない",idText:"tidak mungkin ... (berdasarkan logika — nada heran)"}],examples:[{jp:"彼がそんなことをするわけがない。",romaji:"",idText:"Tidak mungkin dia melakukan hal seperti itu."},{jp:"昨日会ったばかりなのに、忘れたわけがない。",romaji:"",idText:"Baru ketemu kemarin, tidak mungkin sudah lupa."},{jp:"こんな難しい問題、小学生に解けるわけがない。",romaji:"",idText:"Soal sesulit ini, tidak mungkin bisa diselesaikan anak SD."}]},{id:"exp-8",grammarId:"gn2-00064",title:"Pola: 〜わけだ",formula:"V-plain / Adj-plain / N + な + わけだ",meaning:"jadi memang ... / pantas saja ... / berarti ...",nuanceNotes:'〜わけだ mengungkapkan kesimpulan logis dari informasi yang baru saja diketahui — "jadi itulah alasannya" atau "pantas saja". Pembicara merasa pemahamannya terkonfirmasi.',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜わけだ",idText:"jadi memang ... / pantas saja ... / berarti ..."}],examples:[{jp:"彼は10年間日本に住んでいた。日本語が上手なわけだ。",romaji:"",idText:"Dia sudah tinggal 10 tahun di Jepang. Pantas saja bahasa Jepangnya bagus."},{jp:"セールだったから、混んでいたわけだ。",romaji:"",idText:"Karena lagi sale, pantas saja ramai."},{jp:"そういう事情があったから、断ったわけだ。",romaji:"",idText:"Ada alasan seperti itu, jadi memang dia menolak."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "規約 (きやく)" dalam tata kelola perusahaan?',sentencePrompt:'Istilah "社内【しゃない】規約【きやく】" bermakna:',options:["Ketentuan atau anggaran dasar regulasi resmi perusahaan","Daftar menu makan siang di kantin karyawan","Tiket undian berhadiah akhir tahun kantor","Jadwal libur cuti bersama musim panas"],correctAnswer:"Ketentuan atau anggaran dasar regulasi resmi perusahaan",explanation:'"規約 (きやく)" bermakna anggaran dasar, perjanjian regulasi, atau ketentuan formal yang mengikat.',diagnosticFeedback:{"Daftar menu makan siang di kantin karyawan":"Salah: Menu makanan adalah 献立 (kondate) atau メニュー.","Tiket undian berhadiah akhir tahun kantor":"Salah: Undian adalah 抽選 (chuusen) atau 福引 (fukubiki).","Jadwal libur cuti bersama musim panas":"Salah: Jadwal libur adalah 夏季休暇日程 (kaki kyuuka nittei)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat dengan pola keterpaksaan rasional yang tidak dapat dihindari:",sentencePrompt:"台風【たいふう】の 直撃【ちょくげき】により、明日【あした】の 工場【こうじょう】見学【けんがく】は 中止【ちゅうし】[　　]。",options:["せざるを 得【え】ない","しざるを 得【え】ない","する ことに している","した 上【うえ】で ある"],correctAnswer:"せざるを 得【え】ない",explanation:"Untuk verba 中止する, bentuk baku keterpaksaan adalah 中止せざるを得ない (terpaksa harus dibatalkan).",diagnosticFeedback:{"しざるを 得【え】ない":"Kekeliruan Morfologi: Verba suru menjadi se-zaru (bukan shi-zaru).","する ことに している":"Kekeliruan Subjek: 〜ことにしている berarti keputusan santai pribadi, bukan pembatalan darurat bencana alam.","した 上【うえ】で ある":'Kekeliruan Pola: 〜上で bermakna "setelah menuntaskan prasyarat", tidak pas untuk kalimat deklarasi pembatalan.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Kaidah Aturan Institusi): Manakah kalimat yang menggunakan 〜ことになっている secara tepat?",sentencePrompt:"Pilihlah kalimat yang menggunakan 〜ことになっている dengan makna aturan/jadwal baku:",options:["この 部屋【へや】では、靴【くつ】を 脱【ぬ】ぐ ことに なっています。","私【わたし】は 毎朝【まいあさ】 走【はし】る ことに なっています。","昨日【きのう】 買【か】い物【もの】に 行【い】く ことに なっていました。","リンゴが 赤【あか】く なる ことに なっています。"],correctAnswer:"この 部屋【へや】では、靴【くつ】を 脱【ぬ】ぐ ことに なっています。",explanation:"Melepas sepatu di ruangan tertentu adalah aturan/norma institusional objektif, sangat tepat memakai 〜ことになっている.",diagnosticFeedback:{"私【わたし】は 毎朝【まいあさ】 走【はし】る ことに なっています。":"Kekeliruan Subjek: Lari pagi adalah kebiasaan pribadi, tepatnya 走ることにしている.","昨日【きのう】 買【か】い物【もの】に 行【い】く ことに なっていました。":"Kekeliruan Waktu: Rencana belanja kasual masa lalu tidak pas memakai pola aturan institusional.","リンゴが 赤【あか】く なる ことに なっています。":"Kekeliruan Alami: Fenomena pematangan buah adalah proses biologis alamiah, bukan regulasi manusia."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat penegasan kepatuhan:",sentencePrompt:"Susunlah frasa-frasa berikut:",options:["顧客【こきゃく】データは 全【すべ】て 暗号【あんごう】化【か】して 保管【ほかん】する ことに なっている","暗号【あんごう】化【か】して 顧客【こきゃく】データは 全【すべ】て 保管【ほかん】する ことに なっている","保管【ほかん】する ことに なっている 顧客【こきゃく】データは 全【すべ】て 暗号【あんごう】化【か】して","顧客【こきゃく】データは ことに なっている 全【すべ】て 暗号【あんごう】化【か】して 保管【ほかん】する"],correctAnswer:"顧客【こきゃく】データは 全【すべ】て 暗号【あんごう】化【か】して 保管【ほかん】する ことに なっている",explanation:"Urutan baku: Topik (顧客データは) + kuantor (全て) + verba sambung (暗号化して) + verba inti (保管する) + pola aturan (ことになっている).",diagnosticFeedback:{"暗号【あんごう】化【か】して 顧客【こきゃく】データは 全【すべ】て 保管【ほかん】する ことに なっている":"Kekeliruan Topik: Frasa sambung mendahului topik penjelas kalimat.","保管【ほかん】する ことに なっている 顧客【こきゃく】データは 全【すべ】て 暗号【あんごう】化【か】して":"Kekeliruan Penutup: Predikat diletakkan di awal dan menggantung di akhir frasa te.","顧客【こきゃく】データは ことに なっている 全【すべ】て 暗号【あんごう】化【か】して 保管【ほかん】する":"Struktur Terputus: Pola penutup memotong di tengah sebelum verba utama."},tokens:["顧客【こきゃく】データは","全【すべ】て 暗号【あんごう】化【か】して","保管【ほかん】する","ことに なっている"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Sikap Proaktif Audit): Saat Nakamura menyatakan: 「旧型サーバーの 移行が 遅れた 場合は、一時的に システムを 停止せざるを 得ませんね」, apa respons terbaik Anda?",sentencePrompt:"Pilihlah tanggapan profesional yang menunjukkan komitmen mitigasi proaktif:",options:["はい。停止【ていし】という 事態【じたい】を 避【さ】けるため、今夜【こんや】のうちに 全【すべ】ての バックアップと 移行【いこう】を 完了【かんりょう】させます！","システムが 止【と】まっても 私【わたし】には 関係【かんけい】ないので、好【す】きに 止【と】めてください。","中村【なかむら】さん、セキュリティ規約【きやく】なんて 厳【きび】しすぎて バカバカしいですよ。","サーバーなんて 壊【こわ】れたら 壊【こわ】れたで、新【あたら】しいのを 買【か】えば いいじゃないですか。"],correctAnswer:"はい。停止【ていし】という 事態【じたい】を 避【さ】けるため、今夜【こんや】のうちに 全【すべ】ての バックアップと 移行【いこう】を 完了【かんりょう】させます！",explanation:"Menunjukkan inisiatif mencegah kerugian operasional dan dedikasi menjaga ketersediaan sistem.",diagnosticFeedback:{"システムが 止【と】まっても 私【わたし】には 関係【かんけい】ないので、好【す】きに 止【と】めてください。":"Abai & Tidak Bertanggung Jawab: Sikap masa bodoh terhadap kelangsungan sistem membahayakan operasional perusahaan.","中村【なかむら】さん、セキュリティ規約【きやく】なんて 厳【きび】しすぎて バカバカしいですよ。":"Menghina Regulasi: Menyebut regulasi keamanan konyol adalah pelanggaran berat etika kerja.","サーバーなんて 壊【こわ】れたら 壊【こわ】れたで、新【あたら】しいのを 買【か】えば いいじゃないですか。":"Meremehkan Aset: Mengabaikan integritas data pelanggan dan menganggap enteng risiko sistem."}}],can_do_challenge:{statement:"Bisa menjelaskan ketentuan SOP kepatuhan data dan mengambil keputusan darurat yang tak terhindarkan dalam audit perusahaan.",situation:"Ruang Rapat Audit Kepatuhan, Lantai 12 Marunouchi, pukul 09.30",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ことになっている!",modelAnswer:"はい、中村【なかむら】さん！ 規約【きやく】の 通【とお】り、全【すべ】ての サーバーで 自動【じどう】暗号【あんごう】化【か】を 完了【かんりょう】する ことに なっております。",modelAnswerId:"Ya, Nakamura-san! Sesuai regulasi, telah ditetapkan bahwa enkripsi otomatis diselesaikan di semua server.",culturalEtiquette:'Menjelaskan aturan dengan frasa "koto ni natte orimasu" terdengar objektif dan profesional, tidak terkesan memaksakan kehendak pribadi kepada lawan bicara.',skillUnlocked:["Menguasai formulasi pola 〜ことになっている","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Keharusan Normatif, Keterpaksaan Logis & Aturan Bersama"]},pocket_summary:{keyFormula:"V-dict / V-nai + ことになっている (telah ditetapkan sebagai regulasi/aturan umum), V-nai + ざるを得ない (terpaksa harus ... tiada pilihan lain)",coreWords:["規約【きやく】 (agreement; rules)","遵守【じゅんしゅ】","監査【かんさ】","保護【ほご】 (care; protection)"],coreWarning:'Jangan melanggar ketetapan "koto ni natte iru" tanpa otorisasi tertulis dari bagian kepatuhan hukum (Houmubu).',quickDialogue:"A: ブディさん、新【あたら】しい セキュリティ規約【き... → B: はい、中村【なかむら】さん！ 規約【きやく】の 通..."}},"les-n2-u06-02":{pedagogical_framework:{what:{summary:"Menguasai pelaporan berbasis sumber resmi: 〜によると / 〜によれば (menurut data/laporan resmi) dan ketergantungan kondisi: 〜次第だ / 〜次第です (semuanya bergantung pada...).",canDo:"Bisa mengutip temuan hasil audit ketenagakerjaan dan menjelaskan faktor penentu keberhasilan sertifikasi mutu.",targetPatterns:["N + によると / によれば (menurut sumber ...)","N + 次第だ / 次第で (tergantung pada faktor ...)"],coreVocabSample:["監査【かんさ】","報告書【ほうこくしょ】","結果【けっか】","評価【ひょうか】する","基準【きじゅん】","審査【しんさ】","体制【たいせい】","努力【どりょく】"]},sensei_context:{sceneIntro:"Ruang briefing audit Marunouchi. Nakamura membedah draf laporan sementara dari inspektorat kementerian ketenagakerjaan bersama Budi.",dailyMission:'Kutip temuan audit dengan "chousa kekka ni yoruto" dan tegaskan faktor penentu dengan "korekara no taiou shidai desu".',whyOrder:"Pola ~ni yoruto memperkuat kredibilitas argumentasi dengan menyandarkannya pada fakta empiris, sementara ~shidai da menegaskan bahwa masa depan ditentukan oleh tindakan nyata."},cultural_notes:{title:"Pelaporan Berbasis Bukti (エビデンスに基づく報告) dan Ketergantungan Hasil",etiquette:"Menyandarkan laporan pada sumber formal (chousa ni yoruto) mencegah kesan spekulatif. Menutup dengan 〜次第です menunjukkan kesiapan berjuang hingga batas akhir.",taboos:"Jangan menggunakan 〜によると tanpa predikat penutup yang tepat (seperti 〜そうだ atau 〜とのことだ) dalam menyampaikan kabar pihak ketiga."},pronunciation_tips:{title:"Intonasi Rujukan Objektif",moraNote:'Pada "ni yoru to", artikulasikan morfem to dengan jeda mikro sebelum memasuki isi kutipan.',soundTip:'Pada "shidai desu", turunkan nada sopan secara mantap.'},common_pitfalls:[{title:"Lupa Predikat Penutup Kabar setelah 〜によると",caseScenario:"Mengutip berita tanpa menambahkan 〜そうだ atau 〜とのことだ di akhir kalimat.",pitfallWarning:"天気【てんき】予報【よほう】に よると、明日【あした】は 雨【あめ】だ。 (Terasa kaku/terputus)",rightSolution:"天気【てんき】予報【よほう】に よると、明日【あした】は 雨【あめ】だ そうだ。 (Tepat)",explanation:"Dalam ragam formal bahasa Jepang, klausa 〜によると wajib diimbangi predikat kabar angin atau kutipan (〜そうだ / 〜ということだ / 〜とのことだ)."},{title:"Tertukar Antara 〜次第 (Segera Setelah) vs 〜次第だ (Tergantung Pada)",caseScenario:'Mengartikan "shirabe shidai" sebagai tergantung.',pitfallWarning:"結果【けっか】を 調【しら】べ 次第【しだい】です。 (Rancu)",rightSolution:"結果【けっか】は 努力【どりょく】 次第【しだい】です。 (Tepat: Nomina + shidai da = tergantung)",explanation:'V-masu + 次第 berarti "segera setelah", sedangkan Nomina + 次第だ berarti "tergantung pada faktor tersebut".'}],who_and_when:{situational_context:"Penyampaian hasil riset pasar, evaluasi berkala proyek, dan pelaporan berita resmi ke dewan direksi.",social_relations:"Koordinasi strategis antara pimpinan kepatuhan dan analis data.",when_not_to_use:'Jangan gunakan ni yoruto untuk mengutip perasaan batin diri sendiri (seperti "menurut saya sendiri").'},scenario:{title:"Telaah Temuan Laporan Audit Ketenagakerjaan",setting:"Ruang Arsip Kepatuhan Tokyo, pukul 15.00",narrative:"Nakamura dan Budi menganalisis rekomendasi pengawas ketenagakerjaan mengenai jam kerja lembur."}},dialogue:[{id:"d1",speaker:"Nakamura",speakerRole:"Manajer SDM & Regulasi",avatar:"👩‍💼",jp:"ブディさん、外部【がいぶ】監査【かんさ】の 中間【ちゅうかん】報告【ほうこく】書【しょ】に よると、現場【げんば】の 労務【ろうむ】管理【かんり】は 高【たか】く 評価【ひょうか】されている そうですよ。",furigana:"ブディさん、外部監査の 中間報告書に よると、現場の 労務管理は 高く 評価されている そうですよ。",romaji:"Budi-san, gaibu kansa no chuukan houkokusho ni yoru to, gemba no roumu kanri wa takaku hyouka sarete iru sou desu yo.",idText:"Budi, menurut laporan sementara audit eksternal, manajemen ketenagakerjaan lapangan kita dinilai sangat tinggi lho."},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"本当【ほんとう】ですか！ チーム全員【ぜんいん】で 労働【ろうどう】時間【じかん】の 遵守【じゅんしゅ】に 努【つと】めてきた 甲斐【かい】が ありました。",furigana:"本当ですか！ チーム全員で 労働時間の 遵守に 努めてきた 甲斐が ありました。",romaji:"Hontou desu ka! Chiimu zenin de roudou jikan no junshu ni tsutomete kita kai ga arimashita.",idText:"Benarkah! Upaya seluruh tim yang telah berusaha mematuhi jam kerja benar-benar membuahkan hasil berharga."},{id:"d3",speaker:"Nakamura",speakerRole:"Manajer SDM & Regulasi",avatar:"👩‍💼",jp:"ええ。ただ、最終【さいしゅう】的【てき】な 認定【にんてい】が 得【え】られるか どうかは、今月【こんげつ】の 改善【かいぜん】報告【ほうこく】の 内容【ないよう】次第【しだい】です。",furigana:"ええ。ただ、最終的な 認定が 得られるか どうかは、今月の 改善報告の 内容次第です。",romaji:"Ee. Tada, saishuutekina nintei ga erareru ka dou ka wa, kongetsu no kaizen houkoku no naiyou shidai desu.",idText:"Benar. Namun, apakah sertifikasi akhir bisa diperoleh atau tidak, semuanya tergantung pada isi laporan perbaikan bulan ini."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 確実【かくじつ】な 認定【にんてい】取得【しゅとく】に 向【む】けて、データに 基【もと】づく 改善【かいぜん】書【しょ】を 丁寧【ていねい】に まとめてまいります。",furigana:"承知いたしました！ 確実な 認定取得に 向けて、データに 基づく 改善書を 丁寧に まとめてまいります。",romaji:"Shouchi itashimashita! Kakujitsuna nintei shutoku ni mukete, deeta ni motozuku kaizensho o teinei ni matomete mairimasu.",idText:"Dimengerti! Menuju perolehan sertifikasi yang pasti, saya akan menyusun dokumen perbaikan berbasis data dengan saksama."}],vocab_breakdown:[{id:"vg-n2-01646",word:"取り出す",reading:"とりだす",romaji:"toridasu",meaning:"mengambil",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 取り出す / 〜に関する 取り出す dalam wacana profesional.",exampleSentence:{jp:"彼は千円札を財布から取り出した。",furigana:"彼は千円札を財布から取り出した。",romaji:"toridasu",idText:"Dia mengeluarkan uang kertas 1.000 yen dari dompetnya."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"トリダ＼ス"}},{id:"vg-n2-01647",word:"採る",reading:"とる",romaji:"toru",meaning:"mengadopsi",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 採る / 〜に関する 採る dalam wacana profesional.",exampleSentence:{jp:"このカップに尿をとってください。",furigana:"このカップに尿をとってください。",romaji:"toru",idText:"Tolong tinggalkan sampel urin di cangkir ini."},pitch:{pattern:1,category:"atamadaka",mora_count:2,downstep_mora:1,contour:"ト＼ル"}},{id:"vg-n2-01648",word:"捕る",reading:"とる",romaji:"toru",meaning:"mengambil",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 捕る / 〜に関する 捕る dalam wacana profesional.",exampleSentence:{jp:"きのう魚を３匹捕った。",furigana:"きのう魚を３匹捕った。",romaji:"toru",idText:"I caught three fish yesterday."},pitch:{pattern:1,category:"atamadaka",mora_count:2,downstep_mora:1,contour:"ト＼ル"}},{id:"vg-n2-01649",word:"トレーニング",reading:"トレーニング",romaji:"toreeningu",meaning:"pelatihan",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を トレーニング (objek tindakan kerja/bisnis).",exampleSentence:{jp:"彼は筋肉をつけるためにトレーニングしている。",furigana:"彼は筋肉をつけるためにトレーニングしている。",romaji:"toreeningu",idText:"Dia telah berlatih untuk mengembangkan ototnya."},pitch:{pattern:2,category:"nakadaka",mora_count:0,downstep_mora:0,contour:"￣"}},{id:"vg-n2-01654",word:"治す",reading:"なおす",romaji:"naosu",meaning:"menyembuhkan",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 治す / 〜に関する 治す dalam wacana profesional.",exampleSentence:{jp:"あの医者は彼のがんを治してくれるかもしれない。",furigana:"あの医者は彼のがんを治してくれるかもしれない。",romaji:"naosu",idText:"Dokter itu mungkin menyembuhkan kankernya."},pitch:{pattern:2,category:"nakadaka",mora_count:3,downstep_mora:2,contour:"ナオ＼ス"}},{id:"vg-n2-01656",word:"仲直り",reading:"なかなおり",romaji:"nakanaori",meaning:"rekonsiliasi; berdamai dengan",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 仲直り (objek tindakan kerja/bisnis).",exampleSentence:{jp:"彼と仲直りしたい。",furigana:"彼と仲直りしたい。",romaji:"nakanaori",idText:"Saya ingin berdamai dengannya."},pitch:{pattern:3,category:"nakadaka",mora_count:5,downstep_mora:3,contour:"ナカナ＼オリ"}},{id:"vg-n2-01657",word:"長引く",reading:"ながびく",romaji:"nagabiku",meaning:"diperpanjang",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 長引く / 〜に関する 長引く dalam wacana profesional.",exampleSentence:{jp:"その経済学者は長引く不況を予期していた。",furigana:"その経済学者は長引く不況を予期していた。",romaji:"nagabiku",idText:"Ekonom mengantisipasi depresi berkepanjangan."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"ナガビ＼ク"}},{id:"vg-n2-01662",word:"慰める",reading:"なぐさめる",romaji:"nagusameru",meaning:"kenyamanan",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 慰める / 〜に関する 慰める dalam wacana profesional.",exampleSentence:{jp:"夜の静けさが私たちを慰めてくれる。",furigana:"夜の静けさが私たちを慰めてくれる。",romaji:"nagusameru",idText:"Keheningan malam menghibur kami."},pitch:{pattern:4,category:"nakadaka",mora_count:5,downstep_mora:4,contour:"ナグサメ＼ル"}}],explanations:[{id:"exp-1",grammarId:"gn2-00065",title:"Pola: 〜ことになっている",formula:"V-dict / V-nai + ことになっている",meaning:"sudah ditetapkan bahwa ... / seharusnya ... (aturan atau kesepakatan dari luar)",nuanceNotes:"〜ことになっている menyatakan bahwa suatu hal sudah ditetapkan, direncanakan, atau diatur — bukan oleh pembicara sendiri, melainkan oleh pihak luar, sistem, atau kesepakatan bersama.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ことになっている",idText:"sudah ditetapkan bahwa ... / seharusnya ... (aturan atau kesepakatan dari luar)"}],examples:[{jp:"社員は毎朝9時に出社することになっている。",romaji:"",idText:"Karyawan sudah ditentukan harus masuk jam 9 pagi."},{jp:"このビルではペットを飼わないことになっている。",romaji:"",idText:"Di gedung ini sudah diatur tidak boleh memelihara hewan peliharaan."},{jp:"来月、東京支社に異動することになっている。",romaji:"",idText:"Bulan depan, sudah diputuskan akan pindah ke kantor cabang Tokyo."}]},{id:"exp-2",grammarId:"gn2-00067",title:"Pola: 〜に違いない",formula:"V-plain / Adj-plain / N + に違いない",meaning:"pasti ... (keyakinan kuat pembicara)",nuanceNotes:"〜に違いない menyatakan keyakinan kuat pembicara bahwa sesuatu pasti benar, berdasarkan penilaian subjektifnya terhadap situasi atau bukti yang ada.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に違いない",idText:"pasti ... (keyakinan kuat pembicara)"}],examples:[{jp:"彼女は今頃、怒っているに違いない。",romaji:"",idText:"Dia pasti sedang marah sekarang."},{jp:"あんなに練習したから、合格するに違いない。",romaji:"",idText:"Sudah latihan sekeras itu, pasti lulus."},{jp:"電気がついている。まだ起きているに違いない。",romaji:"",idText:"Lampunya menyala. Pasti masih terjaga."}]},{id:"exp-3",grammarId:"gn2-00068",title:"Pola: 〜はずがない",formula:"V-plain / Adj-plain / N + の + はずがない",meaning:"tidak mungkin ... (berdasarkan logika atau ekspektasi yang wajar)",nuanceNotes:"〜はずがない menyatakan bahwa sesuatu seharusnya tidak mungkin terjadi, berdasarkan pengetahuan atau logika objektif pembicara.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜はずがない",idText:"tidak mungkin ... (berdasarkan logika atau ekspektasi yang wajar)"}],examples:[{jp:"昨日日本に着いたばかりだ。疲れていないはずがない。",romaji:"",idText:"Baru tiba di Jepang kemarin. Tidak mungkin tidak lelah."},{jp:"あの優しい人が嘘をつくはずがない。",romaji:"",idText:"Orang sebaik itu tidak mungkin berbohong."},{jp:"10年も勉強して、できないはずがない。",romaji:"",idText:"Belajar selama 10 tahun, tidak mungkin tidak bisa."}]},{id:"exp-4",grammarId:"gn2-00069",title:"Pola: 〜べきだ",formula:"V-dict + べきだ (する → すべきだ atau するべきだ)",meaning:"seharusnya ... / sudah semestinya ... (kewajiban moral)",nuanceNotes:"〜べきだ menyatakan bahwa suatu tindakan adalah hal yang benar atau semestinya dilakukan, berdasarkan norma moral, sosial, atau logika yang berlaku.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜べきだ",idText:"seharusnya ... / sudah semestinya ... (kewajiban moral)"}],examples:[{jp:"間違えたら、素直に謝るべきだ。",romaji:"",idText:"Kalau salah, seharusnya jujur meminta maaf."},{jp:"そんな大切なことは親に相談すべきだ。",romaji:"",idText:"Hal sepenting itu seharusnya didiskusikan dengan orang tua."},{jp:"健康のために、もっと野菜を食べるべきだ。",romaji:"",idText:"Demi kesehatan, seharusnya makan lebih banyak sayuran."}]},{id:"exp-5",grammarId:"gn2-00070",title:"Pola: 〜べきではない",formula:"V-dict + べきではない",meaning:"tidak seharusnya ... / tidak semestinya ...",nuanceNotes:"〜べきではない adalah bentuk negatif dari べきだ — menyatakan bahwa suatu tindakan tidak sesuai dengan norma, moral, atau logika yang benar.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜べきではない",idText:"tidak seharusnya ... / tidak semestinya ..."}],examples:[{jp:"人のプライバシーを勝手に見るべきではない。",romaji:"",idText:"Tidak seharusnya mengintip privasi orang lain sembarangan."},{jp:"大切なことを人任せにするべきではない。",romaji:"",idText:"Hal-hal penting tidak seharusnya diserahkan begitu saja kepada orang lain."},{jp:"感情的になって判断するべきではない。",romaji:"",idText:"Tidak seharusnya mengambil keputusan dalam keadaan emosi."}]},{id:"exp-6",grammarId:"gn2-00071",title:"Pola: 〜得る／〜得ない",formula:"V-stem + 得る (うる/える) / V-stem + 得ない (えない)",meaning:"bisa terjadi / tidak bisa terjadi (kemungkinan — formal)",nuanceNotes:"〜得る menyatakan bahwa sesuatu berpotensi atau memungkinkan untuk terjadi. 〜得ない menyatakan sesuatu yang mustahil terjadi. Digunakan dalam konteks formal atau tulisan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜得る／〜得ない",idText:"bisa terjadi / tidak bisa terjadi (kemungkinan — formal)"}],examples:[{jp:"そのような事故は十分起こり得る。",romaji:"",idText:"Kecelakaan seperti itu sangat mungkin terjadi."},{jp:"あり得ないことが現実になった。",romaji:"",idText:"Hal yang dianggap mustahil menjadi kenyataan."},{jp:"あらゆる可能性を考え得る限り検討した。",romaji:"",idText:"Kami sudah mempertimbangkan semua kemungkinan yang bisa dibayangkan."}]},{id:"exp-7",grammarId:"gn2-00072",title:"Pola: 〜ずにはいられない",formula:"V-nai-stem + ずにはいられない (する → せずにはいられない)",meaning:"tidak bisa tidak ... / tidak bisa menahan diri untuk tidak ...",nuanceNotes:"〜ずにはいられない mengungkapkan dorongan yang tidak bisa ditahan — pembicara merasa terpaksa melakukan sesuatu karena emosi atau perasaan yang kuat dari dalam dirinya.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ずにはいられない",idText:"tidak bisa tidak ... / tidak bisa menahan diri untuk tidak ..."}],examples:[{jp:"その映画を見て、泣かずにはいられなかった。",romaji:"",idText:"Menonton film itu, tidak bisa tidak menangis."},{jp:"彼女の歌声を聞いて、感動せずにはいられなかった。",romaji:"",idText:"Mendengar suara nyanyiannya, tidak bisa tidak tersentuh."},{jp:"不公平な扱いを見て、抗議せずにはいられない。",romaji:"",idText:"Melihat perlakuan tidak adil itu, tidak bisa tidak protes."}]},{id:"exp-8",grammarId:"gn2-00076",title:"Pola: 〜ものだ",formula:"V-dict / V-nai / Adj-plain / N + ものだ",meaning:"memang begitulah ... / seharusnya ... (generalisasi, norma, atau nostalgia)",nuanceNotes:'〜ものだ memiliki tiga fungsi utama tergantung konteks: (1) generalisasi/norma umum — "begitulah adanya"; (2) nostalgia — mengenang kebiasaan masa lalu; (3) kekaguman atau perasaan mendalam.',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ものだ",idText:"memang begitulah ... / seharusnya ... (generalisasi, norma, atau nostalgia)"}],examples:[{jp:"人間は失敗から学ぶものだ。",romaji:"",idText:"Memang manusia belajar dari kegagalan."},{jp:"子供のころは、よく川で遊んだものだ。",romaji:"",idText:"Waktu kecil dulu, sering main di sungai."},{jp:"彼女のやさしさには、本当に感動するものだ。",romaji:"",idText:"Kebaikan hatinya sungguh mengharukan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "監査 (かんさ)" dalam tata kelola institusi?',sentencePrompt:'Istilah "外部【がいぶ】監査【かんさ】" bermakna:',options:["Pemeriksaan kepatuhan resmi oleh auditor independen luar","Pesta perayaan ulang tahun perusahaan di hotel mewah","Pembagian dividen saham kepada pemilik modal","Pemberian hadiah cendera mata kepada tamu asing"],correctAnswer:"Pemeriksaan kepatuhan resmi oleh auditor independen luar",explanation:'"監査 (かんさ)" bermakna inspeksi, audit, dan verifikasi independen terhadap kepatuhan regulasi atau keuangan.',diagnosticFeedback:{"Pesta perayaan ulang tahun perusahaan di hotel mewah":"Salah: Perayaan adalah 記念式典 (kinen shikiten).","Pembagian dividen saham kepada pemilik modal":"Salah: Pembagian dividen adalah 配当金の分配 (haitoukin no bumpai).","Pemberian hadiah cendera mata kepada tamu asing":"Salah: Cendera mata adalah 記念品 (kinenhin) atau お土産 (omiyage)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat dengan pola yang menyatakan ketergantungan pada suatu faktor kunci:",sentencePrompt:"手術【しゅじゅつ】が 成功【せいこう】するか どうかは、医師【いし】の 腕【うで】と 患者【かんじゃ】の 体力【たいりょく】[　　]。",options:["次第【しだい】だ","に よると","に 応【おう】じた","せざるを 得【え】ない"],correctAnswer:"次第【しだい】だ",explanation:"Nomina + 次第だ menyatakan bahwa hasil sepenuhnya bergantung pada faktor tersebut (tergantung keahlian dokter dan stamina pasien).",diagnosticFeedback:{"に よると":"Kekeliruan Pola: 〜によると menyatakan sumber kutipan warta berita, bukan penentu keberhasilan.","に 応【おう】じた":"Kekeliruan Sintaksis: 〜に応じた membutuhkan nomina setelahnya, sedangkan di sini kalimat berada di posisi predikat penutup.","せざるを 得【え】ない":"Kekeliruan Nuansa: 〜ざるを得ない menyatakan keterpaksaan tindakan, tidak nyambung dengan frasa bergantung pada."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Kesesuaian Predikat Kutipan): Manakah kalimat yang menggunakan 〜によると secara benar dengan predikat penutupnya?",sentencePrompt:"Pilihlah kalimat yang menggunakan 〜によると secara gramatikal dan berpasangan tepat:",options:["新聞【しんぶん】の 報道【ほうどう】に よると、新【あたら】しい 法律【ほうりつ】が 可決【かけつ】された そうだ。","私【わたし】の 考え【かんがえ】に よると、この 案【あん】は 失敗【しっぱい】する。","新聞【しんぶん】の 報道【ほうどう】に よると、明日【あした】 会議【かいぎ】を 始【はじ】めましょう。","彼【かれ】の 話【はなし】に よると、リンゴは 美味【おい】しい です。"],correctAnswer:"新聞【しんぶん】の 報道【ほうどう】に よると、新【あたら】しい 法律【ほうりつ】が 可決【かけつ】された そうだ。",explanation:"〜によると wajib berpasangan dengan predikat kabar angin/kutipan seperti 〜そうだ atau 〜ということだ.",diagnosticFeedback:{"私【わたし】の 考え【かんがえ】に よると、この 案【あん】は 失敗【しっぱい】する。":"Kekeliruan Subjek: 〜によると tidak boleh digunakan untuk pikiran atau opini pribadi diri sendiri (gunakan 私の考えでは).","新聞【しんぶん】の 報道【ほうどう】に よると、明日【あした】 会議【かいぎ】を 始【はじ】めましょう。":"Kekeliruan Predikat: 〜によると tidak boleh dipadukan dengan ajakan (〜ましょう) atau perintah.","彼【かれ】の 話【はなし】に よると、リンゴは 美味【おい】しい です。":"Kekeliruan Predikat: Kurang predikat kabar angin (〜そうだ/とのこと) di akhir kalimat."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun frasa-frasa berikut menjadi kalimat pernyataan faktor penentu:",sentencePrompt:"Susunlah frasa-frasa berikut:",options:["認定【にんてい】が 得【え】られるかは 改善【かいぜん】報告【ほうこく】の 内容【ないよう】次第【しだい】です","改善【かいぜん】報告【ほうこく】の 認定【にんてい】が 得【え】られるかは 内容【ないよう】次第【しだい】です","内容【ないよう】次第【しだい】です 認定【にんてい】が 得【え】られるかは 改善【かいぜん】報告【ほうこく】の","得【え】られるかは 認定【にんてい】が 改善【かいぜん】報告【ほうこく】の 内容【ないよう】次第【しだい】です"],correctAnswer:"認定【にんてい】が 得【え】られるかは 改善【かいぜん】報告【ほうこく】の 内容【ないよう】次第【しだい】です",explanation:"Urutan baku: Topik klausa bersyarat (認定が得られるかは) + nomina penentu (改善報告の内容) + predikat penutup (次第です).",diagnosticFeedback:{"改善【かいぜん】報告【ほうこく】の 認定【にんてい】が 得【え】られるかは 内容【ないよう】次第【しだい】です":'Kekeliruan Modifikasi: Frasa modifikasi "kaizen houkoku no" terpisah dari objeknya "naiyou".',"内容【ないよう】次第【しだい】です 認定【にんてい】が 得【え】られるかは 改善【かいぜん】報告【ほうこく】の":"Predikat Terbalik: Meletakkan predikat di awal kalimat.","得【え】られるかは 認定【にんてい】が 改善【かいぜん】報告【ほうこく】の 内容【ないよう】次第【しだい】です":"Subjek Terbalik: Verba ditaruh sebelum subjek partikel ga."},tokens:["認定【にんてい】が","得【え】られるかは","改善【かいぜん】報告【ほうこく】の","内容【ないよう】次第【しだい】です"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Komitmen Menuntaskan): Saat Nakamura menyampaikan: 「最終的な 認定が 得られるか どうかは、今月の 改善報告の 内容次第です」, apa respons terbaik Anda?",sentencePrompt:"Pilihlah tanggapan yang menunjukkan kesungguhan dan profesionalisme tinggi:",options:["承知【しょうち】いたしました！ 確実【かくじつ】な 認定【にんてい】取得【しゅとく】に 向【む】けて、データに 基【もと】づく 改善【かいぜん】書【しょ】を 丁寧【ていねい】に まとめてまいります。","監査【かんさ】なんて どうでもいいので、適当【てきとう】に 数字【すうじ】を でっち上【あ】げて 提出【ていしゅつ】しておきますね。","どうせ 認可【にんか】なんて 取【と】れませんから、今【いま】から 諦【あきら】めて 飲【の】みに 行【い】きましょう。","私【わたし】の せいじゃありません。中村【なかむら】さんが 一人【ひとり】で レポートを 書【か】いてください。"],correctAnswer:"承知【しょうち】いたしました！ 確実【かくじつ】な 認定【にんてい】取得【しゅとく】に 向【む】けて、データに 基【もと】づく 改善【かいぜん】書【しょ】を 丁寧【ていねい】に まとめてまいります。",explanation:"Menunjukkan komitmen terhadap integritas data dan tekad mengamankan sertifikasi bagi tim.",diagnosticFeedback:{"監査【かんさ】なんて どうでもいいので、適当【てきとう】に 数字【すうじ】を でっち上【あ】げて 提出【ていしゅつ】しておきますね。":"Pemalsuan Data: Memalsukan angka dalam audit adalah tindak pidana fatal dalam bisnis.","どうせ 認可【にんか】なんて 取【と】れませんから、今【いま】から 諦【あきら】めて 飲【の】みに 行【い】きましょう。":"Defaitis & Malas: Menyerah sebelum berjuang merusak reputasi seluruh divisi SDM.","私【わたし】の せいじゃありません。中村【なかむら】さんが 一人【ひとり】で レポートを 書【か】いてください。":"Melempar Tugas: Menolak bekerja sama dengan manajer sangat tidak pantas."}}],can_do_challenge:{statement:"Bisa mengutip temuan hasil audit ketenagakerjaan dan menjelaskan faktor penentu keberhasilan sertifikasi mutu.",situation:"Ruang Arsip Kepatuhan Tokyo, pukul 15.00",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜に違いない!",modelAnswer:"本当【ほんとう】ですか！ チーム全員【ぜんいん】で 労働【ろうどう】時間【じかん】の 遵守【じゅんしゅ】に 努【つと】めてきた 甲斐【かい】が ありました。",modelAnswerId:"Benarkah! Upaya seluruh tim yang telah berusaha mematuhi jam kerja benar-benar membuahkan hasil berharga.",culturalEtiquette:"Menyandarkan laporan pada sumber formal (chousa ni yoruto) mencegah kesan spekulatif. Menutup dengan 〜次第です menunjukkan kesiapan berjuang hingga batas akhir.",skillUnlocked:["Menguasai formulasi pola 〜に違いない","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Keharusan Normatif, Keterpaksaan Logis & Aturan Bersama"]},pocket_summary:{keyFormula:"N + によると / によれば (menurut sumber ...), N + 次第だ / 次第で (tergantung pada faktor ...)",coreWords:["監査【かんさ】","報告書【ほうこくしょ】","結果【けっか】 (hasil)","評価【ひょうか】する (mengevaluasi, menilai kinerja atau kualitas)"],coreWarning:"Jangan menggunakan 〜によると tanpa predikat penutup yang tepat (seperti 〜そうだ atau 〜とのことだ) dalam menyampaikan kabar pihak ketiga.",quickDialogue:"A: ブディさん、外部【がいぶ】監査【かんさ】の 中間【... → B: 本当【ほんとう】ですか！ チーム全員【ぜんいん】で..."}}},s={"les-n2-u07-01":{pedagogical_framework:{what:{summary:"Menguasai ungkapan apresiasi berbobot estetis: 〜ものがある (memiliki sisi yang sangat terasa berbobot/mengagumkan) dan batasan kepantasan etis: 〜ものではない (tidak selayaknya dilakukan secara moral/etis).",canDo:"Bisa mengevaluasi karya inovasi arsitektur ramah lingkungan dan mengingatkan batasan etika penghematan biaya produksi.",targetPatterns:["A-i / Na-na / V-dict + ものがある (memiliki daya tarik / nuansa yang sangat terasa)","V-dict + ものではない (tidak selayaknya ... tidak patut secara etis)"],coreVocabSample:["洗練【せんれん】","工夫【くふう】","配慮【はいりょ】","歓声【かんせい】","美徳【びとく】","表現【ひょうげん】する","調和【ちょうわ】","設計【せっけい】"]},sensei_context:{sceneIntro:"Studio evaluasi desain produk ramah lingkungan di Shibuya. Sakura (Konsultan Manajemen) meninjau maket paviliun bambu berkelanjutan bersama Budi.",dailyMission:'Gunakan "mono ga aru" untuk memuji kecanggihan konsep desain dan "mono dewa nai" untuk menjaga integritas standar keselamatan.',whyOrder:"Pola ~mono ga aru memberikan kedalaman apresiasi kultural tingkat menengah-atas (kepekaan rasa), sementara ~mono dewa nai adalah rambu etis yang membimbing batasan profesional."},cultural_notes:{title:"Apresiasi Bernuansa (深みのある評価) dan Batasan Kepantasan (品格と倫理)",etiquette:'Dalam dunia desain Jepang, memuji dengan "miryoku-teki na mono ga arimasu" terdengar jauh lebih elegan dan berwibawa daripada sekadar mengatakan "sugoi desu".',taboos:"Hindari memakai 〜ものではない untuk menggurui atasan secara langsung di forum publik karena terdengar seperti mendikte moralitas lawan bicara."},pronunciation_tips:{title:"Intonasi Penilaian Berbobot",moraNote:'Pada "mono ga aru", lafalkan mo-no-ga-a-ru dengan tempo tenang mengalir tanpa aksen mendesak.',soundTip:'Pada "mono dewa nai", beri sedikit penekanan tegas pada de-wa untuk menandai keteguhan prinsip etis.'},common_pitfalls:[{title:"Tertukar Antara 〜ものがある (Kesan Mendalam) vs 〜ことだ (Perintah Halus)",caseScenario:"Ingin mengungkapkan rasa kagum tetapi memakai kotoda.",pitfallWarning:"彼【かれ】の 努力【どりょく】には 感心【かんしん】する ことだ。 (Terdengar seperti nasihat menggurui)",rightSolution:"彼【かれ】の 努力【どりょく】には 感心【かんしん】する ものが ある。 (Tepat: kesan mendalam yang dirasakan pembicara)",explanation:"〜ものがある mencerminkan resonansi batin subjektif yang mendalam atas suatu kenyataan (memiliki sisi yang membuat kagum)."},{title:"Memakai 〜ものではない untuk Larangan Fisik Sederhana",caseScenario:"Memakai mono dewa nai untuk larangan membuang sampah biasa.",pitfallWarning:"ここには ゴミを 捨【す】てる ものではない。 (Terlalu berlebihan/filosofis)",rightSolution:"約束【やくそく】を 破【やぶ】る ものではない。 (Tepat: menyangkut moralitas kepantasan)",explanation:"〜ものではない khusus digunakan untuk norma moral, akal sehat umum, atau etika perilaku manusia, bukan rambu larangan teknis."}],who_and_when:{situational_context:"Pameran karya arsitektur, ulasan desain produk, editorial majalah industri, dan diskusi etika bisnis.",social_relations:"Apresiasi estetik kolegial antara konsultan desain senior (Sakura) dan praktisi inovasi (Budi).",when_not_to_use:"Jangan gunakan pada hal-hal sepele yang tidak memiliki bobot penilaian rasa atau moral."},scenario:{title:"Evaluasi Maket Paviliun Ramah Lingkungan Shibuya",setting:"Studio Desain Shibuya, Lantai 5, pukul 11.30",narrative:"Sakura mengagumi struktur lengkung kayu maket Budi yang memadukan teknik tradisional Jepang dan bambu Nusantara."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Konsultan Manajemen",avatar:"👩‍🏫",jp:"ブディさん、この 竹【たけ】と 木材【もくざい】を 融合【ゆうごう】させた デザインには、目【め】を 見張【みは】る ものが ありますね！",furigana:"ブディさん、この 竹と 木材を 融合させた デザインには、目を 見張る ものが ありますね！",romaji:"Budi-san, kono take to mokuzai o yuugou saseta dezain ni wa, me o miharu mono ga arimasu ne!",idText:"Budi, pada desain yang memadukan bambu dan kayu ini, benar-benar ada sisi yang membuat mata terkesima ya!"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ありがとうございます！ 日本【にほん】の 伝統【でんとう】工法【こうほう】と インドネシアの 素材【そざい】の 調和【ちょうわ】を 意識【いしき】して 設計【せっけい】いたしました。",furigana:"ありがとうございます！ 日本の 伝統工法と インドネシアの 素材の 調和を 意識して 設計いたしました。",romaji:"Arigatou gozaimasu! Nihon no dentou kouhou to Indoneshia no sozai no chouwa o ishiki shite sekkei itashimashita.",idText:"Terima kasih banyak! Saya merancangnya dengan penuh kesadaran akan keselarasan antara teknik tradisional Jepang dan material Indonesia."},{id:"d3",speaker:"Sakura",speakerRole:"Konsultan Manajemen",avatar:"👩‍🏫",jp:"素晴【すば】らしいです。ただ、コスト削減【さくげん】のために 強度【きょうど】計算【けいさん】を 妥協【だきょう】する ような ことは、プロとして 決【けっ】して すべきもの【もの】では ありませんよ。",furigana:"素晴らしいです。ただ、コスト削減のために 強度計算を 妥協する ような ことは、プロとして 決して すべきものでは ありませんよ。",romaji:"Subarashii desu. Tada, kosuto sakugen no tame ni kyoudo keisan o dakyou suru youna koto wa, puro to shite kesshite subeki mono dewa arimasen yo.",idText:"Luar biasa. Namun, hal seperti mengorbankan perhitungan kekuatan struktur demi pemotongan biaya sama sekali bukanlah hal yang layak dilakukan sebagai profesional."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"もちろんです！ 美【うつく】しさと 同時【どうじ】に 耐震【たいしん】基準【きじゅん】を 完璧【かんぺき】に 満【み】たすよう、厳格【げんかく】に 検証【けんしょう】を 重【かさ】ねてまいります。",furigana:"もちろんです！ 美しさと 同時に 耐震基準を 完璧に 満たすよう、厳格に 検証を 重ねてまいります。",romaji:"Mochiron desu! Utsukushisa to douji ni taishin kijun o kampeki ni mitasu you, genkaku ni kenshou o kasanete mairimasu.",idText:"Tentu saja! Bersamaan dengan keindahan, saya akan melakukan verifikasi ketat berulang kali agar memenuhi standar ketahanan gempa secara sempurna."}],vocab_breakdown:[{id:"vg-n2-01768",word:"話合い",reading:"はなしあい",romaji:"hanashiai",meaning:"diskusi; konferensi",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 話合い (objek tindakan kerja/bisnis).",exampleSentence:{jp:"話し合いはちょっと中断した。",furigana:"話し合いはちょっと中断した。",romaji:"hanashiai",idText:"Terjadi jeda singkat dalam diskusi."},pitch:{pattern:0,category:"heiban",mora_count:5,downstep_mora:0,contour:"ハナシアイ￣"}},{id:"vg-n2-01769",word:"話し掛ける",reading:"はなしかける",romaji:"hanashikakeru",meaning:"menghampiri seseorang",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 話し掛ける / 〜に関する 話し掛ける dalam wacana profesional.",exampleSentence:{jp:"男が近づいて私に話しかけた。",furigana:"男が近づいて私に話しかけた。",romaji:"hanashikakeru",idText:"Seorang pria datang dan berbicara kepada saya."},pitch:{pattern:5,category:"nakadaka",mora_count:6,downstep_mora:5,contour:"ハナシカケ＼ル"}},{id:"vg-n2-01774",word:"放れる",reading:"はなれる",romaji:"hanareru",meaning:"pergi",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 放れる / 〜に関する 放れる dalam wacana profesional.",exampleSentence:{jp:"放れるを使います。",furigana:"放れるを使います。",romaji:"hanareru",idText:"Menggunakan pergi."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"ハナレ＼ル"}},{id:"vg-n2-01776",word:"跳ねる",reading:"はねる",romaji:"haneru",meaning:"melompat",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 跳ねる / 〜に関する 跳ねる dalam wacana profesional.",exampleSentence:{jp:"犬が跳ねるのをごらん。",furigana:"犬が跳ねるのをごらん。",romaji:"haneru",idText:"Lihatlah anjing itu melompat."},pitch:{pattern:2,category:"nakadaka",mora_count:3,downstep_mora:2,contour:"ハネ＼ル"}},{id:"vg-n2-01779",word:"はめる",reading:"はめる",romaji:"hameru",meaning:"(colloquial) to get in; to insert",pos:"verb-ru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の はめる / 〜に関する はめる dalam wacana profesional.",exampleSentence:{jp:"オレ、うまくハメられた。",furigana:"オレ、うまくハメられた。",romaji:"hameru",idText:"Saya dijebak dengan baik."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"ハメル￣"}},{id:"vg-n2-01781",word:"流行る",reading:"はやる",romaji:"hayaru",meaning:"berkembang",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 流行る / 〜に関する 流行る dalam wacana profesional.",exampleSentence:{jp:"今インフルエンザが流行ってます。",furigana:"今インフルエンザが流行ってます。",romaji:"hayaru",idText:"Ada banyak flu yang terjadi sekarang."},pitch:{pattern:2,category:"nakadaka",mora_count:3,downstep_mora:2,contour:"ハヤ＼ル"}},{id:"vg-n2-01782",word:"払い込む",reading:"はらいこむ",romaji:"haraikomu",meaning:"setoran",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 払い込む / 〜に関する 払い込む dalam wacana profesional.",exampleSentence:{jp:"月に１万円づつ銀行に払い込んだ。",furigana:"月に１万円づつ銀行に払い込んだ。",romaji:"haraikomu",idText:"Saya menaruh sepuluh ribu yen ke bank setiap bulan."},pitch:{pattern:4,category:"nakadaka",mora_count:5,downstep_mora:4,contour:"ハライコ＼ム"}},{id:"vg-n2-01783",word:"払い戻す",reading:"はらいもどす",romaji:"haraimodosu",meaning:"membayar kembali",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 払い戻す / 〜に関する 払い戻す dalam wacana profesional.",exampleSentence:{jp:"サラは払い戻してもらう事を要求した。",furigana:"サラは払い戻してもらう事を要求した。",romaji:"haraimodosu",idText:"Sarah menuntut agar dia diberikan pengembalian uang."},pitch:{pattern:5,category:"nakadaka",mora_count:6,downstep_mora:5,contour:"ハライモド＼ス"}}],explanations:[{id:"exp-1",grammarId:"gn2-00077",title:"Pola: 〜ものではない",formula:"V-dict + ものではない",meaning:"tidak seharusnya ... / tidak pantas ... (larangan berdasarkan norma atau etika)",nuanceNotes:"〜ものではない menyatakan larangan atau penilaian bahwa suatu tindakan tidak sesuai dengan norma sosial, etika, atau akal sehat.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ものではない",idText:"tidak seharusnya ... / tidak pantas ... (larangan berdasarkan norma atau etika)"}],examples:[{jp:"人前でそんなことを言うものではない。",romaji:"",idText:"Tidak pantas mengatakan hal seperti itu di depan orang."},{jp:"食べ物を粗末にするものではない。",romaji:"",idText:"Tidak seharusnya menyia-nyiakan makanan."},{jp:"困っている人を見捨てるものではない。",romaji:"",idText:"Tidak pantas meninggalkan orang yang sedang kesulitan."}]},{id:"exp-2",grammarId:"gn2-00078",title:"Pola: 〜ものがある",formula:"V-plain / Adj-plain + ものがある",meaning:"ada sesuatu yang ... / terasa ada unsur ... (kesan subjektif yang dalam)",nuanceNotes:"〜ものがある mengungkapkan perasaan atau kesan subjektif yang kuat — bahwa ada suatu kualitas atau elemen tertentu yang benar-benar dirasakan oleh pembicara.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ものがある",idText:"ada sesuatu yang ... / terasa ada unsur ... (kesan subjektif yang dalam)"}],examples:[{jp:"彼の演技には心を打つものがある。",romaji:"",idText:"Ada sesuatu dalam aktingnya yang benar-benar menyentuh hati."},{jp:"この話には考えさせられるものがある。",romaji:"",idText:"Ada sesuatu dalam cerita ini yang membuat kita berpikir."},{jp:"彼女の作品には独特の美しさを感じるものがある。",romaji:"",idText:"Ada sesuatu dalam karya-karyanya yang memancarkan keindahan yang unik."}]},{id:"exp-3",grammarId:"gn2-00079",title:"Pola: 〜ではないか",formula:"V-plain / Adj-plain / N + ではないか (kasual: じゃないか)",meaning:"bukankah ... ? / ayo ... — (retorikal atau ajakan)",nuanceNotes:"〜ではないか digunakan dalam dua fungsi: (1) pertanyaan retoris untuk menegaskan pendapat pembicara, atau (2) ajakan atau usulan kepada lawan bicara.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ではないか",idText:"bukankah ... ? / ayo ... — (retorikal atau ajakan)"}],examples:[{jp:"これは重大な問題ではないか。",romaji:"",idText:"Bukankah ini masalah yang sangat serius?"},{jp:"せっかくだから、一緒に行こうではないか。",romaji:"",idText:"Sudah jauh-jauh ke sini, ayo pergi bersama."},{jp:"この景色、本当に美しいじゃないか。",romaji:"",idText:"Pemandangan ini, indah sekali kan?"}]},{id:"exp-4",grammarId:"gn2-00080",title:"Pola: 〜に相違ない",formula:"V-plain / Adj-plain / N + に相違ない",meaning:"pasti ... (keyakinan formal dan kuat — lebih formal dari に違いない)",nuanceNotes:"〜に相違ない mengungkapkan keyakinan kuat bahwa sesuatu pasti benar — setara dengan に違いない tetapi lebih formal. Sering ditemukan dalam tulisan resmi, dokumen hukum, atau laporan.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に相違ない",idText:"pasti ... (keyakinan formal dan kuat — lebih formal dari に違いない)"}],examples:[{jp:"目撃者の証言から、彼が犯人であるに相違ない。",romaji:"",idText:"Berdasarkan kesaksian saksi mata, dialah pasti pelakunya."},{jp:"その方針は正しいに相違ない。",romaji:"",idText:"Kebijakan tersebut pasti benar."},{jp:"この発見は歴史的な意義を持つに相違ない。",romaji:"",idText:"Penemuan ini pasti memiliki makna historis."}]},{id:"exp-5",grammarId:"gn2-00082",title:"Pola: 〜を余儀なくされる",formula:"N + を余儀なくされる",meaning:"dipaksa (oleh keadaan) untuk melakukan ... (pasif formal)",nuanceNotes:"〜を余儀なくされる adalah ungkapan pasif formal yang menyatakan bahwa seseorang terpaksa melakukan sesuatu bukan atas kemauan sendiri, melainkan karena keadaan yang memaksa dari luar.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜を余儀なくされる",idText:"dipaksa (oleh keadaan) untuk melakukan ... (pasif formal)"}],examples:[{jp:"地震の影響で、住民は避難を余儀なくされた。",romaji:"",idText:"Akibat gempa bumi, warga terpaksa mengungsi."},{jp:"経営難で、会社は工場閉鎖を余儀なくされた。",romaji:"",idText:"Karena kesulitan keuangan, perusahaan terpaksa menutup pabrik."},{jp:"怪我で選手は引退を余儀なくされた。",romaji:"",idText:"Akibat cedera, atlet itu terpaksa pensiun."}]},{id:"exp-6",grammarId:"gn2-00124",title:"Pola: 〜ものなら",formula:"V-potential / V-volitional-plain + ものなら",meaning:"kalau saja bisa ... (harapan hypothetical / tantangan implisit)",nuanceNotes:"〜ものなら memiliki dua penggunaan: (1) harapan terhadap sesuatu yang dianggap sulit atau mustahil; (2) tantangan atau provokasi implisit.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ものなら",idText:"kalau saja bisa ... (harapan hypothetical / tantangan implisit)"}],examples:[{jp:"できるものなら、もう一度やり直したい。",romaji:"",idText:"Kalau saja bisa, ingin mengulang dari awal."},{jp:"やれるものならやってみろ。",romaji:"",idText:"Kalau memang bisa, silakan coba saja."}]},{id:"exp-7",grammarId:"gn2-00126",title:"Pola: 〜というものだ",formula:"V-plain / Adj-plain / N + というものだ",meaning:"memang begitulah seharusnya / itulah yang namanya ...",nuanceNotes:"〜というものだ menyatakan bahwa sesuatu memang sudah seharusnya begitu — mengungkapkan prinsip umum, nilai, atau kebenaran yang dipegang pembicara.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜というものだ",idText:"memang begitulah seharusnya / itulah yang namanya ..."}],examples:[{jp:"親が子を思うのは当然というものだ。",romaji:"",idText:"Memang sudah seharusnya orang tua menyayangi anaknya."},{jp:"苦しい時に助け合う、それが友情というものだ。",romaji:"",idText:"Saling membantu di saat sulit — itulah yang namanya persahabatan."}]},{id:"exp-8",grammarId:"gn2-00127",title:"Pola: 〜というものでもない",formula:"V-plain / Adj-plain / N + というものでもない",meaning:"bukan berarti ... / tidak harus selalu begitu ...",nuanceNotes:'〜というものでもない menyangkal generalisasi atau asumsi yang terlalu mutlak — "bukan berarti selalu begitu."',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜というものでもない",idText:"bukan berarti ... / tidak harus selalu begitu ..."}],examples:[{jp:"値段が高ければいいというものでもない。",romaji:"",idText:"Bukan berarti karena mahal pasti bagus."},{jp:"努力すれば必ず成功するというものでもない。",romaji:"",idText:"Bukan berarti kalau sudah berusaha keras pasti berhasil."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "洗練 (せんれん)" dalam dunia kreasi arsitektur?',sentencePrompt:'Istilah "洗練【せんれん】された デザイン" bermakna:',options:["Desain yang terpoles elegan, matang, dan bebas dari elemen kasar","Desain murahan yang dibuat dalam waktu sepuluh menit","Pencoretan gambar sketsa dengan spidol hitam secara kasar","Penjualan barang rongsokan di pasar loak kota"],correctAnswer:"Desain yang terpoles elegan, matang, dan bebas dari elemen kasar",explanation:'"洗練 (せんれん)" bermakna keanggunan yang terasah, estetika yang matang, dan kepiawaian seni yang tinggi.',diagnosticFeedback:{"Desain murahan yang dibuat dalam waktu sepuluh menit":"Salah: Karya instan murahan adalah 粗悪品 (soakuhin) atau 安物.","Pencoretan gambar sketsa dengan spidol hitam secara kasar":"Salah: Coretan kasar adalah 落書き (rakugaki) atau 乱筆.","Penjualan barang rongsokan di pasar loak kota":"Salah: Barang loak adalah 骨董品 (kottouhin) atau ガラクタ."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat dengan pola apresiasi mendalam yang berbobot estetis:",sentencePrompt:"彼【かれ】の 描【えが】く 水墨【すいぼく】画【が】には、言葉【ことば】では 言【い】い表【あらわ】せない [　　]。",options:["深【ふか】い ものが ある","深【ふか】い ものではない","深【ふか】い ことに している","深【ふか】い わけには いかない"],correctAnswer:"深【ふか】い ものが ある",explanation:"A-i + ものがある menyatakan adanya keindahan/kedalaman yang sangat terasa di hati pembicara.",diagnosticFeedback:{"深【ふか】い ものではない":"Kekeliruan Makna: 〜ものではない menyatakan larangan moral, tidak cocok untuk apresiasi seni.","深【ふか】い ことに している":"Kekeliruan Pola: 〜ことにしている berarti tekad disiplin diri, tidak nyambung dengan sifat lukisan.","深【ふか】い わけには いかない":"Kekeliruan Pola: 〜わけにはいかない menyatakan batasan kewajiban sosial, tidak pas untuk mendeskripsikan estetika."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Kaidah Kepantasan Etis): Manakah kalimat yang menggunakan 〜ものではない secara tepat?",sentencePrompt:"Pilihlah kalimat yang menggunakan 〜ものではない dengan nuansa etika yang benar:",options:["人【ひと】の 悪口【わるくち】を 陰【かげ】で 言【い】う ものではない。","疲【つか】れたときは、無理【むり】して 走【はし】る ものが ある。","明日【あした】は 楽【たの】しい 旅行【りょこう】に 行【い】く ものではない。","お腹【なか】が 空【す】いたから、ご飯【はん】を 食【た】べる ものではない。"],correctAnswer:"人【ひと】の 悪口【わるくち】を 陰【かげ】で 言【い】う ものではない。",explanation:"Membicarakan keburukan orang lain di belakang adalah pelanggaran norma etika/kepantasan umum, sangat pas memakai 〜ものではない.",diagnosticFeedback:{"疲【つか】れたときは、無理【むり】して 走【はし】る ものが ある。":"Kekeliruan Pola: Di sini dibutuhkan larangan/nasihat (hashiru mono dewa nai), bukan mono ga aru.","明日【あした】は 楽【たの】しい 旅行【りょこう】に 行【い】く ものではない。":"Kekeliruan Konteks: Berlibur bukanlah perbuatan terlarang secara etis.","お腹【なか】が 空【す】いたから、ご飯【はん】を 食【た】べる ものではない。":"Kekeliruan Logika: Makan saat lapar adalah kebutuhan fisiologis normal, bukan larangan moral."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat apresiasi desain:",sentencePrompt:"Susunlah frasa-frasa berikut:",options:["この デザインには 目【め】を 見張【みは】る ものが ありますね","目【め】を 見張【みは】る この デザインには ありますね ものが","ものが ありますね この デザインには 目【め】を 見張【みは】る","この デザインには ありますね ものが 目【め】を 見張【みは】る"],correctAnswer:"この デザインには 目【め】を 見張【みは】る ものが ありますね",explanation:"Urutan baku: Frasa topik objek apresiasi (このデザインには) + idiom verba (目を見張る) + pola penutup rasa (ものがありますね).",diagnosticFeedback:{"目【め】を 見張【みは】る この デザインには ありますね ものが":"Kekeliruan Urutan: Pola penutup terpisah dan terlempar acak.","ものが ありますね この デザインには 目【め】を 見張【みは】る":"Predikat di Depan: Meletakkan predikat rasa sebelum subjek penjelas.","この デザインには ありますね ものが 目【め】を 見張【みは】る":"Verba Terbalik: Verba modifikasi arimasu ditaruh mendahului nomina mono."},tokens:["この デザインには","目【め】を 見張【みは】る","ものが","ありますね"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Komitmen Mutu & Etika): Saat Sakura mengingatkan: 「コスト削減のために 強度計算を 妥協するようなことは、プロとして 決して すべきものではありませんよ」, apa respons terbaik Anda?",sentencePrompt:"Pilihlah tanggapan yang menunjukkan kepatuhan etis tertinggi:",options:["もちろんです！ 美【うつく】しさと 同時【どうじ】に 耐震【たいしん】基準【きじゅん】を 完璧【かんぺき】に 満【み】たすよう、厳格【げんかく】に 検証【けんしょう】を 重【かさ】ねてまいります。","バレなければ 大丈夫【だいじょうぶ】ですよ。柱【はしら】を 半分【はんぶん】に 削【けず】って 浮【う】いた お金【かね】で 焼肉【やきにく】を 食【た】べましょう！","強度【きょうど】なんて どうでもいいです。見【み】た目【め】さえ カッコよければ お客【きゃく】さんは 騙【だま】せますから。","さくらさん、そんな 面倒【めんどう】な 計算【けいさん】、自分【じぶん】で やれば いいじゃないですか。"],correctAnswer:"もちろんです！ 美【うつく】しさと 同時【どうじ】に 耐震【たいしん】基準【きじゅん】を 完璧【かんぺき】に 満【み】たすよう、厳格【げんかく】に 検証【けんしょう】を 重【かさ】ねてまいります。",explanation:"Menjunjung tinggi standar keselamatan publik dan menolak kompromi mutu demi keuntungan sepihak.",diagnosticFeedback:{"バレなければ 大丈夫【だいじょうぶ】ですよ。柱【はしら】を 半分【はんぶん】に 削【けず】って 浮【う】いた お金【かね】で 焼肉【やきにく】を 食【た】べましょう！":"Kriminal & Fatal: Mengurangi struktur penyangga gedung membahayakan nyawa manusia dan merupakan kejahatan.","強度【きょうど】なんて どうでもいいです。見【み】た目【め】さえ カッコよければ お客【きゃく】さんは 騙【だま】せますから。":"Penipuan Konsumen: Niat menipu pelanggan merusak seluruh kehormatan profesi arsitek.","さくらさん、そんな 面倒【めんどう】な 計算【けいさん】、自分【じぶん】で やれば いいじゃないですか。":"Sikap Pembangkang: Menolak arahan verifikasi keselamatan dari konsultan senior."}}],can_do_challenge:{statement:"Bisa mengevaluasi karya inovasi arsitektur ramah lingkungan dan mengingatkan batasan etika penghematan biaya produksi.",situation:"Studio Desain Shibuya, Lantai 5, pukul 11.30",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ものではない!",modelAnswer:"ありがとうございます！ 日本【にほん】の 伝統【でんとう】工法【こうほう】と インドネシアの 素材【そざい】の 調和【ちょうわ】を 意識【いしき】して 設計【せっけい】いたしました。",modelAnswerId:"Terima kasih banyak! Saya merancangnya dengan penuh kesadaran akan keselarasan antara teknik tradisional Jepang dan material Indonesia.",culturalEtiquette:'Dalam dunia desain Jepang, memuji dengan "miryoku-teki na mono ga arimasu" terdengar jauh lebih elegan dan berwibawa daripada sekadar mengatakan "sugoi desu".',skillUnlocked:["Menguasai formulasi pola 〜ものではない","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Penilaian Subjektif, Hakikat Alami & Kesan Mendalam"]},pocket_summary:{keyFormula:"A-i / Na-na / V-dict + ものがある (memiliki daya tarik / nuansa yang sangat terasa), V-dict + ものではない (tidak selayaknya ... tidak patut secara etis)",coreWords:["洗練【せんれん】","工夫【くふう】 (inovasi kecil, kreativitas, akal-akalan yang cerdas)","配慮【はいりょ】 (perhatian/pertimbangan terhadap orang lain, kepedulian)","歓声【かんせい】 (bersorak; teriakan kegembiraan)"],coreWarning:"Hindari memakai 〜ものではない untuk menggurui atasan secara langsung di forum publik karena terdengar seperti mendikte moralitas lawan bicara.",quickDialogue:"A: ブディさん、この 竹【たけ】と 木材【もくざい】を... → B: ありがとうございます！ 日本【にほん】の 伝統【で..."}},"les-n2-u07-02":{pedagogical_framework:{what:{summary:"Menguasai keyakinan analisis pakar: 〜に相違ない (pasti tak diragukan lagi berakar pada data) dan pengajuan hipotesis persuasif: 〜ではないか / 〜ではないだろうか (bukankah ada kemungkinan / saya meyakini bahwa...).",canDo:"Bisa mempresentasikan proyeksi penerimaan pasar atas inovasi produk dengan argumentasi logis yang meyakinkan investor.",targetPatterns:["V / A / Na / N + に相違ない (pasti demikian ... tiada keraguan sedikit pun)","V-plain / N + ではないか / ではないだろうか (bukankah ... mengajukan sudut pandang persuasif)"],coreVocabSample:["革新【かくしん】する","需要【じゅよう】","見通【みとお】し","競合【きょうごう】","優位性【ゆういせい】","提案【ていあん】","市場【しじょう】","普及【ふきゅう】する"]},sensei_context:{sceneIntro:"Ruang presentasi studio Shibuya. Sakura mendengarkan pemaparan Budi mengenai analisis proyeksi penjualan furnitur bambu ramah lingkungan ke pasar perkantoran Tokyo.",dailyMission:'Gunakan "ni soui nai" untuk menegaskan keunggulan komparatif produk dan ajukan hipotesis ekspansi dengan "de wa nai darou ka".',whyOrder:"Dalam wacana formal N2, meyakinkan pemangku kepentingan membutuhkan perpaduan antara kepastian berbasis data (ni soui nai) dan nada diplomatis persuasif (de wa nai ka)."},cultural_notes:{title:"Keyakinan Berwibawa (確信の表明) dan Retorika Persuasif (説得のレトリック)",etiquette:"Gunakan 〜に相違ない dalam presentasi resmi untuk menunjukkan kepercayaan diri penuh atas riset yang dilakukan.",taboos:"Hindari memakai kalimat bernada mutlak tanpa disertai data lampiran pendukung dalam rapat dewan direksi."},pronunciation_tips:{title:'Tempo Penegasan "Ni Soui Nai"',moraNote:'Lafalkan "ni sou-i nai" dengan ritme tegas pada kata sou-i untuk mencerminkan kepastian yang tak tergoyahkan.',soundTip:'Pada "de wa nai darou ka", gunakan intonasi naik-turun halus untuk mengundang kesepakatan audiens.'},common_pitfalls:[{title:"Tertukar Antara 〜に相違ない (Ragam Tulisan/Resmi) vs 〜に違いない (Ragam Percakapan Umum)",caseScenario:"Memakai ni soui nai dalam obrolan santai sehari-hari antar teman.",pitfallWarning:"明日【あした】 雨【あめ】が 降【ふ】るに 相違【そうい】ない よ。 (Terlalu kaku/arkais untuk obrolan santai)",rightSolution:"明日【あした】 雨【あめ】が 降【ふ】るに 違【ちが】いない よ。 (Tepat dalam ragam lisan)",explanation:"〜に相違ない adalah padanan formal dan tertulis dari 〜に違いない, sangat tepat dipakai dalam dokumen, pidato resmi, atau laporan bisnis."},{title:"Salah Nada Mengira 〜ではないか sebagai Pertanyaan Bingung",caseScenario:"Menganggap de wa nai ka sebagai pertanyaan yang tidak tahu jawabannya.",pitfallWarning:"これ、何【なに】ではないか？ (Salah)",rightSolution:"新【あたら】しい チャンスでは ないだろうか。 (Tepat: penegasan pendapat)",explanation:"Pola 〜ではないか / 〜ではないだろうか bukan pertanyaan yang menanti jawaban, melainkan teknik retorika persuasif untuk menyatakan pendapat pembicara sendiri secara halus."}],who_and_when:{situational_context:"Presentasi proposal bisnis, analisis kompetitor pasar modal, dan sidang penentuan strategi korporat.",social_relations:"Pemaparan analis bisnis junior di hadapan mitra konsultasi strategis.",when_not_to_use:"Jangan gunakan pada dugaan spekulatif yang sama sekali tidak memiliki dasar fakta empiris."},scenario:{title:"Pemaparan Studi Kelayakan Pasar Shibuya",setting:"Ruang Pitching Investor Shibuya, pukul 16.00",narrative:"Budi memaparkan data tren pembelian konsumen generasi muda yang condong memilih material ramah lingkungan."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Konsultan Manajemen",avatar:"👩‍🏫",jp:"ブディさん、若年【じゃくねん】層【そう】の エコ意識【いしき】の 高【たか】まりを 見【み】ると、この 商品【しょうひん】の 需要【じゅよう】は 今後【こんご】さらに 拡大【かくだい】するに 相違【そうい】ありませんね。",furigana:"ブディさん、若年層の エコ意識の 高まりを 見ると、この 商品の 需要は 今後さらに 拡大するに 相違ありませんね。",romaji:"Budi-san, jakunensou no eko ishiki no takamari o miru to, kono shouhin no juyou wa kongo sarani kakudai suru ni soui arimasen ne.",idText:"Budi, melihat meningkatnya kesadaran lingkungan di kalangan generasi muda, permintaan produk ini ke depannya pasti akan semakin meluas tanpa diragukan lagi ya."},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、さくらさん！ アンケート調査【ちょうさ】の 結果【けっか】からも、８割【はちわり】以上【いじょう】の 企業【きぎょう】が 導入【どうにゅう】に 前向【まえむ】きであるに 相違【そうい】ありません。",furigana:"はい、さくらさん！ アンケート調査の 結果からも、８割以上の 企業が 導入に 前向きであるに 相違ありません。",romaji:"Hai, Sakura-san! Ankeeto chousa no kekka kara mo, hachiwari ijou no kigyou ga dounyuu ni maemuki de aru ni soui arimasen.",idText:"Ya, Sakura-san! Dari hasil survei kuesioner pun, tak diragukan lagi bahwa lebih dari 80% perusahaan bersikap positif terhadap adopsi produk ini."},{id:"d3",speaker:"Sakura",speakerRole:"Konsultan Manajemen",avatar:"👩‍🏫",jp:"であれば、オフィス空間【くうかん】向【む】けの パッケージ提案【ていあん】を 同時【どうじ】に 進【すす】めるべきでは ないでしょうか。",furigana:"であれば、オフィス空間向けの パッケージ提案を 同時に 進めるべきでは ないでしょうか。",romaji:"De areba, ofisu kuukan muke no pakkeeji teian o douji ni susumerubeki dewa nai darou ka.",idText:"Jika demikian, bukankah kita selayaknya memajukan proposal paket penataan ruang kantor secara bersamaan?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"大変【たいへん】示唆【しさ】に 富【と】む ご提案【ていあん】です！ 早速【さっそく】、法人【ほうじん】向【む】けの カタログ構成【こうせい】案【あん】を 作成【さくせい】いたします。",furigana:"大変示唆に 富む ご提案です！ 早速、法人向けの カタログ構成案を 作成いたします。",romaji:"Taihen shisa ni tomu goteian desu! Sassoku, houjin muke no katarogu kouseian o sakusei itashimasu.",idText:"Saran yang sangat kaya akan wawasan! Segera, saya akan menyusun draf struktur katalog khusus untuk korporasi."}],vocab_breakdown:[{id:"vg-n2-01905",word:"プリント",reading:"プリント",romaji:"purinto",meaning:"mencetak; selebaran",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を プリント (objek tindakan kerja/bisnis).",exampleSentence:{jp:"先生は生徒たちにプリントを配布した。",furigana:"先生は生徒たちにプリントを配布した。",romaji:"purinto",idText:"Guru membagikan handout kepada siswa."},pitch:{pattern:0,category:"heiban",mora_count:0,downstep_mora:0,contour:"￣"}},{id:"vg-n2-01906",word:"振舞う",reading:"ふるまう",romaji:"furumau",meaning:"berperilaku",pos:"verb-u",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi umum: 〜の 振舞う / 〜に関する 振舞う dalam wacana profesional.",exampleSentence:{jp:"学生であるならそのように振舞いなさい。",furigana:"学生であるならそのように振舞いなさい。",romaji:"furumau",idText:"Jika Anda seorang pelajar, bersikaplah seperti itu."},pitch:{pattern:3,category:"nakadaka",mora_count:4,downstep_mora:3,contour:"フルマ＼ウ"}},{id:"vg-n2-01910",word:"ふわふわ",reading:"ふわふわ",romaji:"fuwafuwa",meaning:"ringan; lembut",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を ふわふわ (objek tindakan kerja/bisnis).",exampleSentence:{jp:"寝不足で足元がふわふわしています。",furigana:"寝不足で足元がふわふわしています。",romaji:"fuwafuwa",idText:"Jalanku tidak stabil karena kurang tidur."},pitch:{pattern:1,category:"atamadaka",mora_count:0,downstep_mora:1,contour:"＼"}},{id:"vg-n2-01911",word:"噴火",reading:"ふんか",romaji:"funka",meaning:"letusan",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 噴火 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"その火山は今年２度噴火した。",furigana:"その火山は今年２度噴火した。",romaji:"funka",idText:"Gunung berapi tersebut telah meletus dua kali tahun ini."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"フンカ￣"}},{id:"vg-n2-01912",word:"分解",reading:"ぶんかい",romaji:"bunkai",meaning:"analisis; pembongkaran",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 分解 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"時計を分解するのは組み立てるより簡単だ。",furigana:"時計を分解するのは組み立てるより簡単だ。",romaji:"bunkai",idText:"Membongkar jam tangan lebih mudah daripada merakitnya."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ブンカイ￣"}},{id:"vg-n2-01918",word:"分布",reading:"ぶんぷ",romaji:"bunpu",meaning:"distribusi",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 分布 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"この種の昆虫は日本に広く分布している。",furigana:"この種の昆虫は日本に広く分布している。",romaji:"bunpu",idText:"Serangga ini tersebar luas di seluruh Jepang."},pitch:{pattern:0,category:"heiban",mora_count:3,downstep_mora:0,contour:"ブンプ￣"}},{id:"vg-n2-01922",word:"分類",reading:"ぶんるい",romaji:"bunrui",meaning:"klasifikasi",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 分類 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"彼は書類の分類を終えた。",furigana:"彼は書類の分類を終えた。",romaji:"bunrui",idText:"Dia selesai memilah kertas."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ブンルイ￣"}},{id:"vg-n2-01923",word:"閉会",reading:"へいかい",romaji:"heikai",meaning:"penutupan",pos:"verb-suru",nuance:"Kosakata level N2: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Kolokasi alami: 〜を 閉会 (objek tindakan kerja/bisnis).",exampleSentence:{jp:"国会は閉会して夏休みに入った。",furigana:"国会は閉会して夏休みに入った。",romaji:"heikai",idText:"Diet meningkat untuk istirahat musim panas."},pitch:{pattern:0,category:"heiban",mora_count:4,downstep_mora:0,contour:"ヘイカイ￣"}}],explanations:[{id:"exp-1",grammarId:"gn2-00129",title:"Pola: 〜ということになっている",formula:"Clause + ということになっている",meaning:"sudah menjadi aturan bahwa ... / secara tidak tertulis ...",nuanceNotes:"〜ということになっている menyatakan bahwa sesuatu telah menjadi aturan, kesepakatan, atau norma yang berlaku — baik tertulis maupun tak tertulis.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ということになっている",idText:"sudah menjadi aturan bahwa ... / secara tidak tertulis ..."}],examples:[{jp:"ここでは靴を脱ぐということになっている。",romaji:"",idText:"Di sini sudah menjadi aturan bahwa harus melepas sepatu."},{jp:"会議の費用は会社が負担するということになっている。",romaji:"",idText:"Sudah menjadi ketentuan bahwa biaya rapat ditanggung perusahaan."}]},{id:"exp-2",grammarId:"gn2-00130",title:"Pola: 〜とは限らない",formula:"V-plain / Adj-plain / N + とは限らない",meaning:"tidak selalu ... / belum tentu ...",nuanceNotes:"〜とは限らない menyatakan bahwa sesuatu tidak selalu benar atau tidak bisa dipastikan — menyanggah generalisasi atau asumsi.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜とは限らない",idText:"tidak selalu ... / belum tentu ..."}],examples:[{jp:"有名な人が優れているとは限らない。",romaji:"",idText:"Belum tentu orang yang terkenal itu unggul."},{jp:"高い薬が効くとは限らない。",romaji:"",idText:"Belum tentu obat yang mahal itu ampuh."}]},{id:"exp-3",grammarId:"gn2-00139",title:"Pola: 〜によれば / 〜によると",formula:"N + によれば / N + によると",meaning:"menurut ..., berdasarkan informasi dari ...",nuanceNotes:"〜によれば dan 〜によると digunakan untuk mengutip sumber informasi — berita, laporan, ucapan seseorang, dsb. Biasanya diikuti oleh pernyataan atau klaim yang berasal dari sumber tersebut.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜によれば / 〜によると",idText:"menurut ..., berdasarkan informasi dari ..."}],examples:[{jp:"天気予報によると、明日は雨が降るそうだ。",romaji:"",idText:"Menurut prakiraan cuaca, besok katanya akan hujan."},{jp:"報告書によれば、今年の売上は前年比で増加した。",romaji:"",idText:"Menurut laporan tersebut, penjualan tahun ini meningkat dibandingkan tahun lalu."}]},{id:"exp-4",grammarId:"gn2-00149",title:"Pola: 〜に違いない",formula:"V-plain / い-Adj-plain / な-Adj + に違いない / N + に違いない",meaning:"pasti ..., tidak diragukan lagi ..., tentu saja ...",nuanceNotes:"〜に違いない menyatakan keyakinan kuat dari penutur bahwa sesuatu pasti benar, berdasarkan bukti atau intuisi yang kuat. Tidak ada keraguan di benak penutur.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜に違いない",idText:"pasti ..., tidak diragukan lagi ..., tentu saja ..."}],examples:[{jp:"あの電気は消えていない。まだ誰かいるに違いない。",romaji:"",idText:"Lampunya masih menyala. Pasti masih ada seseorang di dalam."},{jp:"彼女がそんなことをするはずがない。何か理由があるに違いない。",romaji:"",idText:"Tidak mungkin dia melakukan hal itu. Pasti ada alasan tertentu."}]},{id:"exp-5",grammarId:"gn2-00152",title:"Pola: 〜ということになっている",formula:"Clause + ということになっている",meaning:"sudah diputuskan/berlaku ketentuan bahwa ..., secara tidak tertulis sudah ...",nuanceNotes:"〜ということになっている menyatakan bahwa sesuatu telah menjadi aturan, konvensi, atau norma yang berlaku dalam suatu kelompok atau masyarakat — baik tertulis maupun tidak tertulis.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ということになっている",idText:"sudah diputuskan/berlaku ketentuan bahwa ..., secara tidak tertulis sudah ..."}],examples:[{jp:"この会社では、上司より先に帰ってはいけないということになっている。",romaji:"",idText:"Di perusahaan ini sudah menjadi norma bahwa karyawan tidak boleh pulang sebelum atasan."},{jp:"入社した社員は最初の一年は現場研修をするということになっている。",romaji:"",idText:"Sudah menjadi ketentuan bahwa karyawan baru menjalani pelatihan lapangan selama satu tahun pertama."}]},{id:"exp-6",grammarId:"gn2-00153",title:"Pola: 〜とは限らない",formula:"V-plain / い-Adj-plain / な-Adj + とは限らない / N + とは限らない",meaning:"tidak selalu ..., belum tentu ..., tidak bisa dipastikan ...",nuanceNotes:"〜とは限らない menyatakan bahwa suatu generalisasi atau asumsi tidak selalu berlaku — ada pengecualian atau kemungkinan yang berbeda. Digunakan untuk menyangkal kepastian atau pukul rata.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜とは限らない",idText:"tidak selalu ..., belum tentu ..., tidak bisa dipastikan ..."}],examples:[{jp:"一生懸命勉強すれば合格できるとは限らない。",romaji:"",idText:"Belum tentu belajar keras selalu menjamin kelulusan."},{jp:"外国語が話せるとは限らないから、通訳を用意した方がいい。",romaji:"",idText:"Belum tentu mereka bisa berbahasa asing, jadi lebih baik siapkan penerjemah."}]},{id:"exp-7",grammarId:"gn2-00155",title:"Pola: 〜わけにはいかない",formula:"V-dictionary + わけにはいかない / V-ない + わけにはいかない",meaning:"tidak bisa begitu saja ..., tidak mungkin tidak ..., tidak ada alasan untuk tidak ...",nuanceNotes:"〜わけにはいかない menyatakan bahwa sesuatu tidak dapat dilakukan karena alasan moral, sosial, atau situasional yang kuat — meski ada keinginan untuk melakukannya. Bentuk negatif (ないわけにはいかない) menyatakan ketidakmampuan untuk tidak melakukan sesuatu.",patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜わけにはいかない",idText:"tidak bisa begitu saja ..., tidak mungkin tidak ..., tidak ada alasan untuk tidak ..."}],examples:[{jp:"大事な会議があるから、休むわけにはいかない。",romaji:"",idText:"Ada rapat penting, jadi tidak bisa begitu saja absen."},{jp:"頼まれた以上、断るわけにはいかない。",romaji:"",idText:"Karena sudah dimintai tolong, tidak mungkin menolaknya."}]},{id:"exp-8",grammarId:"gn2-00156",title:"Pola: 〜ないものでもない",formula:"V-ない + ものでもない",meaning:"bukan tidak mungkin ..., bisa saja ..., tidak mustahil ...",nuanceNotes:'〜ないものでもない adalah ungkapan negatif ganda yang menyatakan kemungkinan dengan nada ragu-ragu atau hati-hati — "tidak bisa dikatakan tidak mungkin". Menyiratkan kesediaan atau kemungkinan yang kecil namun ada.',patternLogic:"Perhatikan susunan klausa pendahulu dan keterikatan logika predikat penutup.",particleNotes:"Partikel penanda memperjelas relasi semantik antar proposisi kalimat.",formVariations:[{label:"Bentuk Standar",jp:"〜ないものでもない",idText:"bukan tidak mungkin ..., bisa saja ..., tidak mustahil ..."}],examples:[{jp:"条件次第では、協力できないものでもない。",romaji:"",idText:"Tergantung kondisinya, bukan tidak mungkin saya bisa membantu."},{jp:"彼の言い分にも、一理あらないものでもない。",romaji:"",idText:"Bukan berarti argumennya sama sekali tidak ada benarnya."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "需要 (じゅよう)" dalam riset bisnis?',sentencePrompt:'Istilah "市場【しじょう】の 需要【じゅよう】" bermakna:',options:["Kebutuhan atau permintaan pasar atas barang/jasa tertentu","Penutupan pabrik secara massal akibat pailit","Pembuangan limbah beracun ke sungai","Keterlambatan pengiriman paket pos internasional"],correctAnswer:"Kebutuhan atau permintaan pasar atas barang/jasa tertentu",explanation:'"需要 (じゅよう)" bermakna permintaan pasar (demand), berlawanan dengan penawaran (供給 - kyoukyuu).',diagnosticFeedback:{"Penutupan pabrik secara massal akibat pailit":"Salah: Pailit adalah 倒産 (tousan) atau 破産 (hasan).","Pembuangan limbah beracun ke sungai":"Salah: Pembuangan limbah adalah 産業廃棄物の投棄 (sangyou haikibutsu no touki).","Keterlambatan pengiriman paket pos internasional":"Salah: Keterlambatan pengiriman adalah 配送遅延 (haisou chien)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat dengan pola kepastian formal berbasis bukti:",sentencePrompt:"これだけの 証拠【しょうこ】が 揃【そろ】っている 以上【いじょう】、彼【かれ】の 主張【しゅちょう】が 正【ただ】しいに [　　]。",options:["相違【そうい】ない","ものがある","ものではない","次第【しだい】だ"],correctAnswer:"相違【そうい】ない",explanation:"〜に相違ない menyatakan kepastian mutlak yang didukung bukti kuat (pasti benar tanpa keraguan).",diagnosticFeedback:{ものがある:"Kekeliruan Nuansa: 〜ものがある bermakna memiliki kesan mendalam, bukan kesimpulan kepastian fakta.",ものではない:"Kekeliruan Pola: 〜ものではない menyatakan larangan moral, tidak cocok dengan kata benar (tadashii).","次第【しだい】だ":"Kekeliruan Makna: 〜次第だ bermakna tergantung pada, bertentangan dengan kepastian mutlak bukti lengkap."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Retorika Persuasif): Manakah kalimat yang menggunakan 〜ではないだろうか untuk mengajukan opini secara santun?",sentencePrompt:"Pilihlah kalimat yang menggunakan 〜ではないだろうか secara tepat:",options:["今【いま】こそ 新【あたら】しい 市場【しじょう】へ 挑戦【ちょうせん】すべきでは ないだろうか。","今【いま】何時【なんじ】では ないだろうか。","彼【かれ】は 誰【だれ】では ないだろうか。","ここが 東京【とうきょう】では ないだろうか、教【おし】えてください。"],correctAnswer:"今【いま】こそ 新【あたら】しい 市場【しじょう】へ 挑戦【ちょうせん】すべきでは ないだろうか。",explanation:"〜ではないだろうか digunakan untuk mengajukan gagasan atau opini pembicara secara persuasif dan elegan (bukankah saatnya kita menantang pasar baru).",diagnosticFeedback:{"今【いま】何時【なんじ】では ないだろうか。":"Kekeliruan Fungsi: Menanyakan jam adalah pertanyaan fakta langsung, tepatnya 今何時ですか.","彼【かれ】は 誰【だれ】では ないだろうか。":"Kekeliruan Fungsi: Menanyakan identitas orang adalah pertanyaan informasi, tepatnya 彼は誰ですか.","ここが 東京【とうきょう】では ないだろうか、教【おし】えてください。":"Kekeliruan Pragmatik: Pola ini bukan untuk meminta informasi arah jalan yang tidak diketahui pembicara."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun frasa-frasa berikut menjadi kalimat pernyataan kepastian pasar:",sentencePrompt:"Susunlah frasa-frasa berikut:",options:["この 商品【しょうひん】の 需要【じゅよう】は 拡大【かくだい】するに 相違【そうい】ありません","拡大【かくだい】するに 相違【そうい】ありません この 商品【しょうひん】の 需要【じゅよう】は","需要【じゅよう】は 相違【そうい】ありません この 商品【しょうひん】の 拡大【かくだい】するに","この 商品【しょうひん】の 相違【そうい】ありません 拡大【かくだい】するに 需要【じゅよう】は"],correctAnswer:"この 商品【しょうひん】の 需要【じゅよう】は 拡大【かくだい】するに 相違【そうい】ありません",explanation:"Urutan baku: Topik subjek (この商品の需要は) + predikat verba (拡大するに) + penutup kepastian formal (相違ありません).",diagnosticFeedback:{"拡大【かくだい】するに 相違【そうい】ありません この 商品【しょうひん】の 需要【じゅよう】は":"Predikat Terbalik: Meletakkan predikat di awal sebelum subjek kalimat.","需要【じゅよう】は 相違【そうい】ありません この 商品【しょうひん】の 拡大【かくだい】するに":"Sintaksis Terputus: Frasa kepastian memotong di antara subjek dan verba.","この 商品【しょうひん】の 相違【そうい】ありません 拡大【かくだい】するに 需要【じゅよう】は":"Susunan Rusak: Penutup ditempatkan sebelum kata kerja utama."},tokens:["この 商品【しょうひん】の","需要【じゅよう】は","拡大【かくだい】するに","相違【そうい】ありません"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Apresiasi Ide Strategis): Saat Sakura menyarankan: 「オフィス空間向けの パッケージ提案を 同時に 進めるべきでは ないでしょうか」, apa respons terbaik Anda?",sentencePrompt:"Pilihlah tanggapan profesional yang menyambut ide mentor dengan sigap:",options:["大変【たいへん】示唆【しさ】に 富【と】む ご提案【ていあん】です！ 早速【さっそく】、法人【ほうじん】向【む】けの カタログ構成【こうせい】案【あん】を 作成【さくせい】いたします。","そんな 余計【よけい】な 仕事【しごと】、増【ふ】やさないでください。私【わたし】は 今【いま】の ままで 十分【じゅうぶん】です。","法人【ほうじん】なんて 相手【あいて】に しても 儲【もう】かりませんよ。さくらさんは ビジネスを 分【わ】かっていませんね。","カタログを 作【つく】るのは 面倒【めんどう】ですから、さくらさんが 全部【ぜんぶ】 書【か】いてください。"],correctAnswer:"大変【たいへん】示唆【しさ】に 富【と】む ご提案【ていあん】です！ 早速【さっそく】、法人【ほうじん】向【む】けの カタログ構成【こうせい】案【あん】を 作成【さくせい】いたします。",explanation:"Mengapresiasi gagasan rekan senior (Shisa ni tomu goteian) dan langsung mengambil langkah konkret (sassoku).",diagnosticFeedback:{"そんな 余計【よけい】な 仕事【しごと】、増【ふ】やさないでください。私【わたし】は 今【いま】の ままで 十分【じゅうぶん】です。":"Malas & Menolak Berkembang: Menganggap peluang ekspansi sebagai beban merusak prospek bisnis.","法人【ほうじん】なんて 相手【あいて】に しても 儲【もう】かりませんよ。さくらさんは ビジネスを 分【わ】かっていませんね。":"Meremehkan Mentor: Menghina analisis bisnis konsultan senior adalah pelanggaran etika serius.","カタログを 作【つく】るのは 面倒【めんどう】ですから、さくらさんが 全部【ぜんぶ】 書【か】いてください。":"Melempar Pekerjaan: Menolak tugas penyusunan portofolio produk."}}],can_do_challenge:{statement:"Bisa mempresentasikan proyeksi penerimaan pasar atas inovasi produk dengan argumentasi logis yang meyakinkan investor.",situation:"Ruang Pitching Investor Shibuya, pukul 16.00",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ということになっている!",modelAnswer:"はい、さくらさん！ アンケート調査【ちょうさ】の 結果【けっか】からも、８割【はちわり】以上【いじょう】の 企業【きぎょう】が 導入【どうにゅう】に 前向【まえむ】きであるに 相違【そうい】ありません。",modelAnswerId:"Ya, Sakura-san! Dari hasil survei kuesioner pun, tak diragukan lagi bahwa lebih dari 80% perusahaan bersikap positif terhadap adopsi produk ini.",culturalEtiquette:"Gunakan 〜に相違ない dalam presentasi resmi untuk menunjukkan kepercayaan diri penuh atas riset yang dilakukan.",skillUnlocked:["Menguasai formulasi pola 〜ということになっている","Mampu menerapkan prinsip koordinasi komunikasi eksekutif Penilaian Subjektif, Hakikat Alami & Kesan Mendalam"]},pocket_summary:{keyFormula:"V / A / Na / N + に相違ない (pasti demikian ... tiada keraguan sedikit pun), V-plain / N + ではないか / ではないだろうか (bukankah ... mengajukan sudut pandang persuasif)",coreWords:["革新【かくしん】する (berinovasi, merombak atau memperbarui secara mendasar)","需要【じゅよう】 (permintaan (dalam konteks ekonomi))","見通【みとお】し (prospek, perkiraan ke depan, pandangan jauh)","競合【きょうごう】"],coreWarning:"Hindari memakai kalimat bernada mutlak tanpa disertai data lampiran pendukung dalam rapat dewan direksi.",quickDialogue:"A: ブディさん、若年【じゃくねん】層【そう】の エコ意... → B: はい、さくらさん！ アンケート調査【ちょうさ】の ..."}}};export{r as a,t as b,i as c,e as d,n as e,a as f,s as u};
